# ---------------------------------------------------------------------------
# Element supply: constrains what an environment can build
# ---------------------------------------------------------------------------

@dataclass
class ElementSupply:
    """Tracks available elements in the environment."""
    stock: Dict[str, int] = field(default_factory=dict)

    def __post_init__(self):
        if not isinstance(self.stock, dict):
            raise ValueError('ElementSupply: stock must be a dict of '
                             '{element: count}, got %r' % type(self.stock).__name__)
        for el, n in self.stock.items():
            if not isinstance(n, (int, float)) or n < 0:
                raise ValueError('ElementSupply: stock[%r] must be a '
                                 'non-negative count, got %r' % (el, n))

    @classmethod
    def earth_like(cls) -> 'ElementSupply':
        return cls(stock={'C': 999, 'N': 500, 'O': 800, 'H': 9999,
                          'S': 200, 'P': 300, 'F': 50, 'Cl': 80, 'Fe': 30, 'Mg': 40})

    @classmethod
    def silicon_world(cls) -> 'ElementSupply':
        return cls(stock={'Si': 999, 'O': 800, 'C': 100, 'H': 5000,
                          'N': 50, 'S': 300, 'F': 200, 'P': 100})

    @classmethod
    def exotic(cls) -> 'ElementSupply':
        return cls(stock={'C': 200, 'N': 200, 'O': 200, 'S': 200, 'P': 200,
                          'Si': 200, 'F': 200, 'Cl': 200, 'Br': 200, 'H': 2000})

    def can_afford(self, element_counts: Dict[str, int]) -> bool:
        for el, need in element_counts.items():
            if self.stock.get(el, 0) < need:
                return False
        return True

    def richness(self) -> float:
        """How many distinct elements are available."""
        return sum(1 for v in self.stock.values() if v > 0) / len(PERIODIC)


# ---------------------------------------------------------------------------
# Strand: double-stranded genome with complementarity and replication
# ---------------------------------------------------------------------------

class Strand:
    def __init__(self, seq: str, n_bases: int = 4):
        if n_bases not in BASE_SYSTEMS:
            raise ValueError(
                f'Strand: n_bases must be one of '
                f'{sorted(BASE_SYSTEMS)} (got {n_bases!r})')
        self.n_bases = n_bases
        self.system = BASE_SYSTEMS[n_bases]
        self.cmap = _COMPLEMENT_CACHE[n_bases]
        # Normalize case — every alphabet in the engine is uppercase, and
        # GenomeValidator already treats lowercase input as valid; without
        # this a lowercase genome would decode entirely to NOOPs.
        self.seq = seq.upper()  # sense strand
        # Epigenetic state: set of sequence indices carrying 5-methylcytosine.
        # Real biology: ~70-80% of CpG dinucleotides are methylated in
        # mammalian somatic cells; methylated promoter CpGs silence
        # transcription, and 5mC deaminates to thymine (see
        # mutate_seq_realistic's methylated_cpg path).
        self.methylated_sites: set = set()

    @classmethod
    def random(cls, length: int, n_bases: int = 4) -> 'Strand':
        bases = BASE_SYSTEMS[n_bases]['bases']
        seq = ''.join(random.choice(bases) for _ in range(length))
        return cls(seq, n_bases)

    @property
    def complement(self) -> str:
        """Complementary strand: A<->T, C<->G, X<->Y, W<->Z."""
        return ''.join(self.cmap.get(b, b) for b in self.seq)

    @property
    def paired(self) -> List[Tuple[str, str]]:
        """Returns list of (sense_base, complement_base) pairs."""
        comp = self.complement
        return list(zip(self.seq, comp))

    def pair_integrity(self) -> float:
        """Fraction of bases that have valid complements. 1.0 = perfect."""
        valid = sum(1 for b in self.seq if b in self.cmap)
        return valid / max(1, len(self.seq))

    def replicate(self) -> 'Strand':
        """Copy with error rate determined by base system complexity."""
        err = self.system['error_rate']
        new_seq = []
        for b in self.seq:
            if random.random() < err:
                # Mutation: substitute a DIFFERENT base — choosing from the
                # full alphabet silently re-picks the original with prob
                # 1/n_bases, which would understate the observed error rate.
                alts = [x for x in self.system['bases'] if x != b]
                new_seq.append(random.choice(alts or self.system['bases']))
            else:
                new_seq.append(b)
        daughter = Strand(''.join(new_seq), self.n_bases)
        # Epigenetic inheritance: DNMT1 maintenance methyltransferase copies
        # the 5mC pattern onto the daughter duplex at hemi-methylated CpGs.
        # Substitutions never change length, so site indices carry over.
        # Only marks whose CpG context survived replication persist —
        # a substitution that destroys the CG dinucleotide erases the mark.
        dseq = daughter.seq
        daughter.methylated_sites = {
            i for i in self.methylated_sites
            if i + 1 < len(dseq) and dseq[i] == 'C' and dseq[i + 1] == 'G'}
        return daughter

    def transcribe(self) -> str:
        """Sense strand -> RNA-like transcript with intron splicing (5-to-4)."""
        rna = list(self.seq)
        exon_mask = [True] * len(rna)
        for i in range(4, len(rna), 5):
            if random.random() < 0.8:
                exon_mask[i] = False
        transcript = ''.join(b for b, keep in zip(rna, exon_mask) if keep)
        return transcript if len(transcript) >= CODON_LEN else self.seq[:CODON_LEN]

    def codons(self, seed: int = None) -> List[str]:
        """Transcript -> list of 5-base codons.
        If seed is provided, uses seeded RNG for reproducible splicing."""
        if seed is not None:
            rng = random.Random(seed)
            rna = list(self.seq)
            exon_mask = [True] * len(rna)
            for i in range(4, len(rna), 5):
                if rng.random() < 0.8:
                    exon_mask[i] = False
            t = ''.join(b for b, keep in zip(rna, exon_mask) if keep)
            if len(t) < CODON_LEN:
                t = self.seq[:CODON_LEN]
            pads = (CODON_LEN - len(t) % CODON_LEN) % CODON_LEN
            t += ''.join(rng.choices(self.system['bases'], k=pads))
        else:
            t = self.transcribe()
            pads = (CODON_LEN - len(t) % CODON_LEN) % CODON_LEN
            t += ''.join(random.choices(self.system['bases'], k=pads))
        return [t[i:i+CODON_LEN] for i in range(0, len(t), CODON_LEN)]

    def codons_deterministic(self) -> List[str]:
        """Deterministic codon split (no random splicing). For translation display."""
        seq = self.seq
        pads = (CODON_LEN - len(seq) % CODON_LEN) % CODON_LEN
        seq += self.system['bases'][0] * pads
        return [seq[i:i+CODON_LEN] for i in range(0, len(seq), CODON_LEN)]

    def cpg_sites(self) -> List[int]:
        """Indices of CpG dinucleotide cytosines (C followed by G).
        Only meaningful on a real DNA alphabet."""
        if set(self.system['bases']) != set('ATCG'):
            return []
        return [i for i in range(len(self.seq) - 1)
                if self.seq[i] == 'C' and self.seq[i + 1] == 'G']

    def methylate_cpg(self, fraction: float = 0.7,
                      seed: Optional[int] = None) -> int:
        """Methylate a fraction of CpG cytosines (mammalian default ~0.7-0.8).
        Returns the number of newly marked sites.  Deterministic with seed."""
        if not 0.0 <= fraction <= 1.0:
            raise ValueError(
                f'methylate_cpg: fraction must be in [0, 1] '
                f'(got {fraction})')
        rng = random.Random(seed) if seed is not None else random
        sites = self.cpg_sites()
        new_marks = 0
        for i in sites:
            if rng.random() < fraction and i not in self.methylated_sites:
                self.methylated_sites.add(i)
                new_marks += 1
        return new_marks

    def expression_level(self) -> float:
        """Relative transcription level given promoter-region methylation.
        Methylation in the first ~20% of the sequence is treated as promoter
        silencing: full promoter methylation -> ~5% residual expression
        (real silencing is near-total but rarely absolute)."""
        if not self.methylated_sites or not self.seq:
            return 1.0
        promoter_span = max(1, int(len(self.seq) * 0.2))
        promoter_cpgs = [i for i in self.cpg_sites() if i < promoter_span]
        if not promoter_cpgs:
            return 1.0
        frac = sum(1 for i in promoter_cpgs if i in self.methylated_sites) \
               / len(promoter_cpgs)
        return max(0.05, 1.0 - 0.95 * frac)

    def info_density(self) -> float:
        """Bits per base: log2(n_bases). 4-base=2 bits, 8-base=3 bits."""
        return math.log2(self.n_bases)

    def stability_score(self) -> float:
        """Info density discounted by compounded replication error.
        Sweet spot: 4 bases. 2-base is too simple (low info density),
        6+ is unstable (errors compound per base copied).
        The (1-err)**10 factor models cumulative fidelity over a short genome;
        it makes the error penalty dominate for high-base-count systems so
        4-base comes out on top of 6-base and 8-base, matching documented
        biological intuition."""
        err = self.system['error_rate']
        info = self.info_density()
        return min(1.0, (info / 3.0) * ((1.0 - err) ** STABILITY_EXPONENT))

    def __len__(self):
        return len(self.seq)

    def __repr__(self):
        return f"Strand({self.system['name']}, len={len(self.seq)}, integrity={self.pair_integrity():.2f})"


