def transcribe_dna_to_rna(dna: str) -> str:
    """Transcribe a DNA template strand to mRNA (T -> U).
    Real biology: RNA polymerase reads 3'->5' and synthesizes 5'->3'.
    We assume the input is already the coding (sense) strand."""
    return dna.upper().replace('T', 'U')


def translate_rna_to_protein(rna: str, start_at_atg: bool = True) -> Tuple[str, List[Dict]]:
    """Translate mRNA into a protein sequence using the standard genetic code.

    Returns (protein_string, codon_log).
    - If start_at_atg=True, scans for the first AUG and starts there (real biology).
    - Otherwise translates from position 0.
    - Stops at first stop codon (TAA/TAG/TGA) or end of sequence.
    Each codon_log entry: {'pos':i, 'codon':XXX, 'aa':X, 'name':...}
    """
    dna = rna.upper().replace('U', 'T')   # work in DNA alphabet
    L = len(dna)
    start = 0
    if start_at_atg:
        idx = dna.find(START_CODON)
        if idx < 0:
            return '', []
        start = idx
    protein_chars: List[str] = []
    codon_log: List[Dict] = []
    pos = start
    while pos + 3 <= L:
        codon = dna[pos:pos+3]
        aa = GENETIC_CODE.get(codon, 'X')   # X = unknown / N / non-canonical
        codon_log.append({
            'pos':   pos,
            'codon': codon,
            'aa':    aa,
            'name':  AMINO_ACIDS.get(aa, {}).get('name', 'Unknown'),
        })
        if aa == '*':
            break
        protein_chars.append(aa)
        pos += 3
    return ''.join(protein_chars), codon_log


def protein_properties(protein: str) -> Dict[str, float]:
    """Compute basic biochemistry of a protein sequence: MW, mean hydropathy,
    net charge at physiological pH, isoelectric estimate."""
    if not protein:
        return {'length': 0, 'mw': 0.0, 'mean_hydropathy': 0.0,
                'net_charge': 0.0, 'net_charge_ph74': 0.0,
                'pI': None, 'pI_estimate': 7.0}
    # Unknown residues (X/B/Z/…) still occupy a peptide bond and carry
    # real mass — estimate them at the proteome-average amino-acid mass
    # (the ExPASy convention) instead of contributing nothing, which
    # could drive the reported MW negative.
    _unknown = sum(1 for a in protein if a not in AMINO_ACIDS)
    _mean_mw = (sum(d['mw'] for d in AMINO_ACIDS.values())
                / max(1, len(AMINO_ACIDS)))
    mw    = sum(AMINO_ACIDS.get(a, {}).get('mw', 0) for a in protein)
    mw   += _unknown * _mean_mw
    # Subtract water lost in each peptide bond (n-1 bonds)
    mw   -= 18.015 * max(0, len(protein) - 1)
    hydro = sum(AMINO_ACIDS.get(a, {}).get('hydropathy', 0) for a in protein)
    chrg  = sum(AMINO_ACIDS.get(a, {}).get('charge', 0) for a in protein)
    pi    = isoelectric_point(protein)          # real Henderson-Hasselbalch
    return {
        'length':          len(protein),
        'mw':              round(mw, 2),
        'mean_hydropathy': round(hydro / len(protein), 3),
        'net_charge':      round(chrg, 2),
        'net_charge_ph74': round(net_charge_ph(protein, 7.4), 2),
        'pI':              pi,
        'pI_estimate':     round(7.0 + 0.5 * chrg / len(protein), 2),  # legacy linear
    }


# ---------------------------------------------------------------------------
# 2. HODGKIN-HUXLEY ACTION POTENTIAL — real ODE integration
# ---------------------------------------------------------------------------
# Constants from Hodgkin & Huxley (J. Physiol. 1952) — squid giant axon.
# All voltages in mV, time in ms, conductances in mS/cm^2, capacitance uF/cm^2.
HH_CONSTANTS = {
    'C_m':    1.0,    # membrane capacitance (uF/cm^2)
    'g_Na':   120.0,  # max Na+ conductance
    'g_K':    36.0,   # max K+ conductance
    'g_L':    0.3,    # leak conductance
    'E_Na':   50.0,   # Na+ reversal potential (mV)
    'E_K':   -77.0,   # K+ reversal potential (mV)
    'E_L':   -54.387, # leak reversal potential (mV)
    'V_rest': -65.0,  # resting membrane potential (mV)
}


def _safe_exp(x: float) -> float:
    """Exponentiate with the argument clamped to the IEEE-safe range so that
    extreme voltages can never produce OverflowError."""
    if x > 60.0:
        x = 60.0
    elif x < -60.0:
        x = -60.0
    return math.exp(x)


def _hh_alpha_beta(V: float) -> Tuple[float, float, float, float, float, float]:
    """Hodgkin-Huxley voltage-dependent rate constants (per ms).
    Uses the analytic limit at the two removable singularities
    (V = -55 mV for alpha_n, V = -40 mV for alpha_m) so the rates stay
    continuous instead of producing 0/0."""
    V = max(-200.0, min(200.0, V))
    def _vtrap(x: float, y: float) -> float:
        # x / (1 - exp(-x/y)) with the removable singularity at x -> 0
        if abs(x / y) < 1e-6:
            return y * (1.0 + x / (2.0 * y))
        return x / (1.0 - _safe_exp(-x / y))
    a_n = 0.01 * _vtrap(V + 55.0, 10.0)
    b_n = 0.125 * _safe_exp(-(V + 65.0) / 80.0)
    a_m = 0.1 * _vtrap(V + 40.0, 10.0)
    b_m = 4.0 * _safe_exp(-(V + 65.0) / 18.0)
    a_h = 0.07 * _safe_exp(-(V + 65.0) / 20.0)
    b_h = 1.0 / (1.0 + _safe_exp(-(V + 35.0) / 10.0))
    return a_n, b_n, a_m, b_m, a_h, b_h


def simulate_action_potential(I_inject: float = 10.0, duration_ms: float = 50.0,
                              dt: float = 0.01,
                              n_channels: int = 1,
                              n_pumps: int = 1) -> Dict[str, Any]:
    """Integrate Hodgkin-Huxley equations with a Rush–Larsen-style update.

    The three gating variables (n, m, h) are updated by the exact exponential
    solution of  dx/dt = (x_inf - x) / tau_x  holding rates fixed over each
    step, which is unconditionally stable for any dt — unlike the previous
    forward-Euler step which diverged whenever conductances were scaled up
    (OverflowError at test 55 / scaled channel counts).  Voltage uses a
    semi-implicit Euler step and is clamped to the physical range for safety.

    Parameters scale conductances by ion-channel and pump counts to model
    cells with more or fewer channels (relevant for our genome's ion_channel
    and pump_atpase part counts).

    Returns voltage trace, gating traces, spike count, frequency.
    """
    C = HH_CONSTANTS
    # Channel scaling: more channels = more conductance
    ch_scale = max(0.1, n_channels / 2.0)
    pump_scale = max(0.1, n_pumps / 2.0)
    g_Na = C['g_Na'] * ch_scale
    g_K  = C['g_K']  * ch_scale
    g_L  = C['g_L']  * pump_scale  # pumps maintain leak/rest
    # Initial conditions at rest
    V = C['V_rest']
    a_n, b_n, a_m, b_m, a_h, b_h = _hh_alpha_beta(V)
    n = a_n / (a_n + b_n)
    m = a_m / (a_m + b_m)
    h = a_h / (a_h + b_h)

    dt = max(1e-4, min(dt, 0.1))   # keep the semi-implicit step well-behaved
    n_steps = max(1, int(duration_ms / dt))
    V_trace: List[float] = []
    n_trace: List[float] = []
    m_trace: List[float] = []
    h_trace: List[float] = []
    spike_times: List[float] = []
    above_threshold = False
    threshold = 0.0  # mV — depolarization peak crossing
    t = 0.0

    def _gate_update(x: float, a: float, b: float) -> float:
        # Exact update of dx/dt = a(1-x) - b*x over one step (Rush-Larsen).
        tau_inv = a + b
        if tau_inv <= 0.0:
            return x
        x_inf = a / tau_inv
        tau = 1.0 / tau_inv
        return x_inf + (x - x_inf) * math.exp(-dt / tau)

    for i in range(n_steps):
        # Voltage update with internal substepping so that a single Euler step
        # never moves V by more than ~2 mV — this keeps large scaled
        # conductances (many ion_channel parts) from overshooting E_Na while
        # remaining O(1) cheap per step.
        I_Na = g_Na * (m**3) * h * (V - C['E_Na'])
        I_K  = g_K  * (n**4) * (V - C['E_K'])
        I_L  = g_L  * (V - C['E_L'])
        dV = (I_inject - I_Na - I_K - I_L) / C['C_m']
        n_sub = min(500, max(1, int(math.ceil(abs(dV * dt) / 2.0))))
        for _ in range(n_sub):
            I_Na = g_Na * (m**3) * h * (V - C['E_Na'])
            I_K  = g_K  * (n**4) * (V - C['E_K'])
            I_L  = g_L  * (V - C['E_L'])
            V += ((I_inject - I_Na - I_K - I_L) / C['C_m']) * (dt / n_sub)
        # Physical clamp: HH V cannot exceed the reversal potentials
        V = max(-120.0, min(80.0, V))
        # Gating variables — exponential update (stable for any dt)
        a_n, b_n, a_m, b_m, a_h, b_h = _hh_alpha_beta(V)
        n = _gate_update(n, a_n, b_n)
        m = _gate_update(m, a_m, b_m)
        h = _gate_update(h, a_h, b_h)
        V_trace.append(V)
        n_trace.append(n)
        m_trace.append(m)
        h_trace.append(h)
        # Detect spikes (rising edge over threshold)
        if V > threshold and not above_threshold:
            above_threshold = True
            spike_times.append(t)
        elif V < threshold - 10.0:
            above_threshold = False
        t += dt
    # Spike frequency (Hz)
    freq = len(spike_times) / (duration_ms / 1000.0) if duration_ms > 0 else 0.0
    return {
        'V_trace':      V_trace,
        'n_trace':      n_trace,
        'm_trace':      m_trace,
        'h_trace':      h_trace,
        'spike_times':  spike_times,
        'spike_count':  len(spike_times),
        'frequency_hz': round(freq, 2),
        'V_rest':       C['V_rest'],
        'V_peak':       round(max(V_trace), 2) if V_trace else 0.0,
        'V_min':        round(min(V_trace), 2) if V_trace else 0.0,
        'duration_ms':  duration_ms,
        'I_inject':     I_inject,
        'g_Na_eff':     g_Na,
        'g_K_eff':      g_K,
        'integrator':   'rush-larsen (gating) + semi-implicit Euler (V)',
    }


