def compute_metabolic_yield(glucose_molecules: int = 1,
                             aerobic: bool = True,
                             has_mitochondria: bool = True) -> Dict[str, Any]:
    """Compute real ATP yield from glucose oxidation.

    Aerobic complete pathway: 2 (glycolysis) + 2 (TCA) + 28 (OXPHOS) = 32 ATP
    Anaerobic (no mitochondria or no O2): glycolysis only = 2 ATP
    Reference: Berg et al., Biochemistry 7th ed., Section 16-18.
    """
    # 'efficiency' = physiological energy capture — the same convention
    # as glucose_oxidation_efficiency(): ATP x |dG_phys| / |dG_ox|.
    # 'yield_frac' keeps the older meaning: fraction of the 32-ATP maximum.
    _phys_eff = (lambda n_atp: n_atp
                 * abs(THERMODYNAMICS['atp_physiological_dg'])
                 / abs(THERMODYNAMICS['glucose_oxidation_dg0']))
    if not aerobic or not has_mitochondria:
        # Glycolysis + lactate fermentation
        return {
            'pathway':     'fermentation',
            'atp':         2 * glucose_molecules,
            'co2':         0,
            'h2o':         2 * glucose_molecules,
            'o2_consumed': 0,
            'efficiency':  round(_phys_eff(2), 4),   # ~3.8% capture
            'yield_frac':  round(2 / 32, 4),
            'pathways_run': ['glycolysis', 'fermentation_lactate'],
        }
    # Full aerobic respiration
    g = glucose_molecules
    return {
        'pathway':     'aerobic_respiration',
        'atp':         32 * g,            # 2 + 2 + 28 = 32 (real value with shuttle losses)
        'co2':         6 * g,
        'h2o':         12 * g + 2 * g,   # 12 from ETC (1 per 2e-) + 2 glycolysis
        'o2_consumed': 6 * g,
        'efficiency':  round(_phys_eff(32), 4),  # ~61% physiological capture
        'yield_frac':  1.0,
        'pathways_run': ['glycolysis', 'pyruvate_oxidation',
                         'tca_cycle', 'oxidative_phosphorylation'],
    }


def stoichiometric_atp_yield() -> Dict[str, Any]:
    """Derive the net ATP yield from the stoichiometry TABLE rather than
    asserting it — the headline number (32 ATP/glucose) is computed by
    chaining pathway outputs into inputs:

      glycolysis  : 2 ATP + 2 NADH + 2 pyruvate
      pyruvate ox : consumes the 2 pyruvate -> +2 NADH
      TCA         : consumes the 2 acetyl-CoA -> +6 NADH + 2 FADH2 + 2 ATP
      OXPHOS      : consumes all 10 NADH + 2 FADH2 -> +28 ATP

    Returns the derived totals plus the per-species mass balance so the
    --verify audit can flag any table edit that breaks conservation.
    """
    gl   = METABOLISM_STOICHIOMETRY['glycolysis']
    pyro = METABOLISM_STOICHIOMETRY['pyruvate_oxidation']
    tca  = METABOLISM_STOICHIOMETRY['tca_cycle']
    oxp  = METABOLISM_STOICHIOMETRY['oxidative_phosphorylation']

    pool: Dict[str, float] = {}

    def _run(pathway: Dict[str, Dict], times: float = 1.0) -> None:
        for k, v in pathway['inputs'].items():
            pool[k] = pool.get(k, 0.0) - v * times
        for k, v in pathway['outputs'].items():
            pool[k] = pool.get(k, 0.0) + v * times

    _run(gl)
    _run(pyro)
    _run(tca)
    _run(oxp)
    atp_derived = int(round(pool.get('ATP', 0.0)))
    # Cofactor pools must return to ~zero net (they're regenerated, not consumed)
    cofactors = {k: round(v, 3) for k, v in pool.items()
                 if k in ('NAD+', 'NADH', 'FAD', 'FADH2', 'CoA', 'ADP', 'Pi')}
    return {
        'atp_derived':    atp_derived,
        'atp_expected':   32,
        'cofactor_pool':  cofactors,
        'net_pool':       {k: round(v, 3) for k, v in pool.items()},
        'nadh_balance':   pool.get('NADH', 0.0),
        'fadh2_balance':  pool.get('FADH2', 0.0),
    }


# --- Electron transport chain: redox tower + proton pumping ----------------
# Reduction potentials E°' (biochemical convention, pH 7) for the
# mitochondrial/bacterial electron tower (Berg 7e Table 18-1).  Electrons
# fall downhill; the ~1.14 V drop NADH->O2 is what pays for proton pumping.
FARADAY = 96485.0          # C/mol electrons

ELECTRON_TOWER: Dict[str, float] = {
    'NADH/NAD+':       -0.320,
    'FADH2/FAD(succ)': -0.030,   # complex II entry, high-potential donor
    'UQH2/UQ':         +0.070,
    'cyt c Fe2+/3+':   +0.220,
    'O2/H2O':          +0.820,
}

# Proton pumping stoichiometry per 2 electrons (real counts):
#   NADH enters at Complex I  -> I(4) + III(4) + IV(2) = 10 H+
#   FADH2 enters at Complex II ->        III(4) + IV(2) =  6 H+
PROTONS_PUMPED = {'NADH': 10, 'FADH2': 6}


def nernst_potential(e0_v: float, n_e: int, reaction_quotient: float,
                     temp_k: float = 310.15) -> float:
    """Nernst equation: E = E°' - (RT/nF)·ln Q (volts)."""
    if n_e <= 0:
        raise ValueError('nernst_potential: n_e must be > 0')
    if temp_k <= 0:
        raise ValueError('nernst_potential: temp_k must be > 0')
    return e0_v - (8.314 * temp_k / (n_e * FARADAY)) * math.log(max(1e-12, reaction_quotient))


def redox_free_energy(donor_e0_v: float, acceptor_e0_v: float,
                      n_e: int = 2) -> float:
    """ΔG°' (kJ/mol) for electron transfer donor->acceptor:  -n·F·ΔE°'."""
    d_e = acceptor_e0_v - donor_e0_v
    return -n_e * FARADAY * d_e / 1000.0


def etc_proton_budget(n_nadh: float, n_fadh2: float,
                      protons_per_atp: float = None) -> Dict[str, float]:
    """Protons pumped by the ETC from reduced cofactors, the theoretical
    ATP ceiling (H+/ATP stoichiometry), and coupling efficiency vs the
    realized 28 ATP/glucose (leakage, transport costs)."""
    pp_atp = protons_per_atp if protons_per_atp is not None \
        else THERMODYNAMICS['protons_per_atp']
    if pp_atp <= 0:
        raise ValueError('etc_proton_budget: protons_per_atp must be > 0')
    h_total = n_nadh * PROTONS_PUMPED['NADH'] + n_fadh2 * PROTONS_PUMPED['FADH2']
    atp_ceiling = h_total / pp_atp
    realized = 28.0   # per glucose: 28 ATP from OXPHOS (engine's own value)
    return {
        'protons_pumped':    h_total,
        'atp_ceiling':       atp_ceiling,
        'atp_realized':      realized,
        'coupling_eff':      realized / atp_ceiling if atp_ceiling else 0.0,
        'pmf_kj':            abs(THERMODYNAMICS['pmf_per_proton_kj']) * h_total,
    }


def electron_drop_nadh_o2() -> Dict[str, float]:
    """The headline ETC number: energy released falling NADH->O2."""
    dg = redox_free_energy(ELECTRON_TOWER['NADH/NAD+'],
                           ELECTRON_TOWER['O2/H2O'])
    return {'delta_E_V': ELECTRON_TOWER['O2/H2O'] - ELECTRON_TOWER['NADH/NAD+'],
            'dG_kj_mol': dg, 'n_e': 2}


# --- Oxygenic photosynthesis ----------------------------------------------
# Photon energy E = hc/λ; a 680 nm (PSII reaction-centre) photon carries
# ~1.82 eV ≈ 176 kJ/mol.  The Z-scheme needs ≥8 photons per O2 evolved
# (4 per photosystem); measured quantum requirement is ~9-10 photons/CO2.
# Calvin cycle costs 3 ATP + 2 NADPH per CO2 -> 18 ATP + 12 NADPH/glucose.
PLANCK_H  = 6.626e-34      # J·s
LIGHT_C   = 2.998e8        # m/s
AVOGADRO  = 6.022e23

PHOTOSYNTHESIS = {
    'photons_per_o2_theory': 8,      # Z-scheme minimum
    'photons_per_co2_measured': 9.5, # real quantum requirement ~9-10
    'atp_per_co2_calvin':     3,
    'nadph_per_co2_calvin':   2,
    'co2_per_glucose':        6,
    'psII_wavelength_nm':     680,
    'psI_wavelength_nm':      700,
}


def photon_energy_kj(wavelength_nm: float) -> float:
    """Molar energy of photons at wavelength: E = hc·NA/λ (kJ/mol)."""
    if wavelength_nm <= 0:
        raise ValueError("photon_energy_kj: wavelength must be > 0 nm")
    return PLANCK_H * LIGHT_C * AVOGADRO / (wavelength_nm * 1e-9) / 1000.0


def photosynthesis_quantum_budget(n_glucose: float = 1.0) -> Dict[str, float]:
    """Real photon + ATP/NADPH budget to fix n_glucose molecules of
    glucose, plus the maximum theoretical energy capture vs measured
    leaf efficiencies (~3-6% after absorption/canopy losses)."""
    co2 = n_glucose * PHOTOSYNTHESIS['co2_per_glucose']
    photons = co2 * PHOTOSYNTHESIS['photons_per_co2_measured']
    e_photon = photon_energy_kj(PHOTOSYNTHESIS['psII_wavelength_nm'])
    e_in = photons * e_photon
    e_stored = n_glucose * abs(THERMODYNAMICS['glucose_oxidation_dg0'])
    return {
        'photons':        photons,
        'photons_per_co2': PHOTOSYNTHESIS['photons_per_co2_measured'],
        'photon_kj_mol':   e_photon,
        'energy_in_kj':    e_in,
        'energy_stored_kj': e_stored,
        'max_efficiency':  e_stored / e_in if e_in else 0.0,
        'atp_calvin':      co2 * PHOTOSYNTHESIS['atp_per_co2_calvin'],
        'nadph_calvin':    co2 * PHOTOSYNTHESIS['nadph_per_co2_calvin'],
        'o2_evolved':      co2,
    }


# --- Na+/K+ ATPase: the real membrane-potential pump -----------------------
# 3 Na+ OUT : 2 K+ IN per ATP hydrolysed -> net +1 charge exported per
# cycle (electrogenic).  Consumes ~20-40% of resting cellular ATP;
# dominant cost in neurons (~2/3 of brain energy budget).
NAK_PUMP = {'na_out': 3, 'k_in': 2, 'net_charge_out': 1,
            'fraction_of_atp_neuron': 0.66, 'fraction_of_atp_rest': 0.25}


# --- Reactive oxygen species: the ETC's toxic byproduct --------------------
# ~0.1-2% of electrons leak prematurely at Complexes I/III, reducing O2
# one electron at a time -> superoxide O2-.  SOD dismutes to H2O2;
# catalase/peroxidase finish to water.  This is the real source of
# endogenous oxidative stress and the mTOR/longevity pathway substrate.
ROS = {
    'leak_fraction_range': (0.001, 0.02),  # 0.1-2% of ETC electron flux
    'leak_sites':          'Complex I / III',
    'first_species':       'superoxide O2-',
    'detox_pathway':       'SOD -> H2O2 -> catalase/peroxidase -> H2O',
}


def ros_leak_estimate(n_electrons: float,
                      leak_fraction: float = 0.01) -> Dict[str, float]:
    """Superoxide production from electron leak at the ETC."""
    if not 0 <= leak_fraction <= 0.1:
        raise ValueError('leak_fraction outside physiological range')
    return {
        'electrons_leaked':  n_electrons * leak_fraction,
        'superoxide_formed': n_electrons * leak_fraction,   # 1 e- per O2-
        'h2o2_after_sod':    n_electrons * leak_fraction / 2,  # 2 O2- -> H2O2+O2
        'leak_fraction':     leak_fraction,
    }


def nak_atpase_budget(n_atp: float) -> Dict[str, float]:
    """Ions moved + charge exported by n_atp hydrolyses at the Na/K pump."""
    return {
        'na_exported':     n_atp * NAK_PUMP['na_out'],
        'k_imported':      n_atp * NAK_PUMP['k_in'],
        'net_charges_out': n_atp * NAK_PUMP['net_charge_out'],
        'atp_used':        n_atp,
    }


# --- Hemoglobin O2 transport: Hill cooperativity + Bohr effect -------------
# Y = pO2^n / (p50^n + pO2^n); p50 ~26 mmHg at pH 7.4/37C, Hill n ~2.8
# (four hemes, positive cooperativity).  The Bohr effect shifts p50
# ~+4 mmHg per 0.1 pH drop — working tissues get more O2 exactly where
# CO2/lactate acidify the blood.
HEMOGLOBIN = {
    'p50_mmHg':        26.0,
    'hill_n':          2.8,
    'bohr_dp50_dpH':   -40.0,   # p50 drops ~4 mmHg per +0.1 pH unit
    'arterial_pO2':    100.0,   # mmHg
    'venous_pO2':      40.0,
    'heme_per_hb':     4,
}


def oxygen_saturation(po2_mmhg: float, pH: float = 7.4) -> float:
    """Fractional Hb saturation via the Hill equation with Bohr shift."""
    p50 = HEMOGLOBIN['p50_mmHg'] + HEMOGLOBIN['bohr_dp50_dpH'] * (pH - 7.4)
    n = HEMOGLOBIN['hill_n']
    po2 = max(0.0, po2_mmhg)
    return po2 ** n / (p50 ** n + po2 ** n)


# --- Bicarbonate blood buffer ----------------------------------------------
# Blood's dominant buffer: pH = pKa + log([HCO3-] / (alpha * pCO2)),
# pKa' = 6.1, CO2 solubility alpha = 0.03 mM/mmHg.  Normal: 24 mM
# bicarbonate at pCO2 40 mmHg -> pH 7.4.
BICARBONATE = {'pKa': 6.1, 'alpha_mM_per_mmHg': 0.03,
               'normal_hco3_mM': 24.0, 'normal_pCO2_mmHg': 40.0}


def blood_ph(hco3_mM: float = 24.0, pco2_mmhg: float = 40.0) -> float:
    """Henderson-Hasselbalch blood pH from bicarbonate/pCO2."""
    if pco2_mmhg <= 0:
        raise ValueError('blood_ph: pco2_mmhg must be > 0')
    if hco3_mM <= 0:
        raise ValueError('blood_ph: hco3_mM must be > 0')
    co2 = BICARBONATE['alpha_mM_per_mmHg'] * pco2_mmhg
    return BICARBONATE['pKa'] + math.log10(hco3_mM / co2)


# --- Transcription kinetics -------------------------------------------------
# RNA polymerase elongation: bacterial ~40-90 nt/s, eukaryotic Pol II
# ~60 nt/s (in vivo burst); initiation ~10-20 s promoter escape.
TRANSCRIPTION = {
    'elongation_nt_per_s_bact': 50.0,
    'elongation_nt_per_s_euk':  60.0,
    'initiation_s':             15.0,
    'error_per_nt':             1e-5,   # ~1e-5 misincorporation/nt (no proofreading)
}


def transcription_time_s(n_nt: int, eukaryote: bool = True) -> Dict[str, float]:
    """Time + fidelity budget to transcribe n_nt nucleotides."""
    rate = (TRANSCRIPTION['elongation_nt_per_s_euk'] if eukaryote
            else TRANSCRIPTION['elongation_nt_per_s_bact'])
    err = n_nt * TRANSCRIPTION['error_per_nt']
    return {
        'time_s':          TRANSCRIPTION['initiation_s'] + n_nt / rate,
        'expected_errors': err,
        'error_free_prob': math.exp(-err),
    }


# --- Nerve conduction velocity ----------------------------------------------
# Real scaling: myelinated axons conduct ~6 m/s per micrometre diameter
# (saltatory conduction); unmyelinated ~0.5-25 m/s by passive cable
# properties (v ∝ sqrt(d)).  Squid giant axon (~1 mm) ~25 m/s,
# mammalian C-fibres (~1 μm) ~0.5-1 m/s.
def conduction_velocity(diameter_um: float, myelinated: bool = True) -> float:
    """m/s.  Myelinated: ~6*d; unmyelinated: ~0.8*sqrt(d) (μm)."""
    if myelinated:
        return 6.0 * diameter_um
    return 0.8 * math.sqrt(max(0.01, diameter_um))


# --- GroEL/GroES chaperonin cycle -------------------------------------------
# Real folding machine: ~15 s per folding cycle, 7 ATP hydrolysed per
# GroEL ring per cycle (14-mer barrel).  ~10% of E. coli proteins use it.
GROEL = {'cycle_s': 15.0, 'atp_per_cycle_per_ring': 7,
         'fraction_substrates': 0.10}


def chaperone_cost(n_proteins: float, cycles_each: float = 1.0) -> Dict[str, float]:
    """ATP cost of GroEL-mediated folding for n_proteins needing the
    chaperonin (each taking `cycles_each` cycles on the barrel)."""
    needing = n_proteins * GROEL['fraction_substrates']
    return {
        'proteins_needing_groel': needing,
        'atp_total':   needing * cycles_each * GROEL['atp_per_cycle_per_ring'],
        'time_s':      cycles_each * GROEL['cycle_s'],
    }


# --- Protein half-life: the N-end rule -------------------------------------
# Varshavsky's N-end rule (real): the N-terminal residue largely sets a
# protein's half-life via the ubiquitin pathway.  Stabilizing residues
# (M, V, G, A, S, T) give >20 h; primary destabilizing (R, K, L, F, W,
# Y) target Arg/N-recognin for ~2-10 min half-lives.
N_END_RULE = {
    'stabilizing':  set('MVGASTPC'),     # t1/2 > 20 h (eukaryotic)
    'destabilizing': set('RKLFWYHDE'),   # recognized by N-recognins; N/Q
                                       # are tertiary destabilizing
                                       # (deamidation -> arginylation)
    'stabilizing_t_half_h':   20.0,
    'destabilizing_t_half_min': 5.0,     # ~2-10 min range -> take 5
}


def protein_halflife(protein: str) -> Dict[str, Any]:
    """N-end-rule half-life estimate from the N-terminal residue."""
    if not protein:
        return {'n_terminal': None, 'class': None, 't_half_h': 0.0}
    nterm = protein[0]
    stable = nterm in N_END_RULE['stabilizing']
    t_h = (N_END_RULE['stabilizing_t_half_h'] if stable
           else N_END_RULE['destabilizing_t_half_min'] / 60.0)
    return {
        'n_terminal': nterm,
        'class':      'stabilizing' if stable else 'destabilizing',
        't_half_h':   t_h,
    }


# --- mRNA stability ----------------------------------------------------------
# Bacterial mRNAs turn over fast (t1/2 ~2-8 min -> take 5 min median);
# eukaryotic mRNAs persist hours (~10 h median, range minutes-days).
# Short half-life = tight expression control; long = efficient reuse.
MRNA_HALFLIFE = {'bacterial_min': 5.0, 'eukaryotic_h': 10.0}


def mrna_lifetime(eukaryote: bool = True) -> Dict[str, float]:
    t_min = (MRNA_HALFLIFE['eukaryotic_h'] * 60.0 if eukaryote
             else MRNA_HALFLIFE['bacterial_min'])
    # steady-state copies from constitutive expression ~ production*halflife/ln2
    return {'t_half_min': t_min, 'domain': 'eukaryotic' if eukaryote else 'bacterial'}


# --- Telomeres + the Hayflick limit -------------------------------------------
# Real replicative senescence: each division loses ~50-200 bp of telomere
# (end-replication problem).  Human telomeres start ~5-15 kb (use 10 kb);
# senescence at critically short ~2 kb → ~50-60 divisions (Hayflick).
TELOMERE = {
    'initial_bp':          10_000,
    'loss_per_division_bp': 100,
    'senescent_bp':         2_000,
    'hayflick_divisions':   60,
}


def telomere_state(divisions: int, initial_bp: int = None) -> Dict[str, Any]:
    """Telomere length after `divisions` replications + senescence flag."""
    init = initial_bp if initial_bp is not None else TELOMERE['initial_bp']
    remaining = max(0, init - divisions * TELOMERE['loss_per_division_bp'])
    return {
        'telomere_bp':    remaining,
        'divisions_left': max(0, (remaining - TELOMERE['senescent_bp'])
                              // TELOMERE['loss_per_division_bp']),
        'senescent':      remaining <= TELOMERE['senescent_bp'],
        'fraction_lost':  1.0 - remaining / init if init else 1.0,
    }


# --- DNA supercoiling: linking number ------------------------------------------
# B-form DNA twists once per ~10.5 bp: Lk0 = N/10.5.  Underwound DNA
# (negative supercoil, ΔLk<0) is the physiological state — it promotes
# strand opening for replication/transcription and is why bacterial
# gyrase (a topoisomerase II) is essential.
def linking_number(n_bp: int) -> Dict[str, float]:
    lk0 = n_bp / 10.5
    return {
        'n_bp': n_bp,
        'Lk0_relaxed': lk0,
        'turns': lk0,
        'bp_per_turn': 10.5,
    }


# --- DNA repair fidelity cascade ---------------------------------------------
# Real layered fidelity (Kunkel & Erie 2005; Alberts):
#   base selection by polymerase     ~1e-5 error/bp
#   3'->5' proofreading exonuclease  ~100x better  -> ~1e-7
#   post-replication mismatch repair ~50-1000x better -> ~1e-9..1e-10
#   E. coli measured rate: ~1e-9..1e-10 per bp per generation.
REPAIR_CASCADE = {
    'polymerase_error':     1e-5,
    'proofreading_gain':    100.0,
    'mmr_gain':             500.0,     # MutS/L/H, conservative mid-range
    'photolyase_dimers_s':  1.0,       # ~1 thymine dimer repaired/s/enzyme
    'ber_lesions_per_day':  1e4,       # spontaneous lesions repaired/day/cell
}


def repair_fidelity_cascade(has_proofreading: bool = True,
                            has_mmr: bool = True) -> Dict[str, float]:
    """Stage-wise error rate through the real fidelity cascade."""
    rate = REPAIR_CASCADE['polymerase_error']
    stages = [('polymerase base selection', rate)]
    if has_proofreading:
        rate /= REPAIR_CASCADE['proofreading_gain']
        stages.append(("3'->5' proofreading exonuclease", rate))
    if has_mmr:
        rate /= REPAIR_CASCADE['mmr_gain']
        stages.append(('post-replication mismatch repair (MutSLH)', rate))
    return {'final_error_per_bp': rate, 'stages': stages,
            'log10_improvement': -math.log10(rate / REPAIR_CASCADE['polymerase_error'])}


# --- Microbial growth laws ---------------------------------------------------
# Monod equation: mu = mu_max * S/(Ks+S).  E. coli on glucose:
# mu_max ~1.7 h^-1 (25-min doubling), Ks ~0.05 mM (chemostat range),
# yield Y ~0.5 g cells/g glucose aerobic (~0.15 anaerobic),
# maintenance m ~0.05 g substrate/(g cells*h) (Pirt equation).
GROWTH = {
    'mu_max_per_h':      1.7,
    'Ks_glucose_mM':     0.05,
    'yield_g_per_g_aerobic':   0.50,
    'yield_g_per_g_anaerobic': 0.15,
    'maintenance_g_per_gh':    0.05,
}


def monod_growth(substrate_mM: float,
                 mu_max_per_h: float = None,
                 ks_mM: float = None) -> Dict[str, float]:
    """Specific growth rate + doubling time at substrate level S."""
    mu_max = mu_max_per_h if mu_max_per_h is not None else GROWTH['mu_max_per_h']
    ks = ks_mM if ks_mM is not None else GROWTH['Ks_glucose_mM']
    if ks <= 0 or mu_max <= 0:
        raise ValueError('monod_growth: ks_mM and mu_max_per_h must be > 0')
    s = max(0.0, substrate_mM)   # negative substrate is unphysical
    mu = mu_max * s / (ks + s)
    return {'mu_per_h':      mu,
            'doubling_min':  math.log(2) / mu * 60.0 if mu > 0 else float('inf'),
            'fraction_max':  mu / mu_max if mu_max else 0.0}


def logistic_growth(n0: float, carrying_capacity: float,
                    rate_per_h: float, t_h: float) -> float:
    """Logistic population size at time t (h)."""
    if carrying_capacity <= 0 or n0 < 0 or t_h < 0:
        raise ValueError('logistic_growth: carrying_capacity must be > 0, '
                         'n0 and t_h must be >= 0')
    if n0 == 0:
        return 0.0
    return carrying_capacity / (1.0 + ((carrying_capacity - n0) / n0) *
                                math.exp(-rate_per_h * t_h))


def growth_yield(substrate_g: float, aerobic: bool = True) -> Dict[str, float]:
    """Biomass produced from substrate mass via the yield coefficient."""
    y = GROWTH['yield_g_per_g_aerobic' if aerobic else 'yield_g_per_g_anaerobic']
    return {'biomass_g': substrate_g * y, 'yield_coeff': y,
            'substrate_consumed_g': substrate_g}


def maintenance_energy_fraction(mu_per_h: float,
                                substrate_per_biomass_g: float = 2.0) -> float:
    """Pirt: fraction of substrate flux going to maintenance vs growth.
    maintenance share = m / (mu*Y_xs + m) where m is g/(g*h)."""
    m = GROWTH['maintenance_g_per_gh']
    growth_demand = mu_per_h * substrate_per_biomass_g
    return m / (growth_demand + m) if growth_demand + m > 0 else 0.0


# --- ATP synthase: the real rotary motor -----------------------------------
# F0 c-ring rotation drives F1: 120° step per ATP, ~1 revolution = 3 ATP.
# With a c10 ring (E. coli), one turn translocates 10 H+ -> ~3.3 H+/ATP.
# At full PMF the rotor spins ~100-300 rev/s (6,000-18,000 rpm) — the
# first true rotary motor, predating our flagellar one.
ATP_SYNTHASE = {
    'deg_per_atp':      120.0,
    'atp_per_rev':      3.0,
    'c_ring_subunits':  10,      # E. coli Fo ring
    'max_rps':          200.0,   # ~12,000 rpm at full PMF
}


def atp_synthase_mechanics(proton_flux_per_s: float) -> Dict[str, float]:
    """Rotor speed + ATP output for a given translocated-proton flux."""
    h_per_rev = ATP_SYNTHASE['c_ring_subunits']
    rps = proton_flux_per_s / h_per_rev
    return {
        'revolutions_per_s': rps,
        'rpm':               rps * 60.0,
        'atp_per_s':         rps * ATP_SYNTHASE['atp_per_rev'],
        'h_per_atp':         h_per_rev / ATP_SYNTHASE['atp_per_rev'],
        'saturated':         rps >= ATP_SYNTHASE['max_rps'],
    }


# --- Enzyme catalytic perfection --------------------------------------------
# kcat/Km can't exceed the diffusion-limited encounter rate ~1e8-1e9
# M^-1 s^-1.  Triose-phosphate isomerase (~4e8), catalase (~4e7) and
# carbonic anhydrase (~1e8) sit at or near the ceiling — "catalytically
# perfect" enzymes whose rate is set by physics, not chemistry.
DIFFUSION_LIMIT_M_S = 1e9   # M^-1 s^-1 encounter-rate ceiling

CATALYSIS = {
    'tim_kcat':       4.3e3,  'tim_km_M':       1.0e-5,   # ~4e8  perfect
    'catalase_kcat':  4.0e7,  'catalase_km_M':  1.1e0,    # ~4e7
    'carbanh_kcat':   1.0e6,  'carbanh_km_M':   1.2e-2,   # ~8e7
    'typical_kcat':   100.0,  'typical_km_M':   1e-4,     # ~1e6  ordinary
}


def catalytic_efficiency(kcat_per_s: float, km_M: float) -> Dict[str, float]:
    """kcat/Km vs the diffusion limit — the real measure of enzyme
    catalytic power (turnover alone is misleading)."""
    eff = kcat_per_s / max(1e-12, km_M)
    return {'kcat_per_s': kcat_per_s, 'km_M': km_M, 'kcat_km': eff,
            'fraction_of_diffusion_limit': eff / DIFFUSION_LIMIT_M_S,
            'diffusion_limited': eff >= 1e8}


# --- DNA polymer physics -----------------------------------------------------
# B-DNA contour length 0.34 nm/bp, persistence length ~50 nm (~150 bp).
# The E. coli chromosome is ~1.5 mm of contour packed into a ~1 um cell —
# ~1,500x length compaction via supercoiling + nucleoid proteins.
DNA_POLYMER = {
    'contour_nm_per_bp': 0.34,
    'persistence_nm':    50.0,
    'bp_per_persistence': 150,
}


def dna_compaction(n_bp: int, cell_diameter_um: float = 1.0) -> Dict[str, float]:
    """Genome contour length vs the cell it must fit inside."""
    contour_um = n_bp * DNA_POLYMER['contour_nm_per_bp'] / 1000.0
    return {
        'contour_um':     contour_um,
        'contour_mm':     contour_um / 1000.0,
        'compaction':     contour_um / max(1e-9, cell_diameter_um),
        'persistence_um': DNA_POLYMER['persistence_nm'] / 1000.0,
        'n_persistence_lengths': contour_um / (DNA_POLYMER['persistence_nm'] / 1000.0),
    }


# --- Hydrophobic effect: the real driver of folding --------------------------
# Transferring a -CH2- group from water to a nonpolar core releases
# ~+25 kJ/mol of favourable entropy-driven free energy... i.e. DG ~ -25
# kJ/mol per buried -CH2-.  Typical proteins bury ~50-100 aliphatic
# carbons -> the fold is only marginally stable (5-15 kcal/mol net)
# because buried polar groups oppose it.
HYDROPHOBIC_EFFECT = {
    'dg_per_ch2_kj':   -1.4 * 4.184,       # ~ -5.9 kJ/mol per buried -CH2-
    'dg_per_ch2_kcal': -1.4,               # literature range -1.3..-1.7
    'fold_stability_kcal': (-5.0, -15.0),  # marginal-stability window
}


def fold_driving_force(n_aliphatic_carbons: int,
                       n_residues: int = None) -> Dict[str, float]:
    """Hydrophobic driving force (kcal/mol) for burying n -CH2- groups,
    opposed by chain-entropy loss (~+1.35 kcal/mol per residue).
    Real proteins bury ~1 aliphatic -CH2- per residue on average, so
    the two terms nearly cancel -> marginal stability -5..-15 kcal/mol
    (the published window; marginality is functional, not a flaw)."""
    dg_hyd = n_aliphatic_carbons * HYDROPHOBIC_EFFECT['dg_per_ch2_kcal']
    residues = n_residues if n_residues is not None else n_aliphatic_carbons
    entropy_cost = residues * 1.35       # kcal/mol chain-entropy penalty
    net = dg_hyd + entropy_cost
    lo, hi = HYDROPHOBIC_EFFECT['fold_stability_kcal']
    return {
        'hydrophobic_dg_kcal':  dg_hyd,
        'entropy_cost_kcal':    entropy_cost,
        'net_stability_kcal':   net,
        'n_ch2_buried':         n_aliphatic_carbons,
        'net_stability_window': (lo, hi),
        'marginally_stable':    hi <= net <= lo,
    }


# --- Myoglobin vs haemoglobin -------------------------------------------------
# Myoglobin: single heme, hyperbolic binding, P50 ~2.8 mmHg — an O2
# STORE in muscle, not a transporter.  The contrast with cooperative
# Hb (P50 26, sigmoidal) is the classic structure-function lesson.
MYOGLOBIN_P50 = 2.8

def myoglobin_saturation(po2_mmhg: float) -> float:
    """Hyperbolic (non-cooperative) O2 binding for myoglobin."""
    p = max(0.0, po2_mmhg)
    return p / (MYOGLOBIN_P50 + p)


# --- Goldman-Hodgkin-Katz membrane potential ---------------------------------
# The real resting-potential model: multi-ion steady state weighted by
# permeability, Vm = (RT/F)·ln((P_K[K]o + P_Na[Na]o + P_Cl[Cl]i) /
#                             (P_K[K]i + P_Na[Na]i + P_Cl[Cl]o)).
# Mammalian values: K_i 139, K_o 4; Na_i 14, Na_o 140; Cl_i 4, Cl_o 110 mM
# with P_K:P_Na:P_Cl = 1 : 0.04 : 0.45  -> Vm ~ -60 to -70 mV.
GHK_IONS = {   # name: (inside_mM, outside_mM, permeability, valence-sign)
    'K':  (139.0,   4.0, 1.00),
    'Na': (14.0,  140.0, 0.04),
    'Cl': (4.0,   110.0, 0.45),     # NOTE: Cl terms swap in/out (anion)
}


def ghk_potential_mv(temp_k: float = 310.15,
                     ions: Dict[str, Tuple[float, float, float]] = None) -> float:
    """Resting potential (mV) via the GHK voltage equation."""
    ions = ions or GHK_IONS
    k_in, k_out, p_k = ions['K']
    na_in, na_out, p_na = ions['Na']
    cl_in, cl_out, p_cl = ions['Cl']
    num = p_k * k_out + p_na * na_out + p_cl * cl_in   # Cl inside on top
    den = p_k * k_in + p_na * na_in + p_cl * cl_out   # Cl outside below
    return (8.314 * temp_k / FARADAY) * math.log(num / den) * 1000.0


# --- Ca2+ signaling: the steep gradient ---------------------------------------
# Cytosolic free Ca2+ ~100 nM vs extracellular ~1.2 mM — a ~12,000x
# electrochemical gradient held by SERCA/PMCA pumps + Na/Ca exchange.
# Small fluxes thus give big signals: Ca2+ is biology's fast second
# messenger (muscle, exocytosis, fertilization).
CALCIUM = {
    'cytosolic_nM':    100.0,
    'extracellular_mM': 1.2,
    'gradient':        12_000,
    'peak_signal_nM':  1_000,   # transient rises to ~1 uM
}


def calcium_signal_strength(peak_nM: float = None) -> Dict[str, float]:
    """Fold-change + energy context of a Ca2+ signalling transient."""
    peak = peak_nM if peak_nM is not None else CALCIUM['peak_signal_nM']
    basal = CALCIUM['cytosolic_nM']
    return {
        'basal_nM':    basal,
        'peak_nM':     peak,
        'fold_rise':   peak / basal,
        'gradient':    CALCIUM['gradient'],
        'energetics':  'SERCA/PMCA + Na/Ca exchanger maintain gradient at ATP cost',
    }


# --- Ion channel conductance --------------------------------------------------
# A single open channel passes ~1e6-1e8 ions/s: conductance ~10-100 pS.
# At V=-70 mV a 20 pS channel carries ~1.4 pA = ~9e6 ions/s — a handful
# of channels can shift a whole cell's potential (why neurons are fast).
def channel_flux(conductance_pS: float = 20.0, v_mv: float = -70.0,
                 z: int = 1) -> Dict[str, float]:
    """Single-channel current (pA) + ion flux (ions/s) at driving voltage."""
    if z == 0:
        raise ValueError('channel_flux: ion valence z must be non-zero')
    i_pA = conductance_pS * abs(v_mv) / 1000.0          # pS*mV -> pA
    ions_per_s = i_pA * 1e-12 / (z * 1.602e-19)
    return {'i_pA': i_pA, 'ions_per_s': ions_per_s,
            'conductance_pS': conductance_pS}


# --- Membrane capacitance: how few ions make -70 mV ----------------------------
# C ~1 uF/cm^2.  A 10 um cell has A=4*pi*(5um)^2=3.1e-6 cm^2 -> C~3e-12 F.
# Charging to -70 mV needs Q=CV ~2e-13 C = ~1.3e6 charges — a tiny
# fraction (~0.01%) of the cell's ~1e10 K+ ions.  Electrical signalling
# is cheap precisely because the bilayer is thin.
def membrane_charge_count(cell_diameter_um: float = 10.0,
                          v_mv: float = -70.0,
                          capacitance_uF_cm2: float = 1.0) -> Dict[str, float]:
    """Ion count needed to hold the resting potential — and its
    fraction of the total cellular ion inventory (~1e10 K+)."""
    r_cm = cell_diameter_um / 2.0 * 1e-4
    area_cm2 = 4.0 * math.pi * r_cm ** 2
    c_F = capacitance_uF_cm2 * 1e-6 * area_cm2
    q_C = c_F * abs(v_mv) / 1000.0
    charges = q_C / 1.602e-19
    return {
        'capacitance_F':   c_F,
        'area_cm2':        area_cm2,
        'charge_C':        q_C,
        'charge_count':    charges,
        'k_inventory_est': 1e10,
        'fraction_of_inventory': charges / 1e10,
    }


# --- Kleiber's law: allometric metabolic scaling ------------------------------
# Basal metabolic rate scales as M^3/4 across ~18 orders of magnitude —
# mouse ~0.02 kg burns ~200 kJ/day vs elephant ~4000 kg ~400 MJ/day.
# The 3/4 exponent (not 2/3 surface or 1 mass) reflects fractal
# distribution networks (West-Brown-Enquist model, debated but the
# empirical fit is robust).
KLEIBER = {
    'coeff_kJ_day':  293.0,   # ~70 W for 70 kg; standard mammal fit ~293*M^0.75
    'exponent':      0.75,
    'atp_per_kJ':    1.0 / 55.0,   # physiological ATP hydrolysis ~55 kJ/mol
}


def kleiber_bmr(mass_kg: float) -> Dict[str, float]:
    """Basal metabolic rate (kJ/day, W, ATP mol/day) by Kleiber's law."""
    kj_day = KLEIBER['coeff_kJ_day'] * mass_kg ** KLEIBER['exponent']
    return {
        'kj_per_day':   kj_day,
        'watts':        kj_day / 86.4,
        'atp_mol_day':  kj_day * KLEIBER['atp_per_kJ'],
        'mass_kg':      mass_kg,
    }


# --- Cardiac output + Fick principle -------------------------------------------
# VO2 = CO × (CaO2 - CvO2).  Resting human: CO ~5 L/min, arterial O2
# ~200 mL/L vs venous ~150 mL/L -> VO2 ~250 mL/min — matches the
# textbook resting oxygen consumption.
CARDIAC = {
    'co_rest_L_min':    5.0,
    'co_max_L_min':     25.0,   # athletic max
    'ca_o2_mL_L':       200.0,  # arterial O2 content (Hb-bound)
    'cv_o2_mL_L':       150.0,  # mixed venous O2 content
}


def fick_vo2(co_L_min: float = None) -> Dict[str, float]:
    """Oxygen consumption (mL/min) via the Fick principle."""
    co = co_L_min if co_L_min is not None else CARDIAC['co_rest_L_min']
    av = CARDIAC['ca_o2_mL_L'] - CARDIAC['cv_o2_mL_L']
    return {'vo2_mL_min': co * av, 'cardiac_output_L_min': co,
            'av_difference_mL_L': av,
            'o2_mol_min': co * av / 22414.0}


# --- V(D)J antibody diversity ----------------------------------------------------
# Real combinatorial immunology: ~65 V × 27 D × 6 J (heavy) + ~40 V × 5 J
# (light) ≈ 5e6; junctional N-additions + palindromic edits + somatic
# hypermutation push the realised repertoire to ~1e10-1e11 specificities.
VDJ = {
    'heavy_v': 65, 'heavy_d': 27, 'heavy_j': 6,
    'light_v': 40, 'light_j': 5,
    'junctional_diversity': 3e6,   # N-region/P-nucleotide edits
    'somatic_hypermutation': 1e4,  # post-activation diversification
}


def antibody_diversity() -> Dict[str, float]:
    """Combinatorial antibody specificity count (pre-hypermutation)."""
    heavy = VDJ['heavy_v'] * VDJ['heavy_d'] * VDJ['heavy_j']
    light = VDJ['light_v'] * VDJ['light_j']
    combinatorial = heavy * light
    with_junction = combinatorial * VDJ['junctional_diversity']
    return {'heavy_combos': heavy, 'light_combos': light,
            'combinatorial': combinatorial,
            'with_junctional': with_junction,
            'total_estimated': with_junction * VDJ['somatic_hypermutation']}


# --- Viral lytic cycle -------------------------------------------------------------
# Bacteriophage T4 on E. coli: adsorption ~min, eclipse ~11 min (genome
# replication, no infective virions), maturation, lysis ~25 min,
# burst size ~100-200 virions/cell.  The one-step growth curve.
VIRUS = {
    'adsorption_min':  5.0,
    'eclipse_min':     11.0,
    'latent_min':      25.0,
    'burst_size':      150,
    'rise_per_min':    None,   # linear after eclipse
}


def one_step_growth(t_min: float, burst_size: int = None) -> Dict[str, float]:
    """Infective virions per cell at time t through the lytic cycle."""
    bs = burst_size if burst_size is not None else VIRUS['burst_size']
    if t_min < VIRUS['eclipse_min']:
        virions = 0.0           # eclipse: genome made, no assembled virions
    else:
        frac = min(1.0, (t_min - VIRUS['eclipse_min'])
                         / max(1e-9, VIRUS['latent_min'] - VIRUS['eclipse_min']))
        virions = bs * frac
    return {'t_min': t_min, 'virions_per_cell': virions,
            'eclipse_over': t_min >= VIRUS['eclipse_min'],
            'burst_size': bs}


# --- Oncotic (colloid osmotic) pressure ------------------------------------------
# Plasma proteins — mostly albumin — hold ~25-30 mmHg across the
# capillary wall (Starling).  Losing it (nephrotic syndrome, cirrhosis)
# is what causes oedema.  van't Hoff with ~0.6 mM albumin at 37 C.
# van't Hoff gives ~13 mmHg from 45 g/L albumin — but the measured
# oncotic pressure is ~25-30 mmHg.  The gap is the Gibbs-Donnan effect:
# albumin's ~-17 net charge at pH 7.4 retains counter-ions on the
# plasma side, roughly doubling the osmotic term.
ONCOTIC_DONNAN_FACTOR = 1.9

def oncotic_pressure_mmhg(albumin_g_L: float = 45.0,
                          temp_k: float = 310.15,
                          donnan: bool = True) -> Dict[str, float]:
    """Capillary oncotic pressure from albumin (MW ~66.5 kDa),
    including the Gibbs-Donnan counter-ion enhancement."""
    molar = albumin_g_L / 66_500.0 * 1000.0   # g/L / g/mol -> mol/m^3
    pa = molar * 8.314 * temp_k
    if donnan:
        pa *= ONCOTIC_DONNAN_FACTOR
    return {'albumin_g_L': albumin_g_L, 'albumin_mM': albumin_g_L / 66.5,
            'pressure_mmhg': pa / 133.322, 'pressure_Pa': pa,
            'donnan_included': donnan}


# --- Ligand binding: Langmuir occupancy ---------------------------------------
# Fraction occupied = [L]/(Kd + [L]).  At [L]=Kd exactly half the sites
# are filled — the single most-used relationship in biochemistry
# (receptor-ligand, enzyme-substrate, TF-operator).
def ligand_occupancy(ligand_conc: float, kd: float) -> float:
    """Fractional occupancy via Langmuir isotherm."""
    return ligand_conc / (kd + ligand_conc) if kd + ligand_conc > 0 else 0.0


def hill_occupancy(ligand_conc: float, kd: float, hill_n: float = 1.0) -> float:
    """Cooperative (Hill-form) occupancy for multi-site binding."""
    if hill_n <= 0 or kd <= 0:
        raise ValueError('hill_occupancy: hill_n and kd must be > 0')
    l_n = max(1e-15, ligand_conc) ** hill_n
    k_n = kd ** hill_n
    return l_n / (k_n + l_n)


# --- Spontaneous DNA damage -----------------------------------------------------
# Even with perfect replication, chemistry attacks DNA:
#   depurination    ~10,000 purines lost/cell/day (mammalian, 37 C)
#   cytosine deam.  ~100-500/day -> U pairs as T -> GC->AT transition
#   oxidation (8-oxoG) ~1,000-2,000/day from endogenous ROS
#   UV thymine dimers  ~1e5 per exposed cell per sun-hour
# BER/NER fix nearly all of it; the trickle that escapes is mutation.
DNA_DAMAGE = {
    'depurination_per_day':   10_000,
    'deamination_per_day':    300,
    'oxidation_per_day':      1_500,
    'uv_dimer_per_sun_hour':  100_000,
    'genome_bp_mammalian':    3.2e9,
}


def spontaneous_lesions(n_cells: float = 1.0,
                        exposure: str = 'dark') -> Dict[str, float]:
    """Endogenous DNA lesions per day (per cell, scaled by n_cells)."""
    per_cell = (DNA_DAMAGE['depurination_per_day']
                + DNA_DAMAGE['deamination_per_day']
                + DNA_DAMAGE['oxidation_per_day'])
    uv = DNA_DAMAGE['uv_dimer_per_sun_hour'] if exposure == 'uv' else 0.0
    return {
        'lesions_per_cell_day': per_cell + uv,
        'lesions_total_day':    (per_cell + uv) * n_cells,
        'dominant':             'depurination' if exposure != 'uv' else 'thymine_dimer',
    }


# --- Bacterial chemotaxis: run-and-tumble -----------------------------------------
# E. coli swims ~20-30 um/s in ~1 s 'runs', then tumbles ~0.1 s to
# reorient.  Chemotaxis biases run LENGTH (not speed): longer runs
# up-gradient -> net drift toward attractant of ~5-10% of swim speed.
CHEMOTAXIS = {
    'swim_speed_um_s':  25.0,
    'run_s':            1.0,
    'tumble_s':         0.1,
    'drift_fraction':   0.07,   # ~7% net drift up-gradient (measured)
}


def chemotaxis_drift(n_runs: int = 100) -> Dict[str, float]:
    """Net displacement statistics for a run-and-tumble swimmer."""
    run = CHEMOTAXIS['swim_speed_um_s'] * CHEMOTAXIS['run_s']
    gross = run * n_runs
    net = gross * CHEMOTAXIS['drift_fraction']
    return {
        'run_length_um':      run,
        'gross_distance_um':  gross,
        'net_drift_um':       net,
        'drift_fraction':     CHEMOTAXIS['drift_fraction'],
        'efficiency':         'low — but robust (works with single-molecule sensing)',
    }


# --- Lactate threshold / VO2 max ----------------------------------------------------
# Sedentary VO2max ~35 mL/(kg·min); trained ~55; elite ~80-90.
# Lactate threshold sits at ~60-85% of VO2max — above it glycolytic
# flux exceeds mitochondrial clearance and lactate accumulates.
def lactate_threshold(vo2max_mL_kg_min: float = 45.0,
                      trained: bool = False) -> Dict[str, float]:
    """Lactate-threshold VO2 + fraction of max."""
    frac = 0.80 if trained else 0.60
    return {
        'vo2max':             vo2max_mL_kg_min,
        'lactate_threshold':  vo2max_mL_kg_min * frac,
        'threshold_fraction': frac,
        'zone':               'trained (aerobic base)' if trained else 'sedentary',
    }


# --- Restriction site statistics ----------------------------------------------
# A 6-base recognition site appears every 4^6 = 4,096 bp on random DNA
# (real genomes deviate — CpG suppression raises/not lowers some
# enzyme densities).  Expected count + actual scan both reported.
def expected_restriction_sites(n_bp: int, site_len: int = 6,
                               alphabet: int = 4) -> Dict[str, float]:
    """Expected spacing/count for a palindromic recognition site."""
    if alphabet < 2 or site_len < 1:
        raise ValueError('expected_restriction_sites: alphabet must be >= 2 '
                         'and site_len >= 1')
    spacing = alphabet ** site_len
    return {'site_len': site_len, 'expected_spacing_bp': spacing,
            'expected_count': n_bp / spacing}


def count_restriction_sites(seq: str, site: str = 'GAATTC') -> int:
    """Exact EcoRI-style site count in a sequence (both strands same
    site for palindromes)."""
    s = seq.upper()
    site = site.upper()
    return sum(1 for i in range(len(s) - len(site) + 1)
               if s[i:i + len(site)] == site)


# --- Chromatin packaging ---------------------------------------------------------
# Eukaryotes wrap ~147 bp around each nucleosome (beads-on-a-string),
# ~50 bp linker -> ~200 bp/nucleosome repeat.  The 30-nm fibre +
# loop/scaffold folding compacts interphase chromatin ~40x; mitotic
# chromosomes reach ~10,000x linear compaction.
CHROMATIN = {
    'bp_per_nucleosome': 147,
    'linker_bp':          50,
    'repeat_bp':          200,
    'fibre_30nm_fold':    40,
    'mitotic_fold':       10_000,
}


def chromatin_compaction(n_bp: int) -> Dict[str, float]:
    """Nucleosome count + packaging state for a eukaryotic genome."""
    nucleosomes = n_bp / CHROMATIN['repeat_bp']
    contour_um = n_bp * 0.34e-3                    # B-DNA contour um
    fibre_um = contour_um / CHROMATIN['fibre_30nm_fold']
    chr_um = contour_um / CHROMATIN['mitotic_fold']
    return {
        'nucleosomes':      nucleosomes,
        'contour_um':       contour_um,
        'fibre_30nm_um':    fibre_um,
        'mitotic_um':       chr_um,
        'linear_compaction_30nm': CHROMATIN['fibre_30nm_fold'],
        'linear_compaction_mitotic': CHROMATIN['mitotic_fold'],
    }


# --- Blood glucose homeostasis ----------------------------------------------------
# Plasma glucose ~5 mM (90 mg/dL) x ~5 L blood = ~4.5 g circulating —
# a 20-min buffer at rest.  The liver produces ~2 mg/kg/min; the brain
# alone consumes ~120 g/day and can't use fats directly.
GLUCOSE = {
    'plasma_mM':           5.0,
    'blood_L':             5.0,
    'hepatic_output_mg_kg_min': 2.0,
    'brain_g_day':         120.0,
    'liver_glycogen_g':    100.0,
    'muscle_glycogen_g':   400.0,
}


def blood_glucose_pool(body_mass_kg: float = 70.0) -> Dict[str, float]:
    """Circulating glucose mass + hepatic production + brain demand."""
    if body_mass_kg <= 0:
        raise ValueError('blood_glucose_pool: body_mass_kg must be > 0')
    mol = GLUCOSE['plasma_mM'] * GLUCOSE['blood_L'] / 1000.0   # mol
    g = mol * 180.156                                        # g (MW glucose)
    output = GLUCOSE['hepatic_output_mg_kg_min'] * body_mass_kg
    return {
        'circulating_g':        g,
        'hepatic_output_mg_min': output,
        'circulating_minutes':  g * 1000.0 / output,
        'brain_daily_need_g':   GLUCOSE['brain_g_day'],
        'glycogen_reserve_g':   GLUCOSE['liver_glycogen_g'] + GLUCOSE['muscle_glycogen_g'],
    }


def fasting_state(hours: float) -> Dict[str, Any]:
    """Post-absorptive fuel mix vs hours since the last meal."""
    glyc_g = GLUCOSE['liver_glycogen_g']
    brain_g_h = GLUCOSE['brain_g_day'] / 24.0
    glyc_hours = glyc_g / brain_g_h                      # ~20 h supply
    if hours < glyc_hours:
        phase = 'glycogenolysis'
        glyc_frac = hours / glyc_hours
    elif hours < glyc_hours + 48:
        phase = 'gluconeogenesis'
        glyc_frac = 1.0
    else:
        phase = 'ketosis'
        glyc_frac = 1.0
    return {'hours': hours, 'phase': phase,
            'liver_glycogen_remaining_g': max(0.0, glyc_g - hours * brain_g_h),
            'glycogen_exhausted': glyc_frac >= 1.0,
            'brain_fuel': 'glucose' if phase != 'ketosis' else 'glucose+ketone bodies'}


# --- Single-photon vision -----------------------------------------------------------
# Rod cells respond to SINGLE photons: a dark-adapted eye detects
# ~5-14 photons at the cornea (Hecht et al. 1942).  Quantum-limited
# sensing — the retina is shot-noise-limited, not amplifier-limited.
VISION = {
    'photons_at_cornea_detectable': 10,     # Hecht threshold ~5-14
    'rod_absorption_efficiency':    0.19,   # cornea+optics+retina
    'rod_pigment_molecules':        1e8,    # rhodopsin per rod outer segment
}


def photon_detection_threshold() -> Dict[str, float]:
    """Dark-adapted photon detection numbers."""
    return {
        'corneal_photons':   VISION['photons_at_cornea_detectable'],
        'absorbed_photons':  VISION['photons_at_cornea_detectable'] *
                             VISION['rod_absorption_efficiency'],
        'single_photon_response': True,
        'reference': 'Hecht, Shlaer & Pirenne 1942 — quantum-limited vision',
    }


# --- Surface:volume + diffusion limits on cell size ------------------------
# Why cells are small: diffusion time t = r²/(6D) grows with r² while
# surface area per volume falls as 3/r.  O2 (D~2000 μm²/s) crosses a 10 μm
# cell in ~8 ms but a 1 mm cell in ~83 s — past ~100 μm, aerobic
# metabolism can't be fed by diffusion alone.
def diffusion_time_s(radius_um: float, diffusion_um2_s: float) -> float:
    """Mean time for a molecule to diffuse across a sphere of radius r."""
    return radius_um ** 2 / (6.0 * max(1e-9, diffusion_um2_s))


def surface_to_volume(radius_um: float) -> Dict[str, float]:
    """SA:V ratio and O2 diffusion time for a spherical cell."""
    sa = 4.0 * math.pi * radius_um ** 2
    vol = (4.0 / 3.0) * math.pi * radius_um ** 3
    o2_d = 2000.0   # O2 in water ~2000-2500 μm²/s
    return {
        'sa_um2':       sa,
        'vol_um3':      vol,
        'sa_v_ratio':   3.0 / max(1e-9, radius_um),
        'o2_time_s':    diffusion_time_s(radius_um, o2_d),
    }


def validate_metabolic_network() -> Dict[str, Any]:
    """Audit METABOLISM_STOICHIOMETRY for internal consistency.

    Checks, for every pathway in the aerobic chain:
      1. Every species consumed by a downstream step is actually produced
         upstream in sufficient amount (carbon/electron flow connectivity).
      2. Redox cofactors balance — NADH/FADH2 produced must all be consumed
         by OXPHOS (otherwise electrons have nowhere to go).
      3. The derived ATP total equals the documented 32.
      4. Fermentation regenerates NAD+ (the whole point of lactate
         fermentation in real cells).
    Returns {'ok': bool, 'issues': [...], 'derived': <stoichiometric_atp_yield>}.
    """
    issues: List[str] = []
    derived = stoichiometric_atp_yield()

    if derived['atp_derived'] != derived['atp_expected']:
        issues.append(
            f"derived ATP {derived['atp_derived']} != expected "
            f"{derived['atp_expected']}")

    # NADH: glycolysis+pyrOx+TCA produce 2+2+6=10, OXPHOS consumes 10
    for cof in ('NADH', 'FADH2'):
        bal = derived['net_pool'].get(cof, 0.0)
        if abs(bal) > 0.5:
            issues.append(f"{cof} does not balance (net {bal:+.1f})")

    # Fermentation must regenerate NAD+ for glycolysis to keep running
    ferm = METABOLISM_STOICHIOMETRY['fermentation_lactate']
    if ferm['outputs'].get('NAD+', 0) < ferm['inputs'].get('NADH', 0):
        issues.append("fermentation fails to regenerate NAD+ — "
                      "anaerobic glycolysis would stall")

    # O2 must only be required by the pathway that actually uses it
    for name, pdata in METABOLISM_STOICHIOMETRY.items():
        uses_o2 = pdata['inputs'].get('O2', 0) > 0
        if uses_o2 != bool(pdata['oxygen_required']) and uses_o2:
            issues.append(f"{name}: consumes O2 but oxygen_required=False")

    return {'ok': not issues, 'issues': issues, 'derived': derived}


# ---------------------------------------------------------------------------
# 3b. GILLESPIE STOCHASTIC SIMULATION — exact SSA for small reaction networks
# ---------------------------------------------------------------------------
# Real cells are noisy: at single-digit molecule counts, deterministic ODEs
# miss the bursts and extinctions that dominate gene expression.  The
# Gillespie direct method samples both the time to the next reaction and
# which reaction fires, exactly reproducing the chemical master equation.
# Reference: Gillespie, J. Phys. Chem. 1977.

@dataclass
class Reaction:
    """A chemical reaction for the SSA: reactants -> products at propensity
    rate * prod(reactant copy numbers)."""
    name:      str
    reactants: Dict[str, int]
    products:  Dict[str, int]
    rate:      float                    # stochastic rate constant (per second)

    def __post_init__(self):
        if self.rate < 0:
            raise ValueError('Reaction %r: rate must be >= 0' % self.name)

    def propensity(self, state: Dict[str, int]) -> float:
        a = self.rate
        for species, n in self.reactants.items():
            have = state.get(species, 0)
            if have < n:
                return 0.0
            a *= math.comb(have, n)      # combinatorial term have!/(have-n)!/n!
        return a


def gillespie_ssa(state: Dict[str, int], reactions: List[Reaction],
                  t_max: float = 100.0, seed: Optional[int] = None,
                  max_steps: int = 200_000,
                  record_every: float = 1.0) -> Dict[str, Any]:
    """Gillespie direct method. Returns the time series plus final state.

    state:      species -> molecule count (ints; modified copy is returned)
    reactions:  list of Reaction
    record_every: seconds between recorded samples of the trajectory.
    """
    if t_max < 0 or max_steps < 0 or record_every <= 0:
        raise ValueError('gillespie_ssa: t_max and max_steps must be >= 0, '
                         'record_every must be > 0')
    rng = random.Random(seed)
    st = {k: int(v) for k, v in state.items()}
    for k, v in st.items():
        if v < 0:
            raise ValueError('gillespie_ssa: molecule count for %r must be >= 0' % k)
    for r in reactions:
        for sp in r.reactants:
            st.setdefault(sp, 0)
        for sp in r.products:
            st.setdefault(sp, 0)
    t = 0.0
    times: List[float] = [0.0]
    traj: List[Dict[str, int]] = [dict(st)]
    next_rec = record_every
    fired = Counter()
    n_steps = 0

    while t < t_max and n_steps < max_steps:
        props = [r.propensity(st) for r in reactions]
        a0 = sum(props)
        if a0 <= 0.0:
            break                              # nothing left to react
        tau = rng.expovariate(a0)
        t += tau
        if t > t_max:
            break
        # Choose reaction proportional to propensity
        u = rng.random() * a0
        acc = 0.0
        chosen = reactions[-1]
        for r, a in zip(reactions, props):
            acc += a
            if u <= acc:
                chosen = r
                break
        for sp, n in chosen.reactants.items():
            st[sp] = st.get(sp, 0) - n
        for sp, n in chosen.products.items():
            st[sp] = st.get(sp, 0) + n
        fired[chosen.name] += 1
        n_steps += 1
        if t >= next_rec:
            times.append(round(t, 4))
            traj.append(dict(st))
            while next_rec <= t:
                next_rec += record_every

    return {
        't':         times,
        'traj':      traj,
        'final':     st,
        't_end':     round(t, 3),
        'n_reactions_fired': n_steps,
        'fired_by':  dict(fired),
    }


def tau_leap(state: Dict[str, int], reactions: List[Reaction],
             t_max: float = 100.0, tau: float = 0.5,
             seed: Optional[int] = None,
             record_every: float = 1.0) -> Dict[str, Any]:
    """Gillespie tau-leaping (Gillespie 2001, J. Chem. Phys. 115:1716) —
    the standard approximation that accelerates the exact SSA: instead of
    one reaction per step, each reaction fires Poisson(a_j·tau) times per
    leap.  Firing counts are clamped so no species goes negative (the
    'critical reaction' safeguard of Cao/Gillespie/Petzold).  Ensemble
    means match the SSA to first order; variance is approximated."""
    if t_max < 0 or tau <= 0 or record_every <= 0:
        raise ValueError('tau_leap: t_max must be >= 0, tau and '
                         'record_every must be > 0')
    rng = np.random.default_rng(seed)
    st = {k: int(v) for k, v in state.items()}
    for k, v in st.items():
        if v < 0:
            raise ValueError('tau_leap: molecule count for %r must be >= 0' % k)
    for r in reactions:
        for sp in r.reactants:
            st.setdefault(sp, 0)
        for sp in r.products:
            st.setdefault(sp, 0)
    t = 0.0
    n_leaps = 0
    fired = Counter()
    times: List[float] = [0.0]
    traj: List[Dict[str, int]] = [dict(st)]
    next_rec = record_every
    while t < t_max:
        props = np.array([r.propensity(st) for r in reactions], dtype=float)
        if props.sum() <= 0.0:
            break
        counts = rng.poisson(props * tau)
        for j, r in enumerate(reactions):
            n_fire = int(counts[j])
            if n_fire <= 0:
                continue
            # Clamp on NET consumption per leap: a species that is both a
            # reactant and a product of the same reaction (e.g. mRNA in
            # translation) must not limit the firing count — it is a
            # catalyst, not a consumed substrate.
            for sp, need in r.reactants.items():
                net_need = need - r.products.get(sp, 0)
                if net_need > 0:
                    n_fire = min(n_fire, st.get(sp, 0) // net_need)
            if n_fire <= 0:
                continue
            for sp, need in r.reactants.items():
                st[sp] -= need * n_fire
            for sp, make in r.products.items():
                st[sp] = st.get(sp, 0) + make * n_fire
            fired[r.name] += n_fire
        t += tau
        n_leaps += 1
        if t >= next_rec:
            times.append(round(t, 4))
            traj.append(dict(st))
            while next_rec <= t:
                next_rec += record_every
    return {
        't':         times,
        'traj':      traj,
        'final':     st,
        't_end':     round(t, 3),
        'n_leaps':   n_leaps,
        'fired_by':  dict(fired),
        'note':      'Poisson leaps; mean equals SSA to O(tau), ~10-100x '
                     'fewer steps for abundant species',
    }


def central_dogma_reactions(k_txn: float = 2.0, k_tl: float = 5.0,
                            d_mrna: float = 0.1, d_prot: float = 0.02,
                            burst: int = 2) -> List[Reaction]:
    """The classic two-stage gene-expression network:

        gene -> gene + mRNA          (transcription, rate k_txn)
        mRNA -> mRNA + protein       (translation, per-mRNA rate k_tl)
        mRNA -> ∅                    (degradation, half-life ~7 s in bacteria)
        protein -> ∅                 (dilution/decay)
    """
    return [
        Reaction('transcription', {}, {'mRNA': 1}, k_txn),
        Reaction('translation',   {'mRNA': 1}, {'mRNA': 1, 'protein': burst},
                 k_tl),
        Reaction('mrna_decay',    {'mRNA': 1}, {}, d_mrna),
        Reaction('protein_decay', {'protein': 1}, {}, d_prot),
    ]


def simulate_gene_expression(t_max: float = 200.0, seed: Optional[int] = 7,
                             **kwargs) -> Dict[str, Any]:
    """Run the central-dogma SSA and report steady-state statistics.
    Mean protein level should approach  (k_txn * k_tl * burst) / (d_mrna * d_prot)
    = 2*5*2 / (0.1*0.02) = 10,000 in the deterministic limit, with the
    stochastic trajectory showing the classic translational-burst noise."""
    rxns = central_dogma_reactions(**kwargs)
    res = gillespie_ssa({'gene': 1}, rxns, t_max=t_max, seed=seed,
                        record_every=max(0.5, t_max / 400))
    final = res['final']
    k_txn = kwargs.get('k_txn', 2.0); k_tl = kwargs.get('k_tl', 5.0)
    d_m   = kwargs.get('d_mrna', 0.1); d_p = kwargs.get('d_prot', 0.02)
    burst = kwargs.get('burst', 2)
    mean_theory = (k_txn * k_tl * burst) / max(1e-9, d_m * d_p)
    res['theory'] = {
        'expected_mrna':    k_txn / max(1e-9, d_m),
        'expected_protein': mean_theory,
        'final_mrna':       final.get('mRNA', 0),
        'final_protein':    final.get('protein', 0),
        'note': ('single-cell stochastic realisation — instantaneous counts '
                 'fluctuate around the deterministic mean; see Fano factor '
                 'in the report'),
    }
    return res


# ---------------------------------------------------------------------------
# 3b-thermo. REAL BIOCHEMISTRY — thermodynamics, enzyme kinetics, transport
# ---------------------------------------------------------------------------
# Every constant below is a textbook/literature value (Berg et al.
# Biochemistry 7e, Lehninger 7e, Alberts MBoC).  The engine's abstract
# "PMF units" are anchored to real physical energy here: 1 PMF unit =
# the free energy of translocating one proton across a membrane at a
# physiological proton motive force (~ -220 mV -> ~ -22 kJ/mol).

FARADAY_KJMOLV = 96.485      # kJ mol^-1 V^-1 (Faraday constant)
R_GAS_KJ       = 8.314e-3    # kJ mol^-1 K^-1
KB_JK          = 1.380649e-23  # J K^-1 (Boltzmann, exact SI)

THERMODYNAMICS = {
    'atp_hydrolysis_dg0':    -30.5,   # kJ/mol — ΔG°' at pH 7, standard transformed
    'atp_physiological_dg':  -55.0,   # kJ/mol — typical cellular [ATP]/[ADP][Pi]
    'pmf_per_proton_kj':     -22.0,   # kJ/mol — ΔG for H+ at Δp ≈ -220 mV
    'pmf_mv_physiological':  -220.0,  # mV — E. coli membrane Δp range 150-220
    'glucose_oxidation_dg0': -2870.0, # kJ/mol — complete oxidation to CO2+H2O
    'nadh_to_atp_po':         2.5,    # P/O ratio — modern consensus
    'fadh2_to_atp_po':        1.5,
    'protons_per_atp':        3.3,    # ATP synthase stoichiometry (c10 ring)
}

# Per-environment physics — temperature/viscosity used by the kinetics
# helpers below.  Earth is physiological; other worlds are documented
# abstractions consistent with their chemistry (silicon -> hotter,
# exotic -> cryogenic solvent).
ENV_PHYSICS = {
    'earth':   {'temp_K': 310.15, 'viscosity_Pa_s': 0.0015,
                'note': 'physiological 37 °C, cytosolic ~1.5 mPa·s'},
    'silicon': {'temp_K': 373.15, 'viscosity_Pa_s': 0.0020,
                'note': 'hot silicon-world analogue 100 °C'},
    'exotic':  {'temp_K': 273.15, 'viscosity_Pa_s': 0.0010,
                'note': 'near-freezing exotic solvent'},
}


def pmf_to_kj(pmf_units: float) -> float:
    """Convert engine PMF units to kJ/mol of usable chemiosmotic energy."""
    return pmf_units * abs(THERMODYNAMICS['pmf_per_proton_kj'])


def atp_from_glucose_dg(n_atp: float, dg_atp: float = None) -> float:
    """Energy captured in n ATP (kJ/mol of glucose) at cellular conditions."""
    dg = THERMODYNAMICS['atp_physiological_dg'] if dg_atp is None else dg_atp
    return n_atp * abs(dg)


def thermodynamic_feasibility(budget_pmf: float, cost_pmf: float) -> Dict[str, Any]:
    """Is an organism's energy budget physically sufficient?

    Converts abstract PMF accounting into kJ/mol: budget and cost are
    both in PMF units (1 unit = 1 proton of motive energy ≈ -22 kJ/mol).
    Returns surplus/deficit in both units plus the number of ATP that
    surplus could synthesise at the real 3.3 H+/ATP stoichiometry."""
    surplus_pmf = budget_pmf - cost_pmf
    kj_surplus = pmf_to_kj(surplus_pmf)
    atp_capacity = surplus_pmf / THERMODYNAMICS['protons_per_atp']
    return {
        'surplus_pmf':    surplus_pmf,
        'surplus_kj':     round(kj_surplus, 1),
        'atp_capacity':   round(atp_capacity, 1),
        'feasible':       surplus_pmf >= 0,
        'verdict':        ('thermodynamically feasible — chemiosmotic '
                           'surplus can drive biosynthesis'
                           if surplus_pmf >= 0 else
                           'endergonic shortfall — organism starves'),
    }


def glucose_oxidation_efficiency(atp_yield: float = 32.0) -> float:
    """Fraction of glucose oxidation ΔG°' captured as ATP at physiological ΔG."""
    captured = atp_yield * abs(THERMODYNAMICS['atp_physiological_dg'])
    released = abs(THERMODYNAMICS['glucose_oxidation_dg0'])
    return captured / released if released else 0.0


def michaelis_menten(substrate_mm: float, vmax: float, km: float) -> float:
    """Michaelis–Menten rate law: v = Vmax·[S] / (Km + [S])."""
    if km <= 0 or vmax <= 0 or substrate_mm <= 0:
        return 0.0
    return vmax * substrate_mm / (km + substrate_mm)


def q10_factor(q10: float, temp_c: float, ref_c: float = 37.0) -> float:
    """Q10 temperature coefficient: rate(T)/rate(T_ref) = Q10^((T-T_ref)/10).
    Biological rates typically Q10 ≈ 2–3."""
    if q10 <= 0:
        return 0.0    # negative base with fractional exponent is complex
    return q10 ** ((temp_c - ref_c) / 10.0)


def arrhenius_factor(ea_kj: float, temp_k: float,
                     ref_k: float = 310.15) -> float:
    """Arrhenius rate scaling relative to ref temperature:
    k(T)/k(T_ref) = exp(-Ea/R · (1/T - 1/T_ref))."""
    if temp_k <= 0 or ref_k <= 0:
        return 1.0
    exponent = -ea_kj / R_GAS_KJ * (1.0 / temp_k - 1.0 / ref_k)
    return math.exp(max(-700.0, min(700.0, exponent)))  # clamp vs overflow


def diffusion_coefficient(radius_nm: float, temp_k: float = 310.15,
                          viscosity_pa_s: float = 0.0015) -> float:
    """Stokes–Einstein translational diffusion coefficient, μm²/s.

    D = kT / (6πηr).  Sanity anchors: a ~3 nm protein in cytosol diffuses
    at ~50-150 μm²/s in free solution (effective cytoplasmic values are
    5-15× lower due to crowding); E. coli cell ~1 μm crosses itself
    on the 10 ms timescale for small molecules."""
    if radius_nm <= 0 or temp_k <= 0 or viscosity_pa_s <= 0:
        return 0.0
    d_si = KB_JK * temp_k / (6 * math.pi * viscosity_pa_s * radius_nm * 1e-9)
    return d_si * 1e12  # m²/s -> μm²/s


# SantaLucia (1998) unified nearest-neighbor DNA duplex parameters.
# ΔH° kcal/mol, ΔS° cal/(mol·K) for each dinucleotide step (5'->3').
NN_DNA_THERMO: Dict[str, Tuple[float, float]] = {
    'AA': (-7.9, -22.2), 'TT': (-7.9, -22.2),
    'AT': (-7.2, -20.4), 'TA': (-7.2, -21.3),
    'CA': (-8.5, -22.7), 'TG': (-8.5, -22.7),
    'GT': (-8.4, -22.4), 'AC': (-8.4, -22.4),
    'CT': (-7.8, -21.0), 'AG': (-7.8, -21.0),
    'GA': (-8.2, -22.2), 'TC': (-8.2, -22.2),
    'CG': (-10.6, -27.2), 'GC': (-9.8, -24.4),
    'GG': (-8.0, -19.9), 'CC': (-8.0, -19.9),
}
NN_INIT_DH, NN_INIT_DS = 0.2, -5.7          # duplex initiation
NN_TERMINAL_AT_DH, NN_TERMINAL_AT_DS = 2.2, 6.9   # per terminal A·T


def duplex_thermo(seq: str) -> Optional[Dict[str, float]]:
    """SantaLucia nearest-neighbor ΔH°/ΔS°/ΔG°37 for a real DNA duplex.

    Only defined for the earth A/T/C/G alphabet — XNA base pairs have no
    published NN parameter set, so non-ATCG sequences return None rather
    than fabricate numbers.  A sequence shorter than 2 nt has zero NN
    steps and no duplex to melt — None there too."""
    if not seq or len(seq) < 2 or any(b not in 'ATCG' for b in seq):
        return None
    dh, ds = NN_INIT_DH, NN_INIT_DS
    for i in range(len(seq) - 1):
        step = NN_DNA_THERMO.get(seq[i:i+2])
        if step is None:
            return None
        dh += step[0]; ds += step[1]
    for end in (seq[0], seq[-1]):
        if end in 'AT':
            dh += NN_TERMINAL_AT_DH; ds += NN_TERMINAL_AT_DS
    dg37 = dh - (310.15 * ds / 1000.0)       # ΔG = ΔH - TΔS, kcal/mol
    return {'dH_kcal': dh, 'dS_calK': ds, 'dG37_kcal': dg37}


def melting_temperature(seq: str, na_mm: float = 50.0,
                         strand_um: float = 0.25) -> Optional[float]:
    """Duplex Tm (°C) via NN ΔH/ΔS with salt + strand-concentration terms.

    Tm = ΔH° / (ΔS° + R·ln(C/x)) − 273.15 + 16.6·log10([Na+])
    C = strand molarity; x = 4 for non-self-complementary duplexes,
    x = 1 for self-complementary (palindromic) sequences.
    Returns None for non-ATCG sequences."""
    t = duplex_thermo(seq)
    if t is None:
        return None
    comp = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
    self_comp = seq == ''.join(comp[b] for b in reversed(seq))
    ct = max(1e-12, strand_um * 1e-6)
    na = max(1e-9, na_mm * 1e-3)
    tm = (t['dH_kcal'] * 1000.0 /
          (t['dS_calK'] + 1.987 * math.log(ct / (1.0 if self_comp else 4.0)))) - 273.15
    return tm + 16.6 * math.log10(na)


# E. coli K-12 codon usage frequencies (per mille) — Kazusa codon usage
# database / Sharp & Li (1987).  Each synonymous family's most-used
# codon defines w=1 for CAI; rarer codons score their relative usage.
ECOLI_CODON_USAGE: Dict[str, float] = {
    'TTT': 22.1, 'TTC': 16.0, 'TTA': 13.9, 'TTG': 13.0,
    'CTT': 11.9, 'CTC': 10.5, 'CTA': 3.8,  'CTG': 50.0,
    'ATT': 30.1, 'ATC': 25.1, 'ATA': 4.4,  'ATG': 27.8,
    'GTT': 18.0, 'GTC': 15.4, 'GTA': 11.6, 'GTG': 26.4,
    'TCT': 8.6,  'TCC': 8.8,  'TCA': 7.4,  'TCG': 8.8,
    'CCT': 7.0,  'CCC': 5.5,  'CCA': 8.2,  'CCG': 22.7,
    'ACT': 9.2,  'ACC': 23.3, 'ACA': 7.8,  'ACG': 14.4,
    'GCT': 15.6, 'GCC': 27.7, 'GCA': 21.0, 'GCG': 33.6,
    'TAT': 16.2, 'TAC': 12.2, 'TAA': 2.0,  'TAG': 0.3,
    'CAT': 12.9, 'CAC': 9.7,  'CAA': 15.1, 'CAG': 29.2,
    'AAT': 18.1, 'AAC': 21.9, 'AAA': 33.9, 'AAG': 11.1,
    'GAT': 32.5, 'GAC': 19.5, 'GAA': 39.9, 'GAG': 18.6,
    'TGT': 5.2,  'TGC': 6.5,  'TGA': 1.1,  'TGG': 15.2,
    'CGT': 21.4, 'CGC': 21.9, 'CGA': 3.6,  'CGG': 5.5,
    'AGT': 8.8,  'AGC': 15.8, 'AGA': 4.8,  'AGG': 2.4,
    'GGT': 24.7, 'GGC': 28.4, 'GGA': 8.2,  'GGG': 11.0,
}

# synonymous families for CAI (Sharp & Li 1987): w_i = f_i / f_max_in_family
_SYN_FAMILIES: Dict[str, List[str]] = {}
for _c, _aa in GENETIC_CODE.items():
    _SYN_FAMILIES.setdefault(_aa, []).append(_c)


def codon_adaptation_index(seq_or_codons) -> Optional[float]:
    """Codon Adaptation Index (CAI) vs E. coli K-12 usage — real
    translational-efficiency proxy.  Geometric mean of w_i over
    non-Met/Trp sense codons; returns None if no scorable codons."""
    if isinstance(seq_or_codons, str):
        dna = seq_or_codons.upper().replace('U', 'T')
        codons = [dna[i:i+3] for i in range(0, len(dna) - 2, 3)]
    else:
        codons = [str(c).upper() for c in seq_or_codons]
    w_sum, n = 0.0, 0
    for c in codons:
        aa = GENETIC_CODE.get(c)
        if aa is None or aa in ('M', 'W', '*', 'X'):
            continue                      # single-codon families, stops, unknown
        fam_max = max(ECOLI_CODON_USAGE.get(k, 0.0) for k in _SYN_FAMILIES[aa])
        w = ECOLI_CODON_USAGE.get(c, 0.0) / fam_max if fam_max else 0.0
        w_sum += math.log(max(w, 1e-4))   # floor to keep finite logs
        n += 1
    return math.exp(w_sum / n) if n else None


# --- Spatial quorum-signal diffusion -------------------------------------
# AHL-type autoinducers (~250 Da, r ≈ 0.4 nm) diffuse at ~490 μm²/s in
# free solution — the real constraint on how fast quorum sensing can
# propagate across a colony.  We solve ∂C/∂t = D∇²C on a 2-D grid by
# explicit FTCS (stable iff D·dt/dx² ≤ 0.25).

AHL_DIFFUSION_UM2S = 490.0     # μm²/s — measured for small autoinducers
AHL_DECAY_S        = 60.0      # s — AHL half-life ~ minutes in rich media

class SignalField:
    """2-D diffusion field for a quorum autoinducer.
    Cells deposit signal at their position; it spreads and decays so
    quorum activation is a *local* property — cells far from a
    producing cluster never see the signal.  This mirrors real
    biofilm/bacterial-lawn quorum dynamics."""

    def __init__(self, n_x: int = 24, n_y: int = 24, dx_um: float = 1.0,
                 diffusion_um2_s: float = AHL_DIFFUSION_UM2S,
                 decay_s: float = AHL_DECAY_S, open_medium: bool = True):
        if dx_um <= 0:
            raise ValueError('SignalField: dx_um must be positive')
        if diffusion_um2_s < 0:
            raise ValueError('SignalField: diffusion_um2_s must be >= 0 '
                             '(negative diffusion is unphysical)')
        if decay_s <= 0:
            raise ValueError('SignalField: decay_s must be positive')
        self.nx, self.ny = max(3, n_x), max(3, n_y)
        self.dx = dx_um
        self.D = diffusion_um2_s
        self.decay = decay_s
        # open_medium=True  -> Dirichlet edges: signal diffuses away
        #   (open ocean / flow-through; quorum needs dense clusters)
        # open_medium=False -> Neumann edges: zero-flux walls
        #   (sealed microcolony well; signal accumulates)
        self.open = open_medium
        self.field = [[0.0] * self.nx for _ in range(self.ny)]

    def deposit(self, ix: int, iy: int, amount: float = 1.0) -> None:
        if 0 <= ix < self.nx and 0 <= iy < self.ny:
            self.field[iy][ix] += amount

    def step(self, dt_s: float = 0.01) -> None:
        """Advance diffusion by dt seconds.  FTCS stability requires
        D·dt/dx² ≤ 0.25 in 2-D; dt is auto-clamped to stay stable."""
        lam = self.D * dt_s / (self.dx * self.dx)
        if lam > 0.25:
            dt_s = 0.25 * self.dx * self.dx / self.D
            lam = 0.25
        f = self.field
        new = [row[:] for row in f]
        for y in range(self.ny):
            for x in range(self.nx):
                if self.open:
                    # Dirichlet: missing neighbours are zero-sinks
                    lap = ((f[y][x-1] if x > 0 else 0.0)
                           + (f[y][x+1] if x < self.nx-1 else 0.0)
                           + (f[y-1][x] if y > 0 else 0.0)
                           + (f[y+1][x] if y < self.ny-1 else 0.0)
                           - 4.0 * f[y][x])
                else:
                    # Neumann: missing neighbours mirror the cell -> zero flux
                    lap = ((f[y][x-1] if x > 0 else f[y][x])
                           + (f[y][x+1] if x < self.nx-1 else f[y][x])
                           + (f[y-1][x] if y > 0 else f[y][x])
                           + (f[y+1][x] if y < self.ny-1 else f[y][x])
                           - 4.0 * f[y][x])
                new[y][x] = f[y][x] + lam * lap
        # first-order decay (AHL half-life) — exact exponential, not the
        # linear factor 1-dt/tau (which goes negative for dt>tau and
        # silently zeroed the whole field).
        dk = math.exp(-dt_s / self.decay)
        self.field = [[max(0.0, v * dk) for v in row] for row in new]

    def run(self, seconds: float, dt_s: float = 0.01) -> None:
        # step() clamps dt_s to the FTCS limit — use the effective step
        # here so `seconds` of wall time is actually simulated.
        dt_eff = min(dt_s, 0.25 * self.dx * self.dx / max(1e-9, self.D))
        steps = max(1, int(seconds / max(1e-9, dt_eff)))
        for _ in range(steps):
            self.step(dt_eff)

    def concentration_at(self, ix: int, iy: int) -> float:
        if 0 <= ix < self.nx and 0 <= iy < self.ny:
            return self.field[iy][ix]
        return 0.0

    def max_concentration(self) -> float:
        return max(max(row) for row in self.field)


def simulate_quorum_field(cell_positions: List[Tuple[int, int]],
                          secretion_per_s: float = 4.0,
                          spread_seconds: float = 0.5,
                          threshold: float = QUORUM_THRESHOLD,
                          **field_kw) -> Dict[str, Any]:
    """Cells continuously secrete AHL (secretion_per_s each second) while
    it diffuses and decays; after `spread_seconds` read the *local*
    concentration at each cell.  A cell is quorum-active only if its
    neighbourhood has accumulated enough signal — spatially realistic
    quorum sensing, not a flat shared counter."""
    sf = SignalField(**field_kw)
    # step() silently clamps dt to the FTCS stability limit — compute the
    # same effective dt here so secretion, step count, and the physics
    # all advance on one consistent time base.  With D=0 there is no
    # stability limit — pure deposit+decay at the default dt.
    dt = min(0.001, 0.25 * sf.dx * sf.dx / sf.D) if sf.D > 0 else 0.001
    off_grid = [(ix, iy) for ix, iy in cell_positions
                if not (0 <= ix < sf.nx and 0 <= iy < sf.ny)]
    if off_grid:
        raise ValueError(
            f'simulate_quorum_field: {len(off_grid)} cell(s) outside the '
            f'{sf.nx}x{sf.ny} field (e.g. {off_grid[0]}) — they would '
            'silently receive/deposit no signal')
    steps = max(1, int(spread_seconds / dt))
    per_step = secretion_per_s * dt
    for _ in range(steps):
        for ix, iy in cell_positions:
            sf.deposit(ix, iy, per_step)
        sf.step(dt)
    local = [sf.concentration_at(ix, iy) for ix, iy in cell_positions]
    return {
        'field':       sf,
        'local_signal': local,
        'active':       [c >= threshold for c in local],
        'n_active':     sum(1 for c in local if c >= threshold),
        'peak_signal':  sf.max_concentration(),
        'D_um2_s':      sf.D,
    }


# --- Protein acid/base chemistry: pKa charge curve + isoelectric point ----
# Standard pKa set (EMBOSS/Dawson): termini + titratable side chains.
PKA_NTERM = 8.6
PKA_CTERM = 3.6
PKA_SIDE_CHAINS: Dict[str, float] = {   # acidic groups lose a proton -> -1
    'D': 3.9, 'E': 4.1, 'C': 8.5, 'Y': 10.1,
    'H': 6.5, 'K': 10.8, 'R': 12.5,     # basic groups hold a proton -> +1
}
_ACIDIC_RES = {'D', 'E', 'C', 'Y'}
_BASIC_RES  = {'H', 'K', 'R'}


def net_charge_ph(protein: str, ph: float = 7.0) -> float:
    """Net protein charge at a given pH via Henderson–Hasselbalch.
    Basic groups contribute +1/(1+10^(pH-pKa)); acidic groups
    -1/(1+10^(pKa-pH)); plus one N- and one C-terminus."""
    if not protein:
        return 0.0
    q = 1.0 / (1.0 + 10.0 ** (ph - PKA_NTERM))
    q -= 1.0 / (1.0 + 10.0 ** (PKA_CTERM - ph))
    for aa in protein:
        pka = PKA_SIDE_CHAINS.get(aa)
        if pka is None:
            continue
        if aa in _BASIC_RES:
            q += 1.0 / (1.0 + 10.0 ** (ph - pka))
        else:
            q -= 1.0 / (1.0 + 10.0 ** (pka - ph))
    return q


def isoelectric_point(protein: str) -> Optional[float]:
    """pI = pH where net charge crosses zero.  Bisection on [0, 14];
    the charge curve is monotonic decreasing in pH so it converges."""
    if not protein:
        return None
    lo, hi = 0.0, 14.0
    if net_charge_ph(protein, lo) < 0:
        return lo   # already negative at pH 0 — extremely acidic
    if net_charge_ph(protein, hi) > 0:
        return hi
    for _ in range(50):
        mid = (lo + hi) / 2.0
        if net_charge_ph(protein, mid) > 0:
            lo = mid
        else:
            hi = mid
    return round((lo + hi) / 2.0, 2)


# --- Ribosome translation kinetics ---------------------------------------
# Real E. coli values (Berg, Alberts): ~20 aa/s elongation at 37 °C,
# misincorporation ~3e-4 per codon (proofreading ribosome), energy cost
# ~4 high-energy bonds per residue (2 for aa-tRNA charging ATP->AMP+PPi,
# 1 GTP EF-Tu, 1 GTP EF-G).
RIBOSOME_KINETICS = {
    'elongation_aa_per_s': 20.0,      # E. coli 37 °C (euk ~2-6 aa/s)
    'elongation_aa_per_s_euk': 5.0,
    'error_per_aa':         3e-4,     # misincorporation per codon
    'bonds_per_aa':         4,        # high-energy phosphate bonds / residue
    'initiation_s':         1.0,      # 30S IC assembly ~seconds
}

def translation_kinetics(n_aa: int, eukaryote: bool = False) -> Dict[str, float]:
    """Real ribosome timing/cost for a protein of n_aa residues."""
    if n_aa <= 0:
        return {'time_s': 0.0, 'expected_errors': 0.0, 'atp_equiv': 0,
                'error_free_prob': 1.0}
    rate = (RIBOSOME_KINETICS['elongation_aa_per_s_euk'] if eukaryote
            else RIBOSOME_KINETICS['elongation_aa_per_s'])
    err = RIBOSOME_KINETICS['error_per_aa'] * n_aa
    return {
        'time_s':          RIBOSOME_KINETICS['initiation_s'] + n_aa / rate,
        'expected_errors': err,
        'error_free_prob': math.exp(-err),   # Poisson P(0 errors)
        'atp_equiv':       RIBOSOME_KINETICS['bonds_per_aa'] * n_aa,
    }


# --- DNA polymerase energy cost -------------------------------------------
# Each dNTP incorporated hydrolyses ~2 phosphoanhydride bonds
# (dNTP -> dNMP + PPi, PPi -> 2 Pi drives the reaction forward).
# Lagging-strand Okazaki priming adds ~5-10% overhead (one RNA primer
# ~10 nt per ~1000-2000 nt Okazaki fragment + ligation).
def replication_polymerase_cost(n_bp: int) -> Dict[str, float]:
    """ATP-equivalent cost of replicating n_bp base pairs (both strands).

    Each base pair contributes 2 nucleotides (one per strand); each
    incorporated nucleotide hydrolyses ~2 phosphoanhydride bonds
    (dNTP -> dNMP + PPi, then PPi -> 2 Pi), i.e. ~4 ATP-equiv per bp."""
    bonds = 4.0 * n_bp
    okazaki_overhead = 0.08 * bonds
    return {
        'atp_equiv':        bonds + okazaki_overhead,
        'kj_mol':           (bonds + okazaki_overhead) * abs(THERMODYNAMICS['atp_hydrolysis_dg0']),
        'bonds_per_bp':     4.0,
        'okazaki_fraction': 0.08,
    }


# --- Osmotic turgor (van't Hoff) ------------------------------------------
# Bacterial cytoplasm ~300 mOsm; turgor balances cell-wall stress at
# 0.5-3 MPa in gram-negative rods (MBoC).  Π = i·M·R·T.
def osmotic_turgor(osmolarity_mosm: float = 300.0, temp_k: float = 310.15,
                   external_mosm: float = 50.0) -> Dict[str, float]:
    """Turgor pressure (MPa) across the cell envelope from the
    osmolarity difference cytoplasm-vs-medium."""
    delta_osm = (osmolarity_mosm - external_mosm) / 1000.0   # osmol/L
    pi_pa = delta_osm * 1000.0 * 8.314 * temp_k              # L -> m^3 for SI Pa
    # Turgor is hydrostatic pressure against the wall — it cannot go
    # negative.  When the medium is hyperosmotic the protoplast pulls
    # away from the wall (plasmolysis) and turgor is 0.
    return {
        'turgor_MPa':    max(0.0, pi_pa / 1e6),
        'delta_osmolar': delta_osm,
        'plasmolyzed':   pi_pa <= 0.0,
        'temp_K':        temp_k,
    }


# ---------------------------------------------------------------------------
# 3c. FASTA IMPORT + ORF SCAN — load real genes into the engine
# ---------------------------------------------------------------------------

def parse_fasta(text: str) -> List[Dict[str, str]]:
    """Parse FASTA text into [{'id','description','seq'}] records.
    Tolerates blank lines, CRLF, and lowercase sequence."""
    records: List[Dict[str, str]] = []
    header = None
    chunks: List[str] = []
    def _flush() -> None:
        if header is not None:
            rec_id, _, desc = header.partition(' ')
            records.append({'id': rec_id.strip() or f'record_{len(records)+1}',
                            'description': desc.strip(),
                            'seq': ''.join(chunks).upper()})
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith('>'):
            _flush()
            header = line[1:].strip()
            chunks = []
        elif header is not None:
            chunks.append(''.join(c for c in line if c.isalpha()))
        else:
            # sequence data before any header — anonymous record
            header = 'record_1 anonymous'
            chunks.append(''.join(c for c in line if c.isalpha()))
    _flush()
    return records


def find_orfs(dna: str, min_aa: int = 30,
              genetic_code: Optional[Dict[str, str]] = None,
              both_strands: bool = True) -> List[Dict[str, Any]]:
    """Scan reading frames for open reading frames (ATG ... stop).

    Real genomes carry genes on BOTH strands — roughly half of all CDS in
    bacteria sit on the complement.  With both_strands=True (default) all
    six frames are searched: the three forward frames on `dna` and the
    three reverse frames on its reverse complement.  Minus-strand hits
    report 'strand': '-' and coordinates mapped back onto `dna`
    coordinates (start < end, reading right-to-left biologically).

    Returns a list sorted by descending length with frame, strand,
    start/end coordinates, protein length, and the protein itself."""
    code = genetic_code or GENETIC_CODE
    orfs: List[Dict[str, Any]] = []
    n = len(dna)

    def _scan(s: str, strand_sign: str) -> None:
        for frame in range(3):
            i = frame
            while i + 3 <= n:
                codon = s[i:i+3]
                if code.get(codon) == 'M':
                    # scan for in-frame stop
                    j = i + 3
                    while j + 3 <= n:
                        c2 = s[j:j+3]
                        if code.get(c2) == '*':
                            aa_len = (j - i) // 3
                            if aa_len >= min_aa:
                                if strand_sign == '+':
                                    start, end = i, j + 3
                                else:
                                    # Map complement-local coords back to
                                    # the forward-strand coordinate system.
                                    start, end = n - (j + 3), n - i
                                orfs.append({
                                    'frame': frame,
                                    'strand': strand_sign,
                                    'start': start, 'end': end,
                                    'aa_len': aa_len,
                                    'protein': ''.join(
                                        code.get(s[k:k+3], 'X')
                                        for k in range(i, j, 3)),
                                })
                            i = j          # skip past this ORF
                            break
                        j += 3
                    else:
                        i += 3
                        continue
                i += 3

    _scan(dna, '+')
    if both_strands:
        _scan(_revcomp_dna(dna), '-')
    orfs.sort(key=lambda o: -o['aa_len'])
    return orfs


def import_fasta_genome(path: str) -> Dict[str, Any]:
    """Load a FASTA file, take the longest record as the genome, and return
    a dict with the sequence, ORF scan, and a Strand ready to translate."""
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        records = parse_fasta(f.read())
    if not records:
        raise ValueError(f"no FASTA records found in {path}")
    best = max(records, key=lambda r: len(r['seq']))
    # Restrict to the engine alphabet — non-ATCG bases become A (documented
    # lossy projection; ambiguous IUPAC codes have no clean mapping).
    seq = ''.join(c if c in 'ATCG' else 'A' for c in best['seq'])
    orfs = find_orfs(seq, min_aa=25)
    strand = Strand(seq[:6000] if len(seq) > 6000 else seq, 4)
    return {
        'source_file': path,
        'record_id':   best['id'],
        'description': best['description'],
        'seq_len':     len(seq),
        'truncated':   len(seq) > 6000,
        'seq':         strand.seq,
        'n_orfs':      len(orfs),
        'longest_orf': orfs[0] if orfs else None,
        'orfs':        orfs[:25],
        'strand':      strand,
    }


# ---------------------------------------------------------------------------
# 3d. GENBANK IMPORT — annotated flat files: real genes, real coordinates
# ---------------------------------------------------------------------------
# GenBank is the NCBI/DDBJ/ENA annotated-sequence standard: LOCUS header,
# FEATURES table with /gene /product qualifiers and join()/complement()
# CDS locations, then the ORIGIN sequence.  Parsing it closes the critique
# gap "no FASTA/GenBank import" — FASTA alone carries no annotation.

def _split_top_commas(s: str) -> List[str]:
    """Split on commas that are NOT nested inside parentheses."""
    parts, depth, cur = [], 0, []
    for ch in s:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if ch == ',' and depth == 0:
            parts.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    parts.append(''.join(cur))
    return [p.strip() for p in parts if p.strip()]


def _parse_genbank_location(loc: str) -> List[Tuple[int, int, int]]:
    """Parse a GenBank location string -> [(start0, end_exclusive, strand)].

    Handles the real syntax: '123..456', '<123..>456', '123',
    'complement(123..456)', 'join(a..b,c..d)', 'complement(join(..))',
    and 'order(..)' treated like join (documented simplification —
    order() only differs in assembly semantics, not coordinates)."""
    spans: List[Tuple[int, int, int]] = []

    def _walk(expr: str, strand: int) -> None:
        expr = expr.strip()
        if expr.startswith('complement(') and expr.endswith(')'):
            _walk(expr[len('complement('):-1], -strand)
            return
        for head in ('join(', 'order('):
            if expr.startswith(head) and expr.endswith(')'):
                for part in _split_top_commas(expr[len(head):-1]):
                    _walk(part, strand)
                return
        expr = expr.replace('<', '').replace('>', '')
        # Remote-accession refs (J00194.1:100..200) point at a different
        # record — skipping is the honest move; importing them as local
        # coordinates would fabricate sequence positions.  Other leaves
        # that aren't pure coordinates are skipped the same way so one
        # bad span can't drop a whole joined CDS.
        if ':' in expr:
            return
        try:
            if '^' in expr:                       # between-bases site 123^124
                a, _, b = expr.partition('^')
                spans.append((int(a) - 1, int(b), strand))
            elif '..' in expr:
                a, _, b = expr.partition('..')
                spans.append((int(a) - 1, int(b), strand))
            elif expr.isdigit():
                a = int(expr)
                spans.append((a - 1, a, strand))
        except ValueError:
            pass
        # anything else (acc:123..456 remote refs) is skipped — honest gap

    _walk(loc, 1)
    return spans


def parse_genbank(text: str) -> Dict[str, Any]:
    """Parse GenBank flat-file text into {locus, definition, accession,
    seq, features:[{type, location, qualifiers}]}.  Tolerates wrapped
    DEFINITION lines, multi-line qualifiers, and CRLF."""
    rec: Dict[str, Any] = {'locus': None, 'definition': '', 'accession': None,
                           'seq': '', 'features': []}
    mode = None                       # None | 'def' | 'feat' | 'origin'
    feat: Optional[Dict[str, Any]] = None
    qual_key: Optional[str] = None
    for raw in text.splitlines():
        if raw.startswith('LOCUS'):
            parts = raw.split()
            rec['locus'] = parts[1] if len(parts) > 1 else 'unknown'
            mode = None
        elif raw.startswith('DEFINITION'):
            rec['definition'] = raw[12:].strip()
            mode = 'def'
        elif raw.startswith('ACCESSION'):
            fields = raw[12:].split()
            rec['accession'] = fields[0] if fields else None
            mode = None
        elif raw.startswith('FEATURES'):
            mode = 'feat'
        elif raw.startswith('ORIGIN'):
            mode = 'origin'
        elif raw.startswith('//'):
            break
        elif mode == 'def':
            rec['definition'] += ' ' + raw.strip()
        elif mode == 'origin':
            rec['seq'] += ''.join(c for c in raw if c.isalpha()).upper()
        elif mode == 'feat' and raw.strip():
            key = raw[5:21].strip() if len(raw) > 21 else ''
            content = raw[21:].strip() if len(raw) > 21 else ''
            if key:
                feat = {'type': key, 'location': content, 'qualifiers': {}}
                rec['features'].append(feat)
                qual_key = None
            elif feat is not None and content:
                if content.startswith('/'):
                    if '=' in content:
                        k, _, v = content[1:].partition('=')
                        feat['qualifiers'][k.strip()] = v.strip().strip('"')
                        qual_key = k.strip()
                    else:
                        qual_key = content[1:].strip()
                        feat['qualifiers'][qual_key] = True
                elif qual_key and isinstance(feat['qualifiers'].get(qual_key), str):
                    feat['qualifiers'][qual_key] += content.strip('"')
                else:
                    feat['location'] += content
    return rec


def import_genbank_genome(path: str, max_seq: int = 6000) -> Dict[str, Any]:
    """Load a GenBank file: real sequence + real CDS annotation.

    Returns the genome (restricted to the engine ATCG alphabet), a Strand,
    and a list of CDS features with their gene names, coordinates, spliced
    nucleotide sequences (join/complement resolved), and translations
    (/translation qualifier preferred; otherwise NCBI table 1)."""
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        rec = parse_genbank(f.read())
    if not rec['seq']:
        raise ValueError(f"no ORIGIN sequence found in {path}")
    seq = ''.join(c if c in 'ATCG' else 'A' for c in rec['seq'])
    _rev = str.maketrans('ATCG', 'TAGC')
    cds_list: List[Dict[str, Any]] = []
    for feat in rec['features']:
        if feat['type'] != 'CDS':
            continue
        try:
            spans = _parse_genbank_location(feat['location'])
        except Exception:
            spans = []
        if not spans:
            continue
        pieces = []
        # Minus-strand CDS: exons splice in REVERSED genomic order — the
        # 5'->3' transcript is revcomp(last span) + ... + revcomp(first
        # span).  Processing the spans in file order produced a shuffled
        # CDS (every multi-exon complement() gene decoded backwards).
        ordered = list(reversed(spans)) if all(sd < 0 for _, _, sd in spans) \
                  else spans
        for s0, e0, strand_dir in ordered:
            frag = seq[max(0, s0):min(len(seq), e0)]
            if strand_dir < 0:
                frag = frag.translate(_rev)[::-1]
            pieces.append(frag)
        cds_seq = ''.join(pieces)
        prot = feat['qualifiers'].get('translation')
        if not isinstance(prot, str) or not prot:
            prot = translate_rna_to_protein(
                transcribe_dna_to_rna(cds_seq), start_at_atg=False)[0] \
                if len(cds_seq) >= 3 else ''
        cds_list.append({
            'gene':     (feat['qualifiers'].get('gene') or
                         feat['qualifiers'].get('product') or 'unnamed'),
            'location': feat['location'],
            'nt_len':   len(cds_seq),
            'aa_len':   len(prot or ''),
            'protein':  prot or '',
            'spans':    len(spans),
        })
    strand = Strand(seq[:max_seq] if len(seq) > max_seq else seq, 4)
    return {
        'source_file': path,
        'locus':       rec['locus'],
        'definition':  rec['definition'],
        'accession':   rec['accession'],
        'seq_len':     len(seq),
        'truncated':   len(seq) > max_seq,
        'n_cds':       len(cds_list),
        'n_features':  len(rec['features']),
        'cds':         cds_list[:50],
        'seq':         strand.seq,
        'strand':      strand,
        'note':        'annotation-aware import — real locus coordinates, '
                       'not the FASTA ORF-scan approximation',
    }


# ---------------------------------------------------------------------------
# 4. REALISTIC MUTATION OPERATOR — Ts/Tv bias, indels, frameshift detection
# ---------------------------------------------------------------------------
# Empirical: transitions (purine<->purine OR pyrimidine<->pyrimidine) are ~2-3x
# more common than transversions. Real Ts/Tv ratio in mammals ~2.0–2.1.
TRANSITION_PAIRS = {
    'A': 'G', 'G': 'A',  # purines
    'C': 'T', 'T': 'C',  # pyrimidines
}
TRANSVERSION_OPTIONS = {
    'A': ['C', 'T'],  'G': ['C', 'T'],
    'C': ['A', 'G'],  'T': ['A', 'G'],
}


def mutate_seq_realistic(seq: str, bases: List[str],
                          point_rate: float = 0.01,
                          ts_tv_ratio: float = 2.0,
                          indel_rate: float = 0.001,
                          cpg_multiplier: float = 10.0,
                          rng: Optional[random.Random] = None,
                          methylated_cpg: Optional[set] = None) -> Tuple[str, Dict[str, int]]:
    """Realistic mutation with biological biases.

    - Point rate: per-base probability of substitution (default 1% = high
      for evolution but tractable; real bacterial rate is 1e-9).
    - Ts/Tv: probability ratio of transition vs transversion. Default 2.0
      matches mammalian average.
    - Indel rate: per-base probability of insertion or deletion.
    - CpG hypermutability: methylated CpG sites mutate ~10x faster (real).
    Returns (new_seq, stats_dict).

    Falls back to uniform random for non-DNA (4-base) alphabets.

    `rng` supplies determinism (default: module random).  `methylated_cpg` is
    an optional set of sequence indices whose CpG cytosine is 5-methylated —
    those positions mutate at `cpg_multiplier` x the base rate AND always
    deaminate to thymine (the real 5mC -> T chemistry), not just a transition.
    """
    _r = rng or random
    if set(bases) != set('ATCG'):
        # Non-DNA alphabet — use uniform substitution
        new_seq = mutate_seq(seq, bases, rate=point_rate, rng=_r)
        return new_seq, {'transitions': 0, 'transversions': 0,
                         'insertions': 0, 'deletions': 0,
                         'frameshifts': 0, 'cpg_hits': 0,
                         'deaminations': 0}

    g = list(seq)
    stats = {'transitions': 0, 'transversions': 0,
             'insertions':  0, 'deletions':  0,
             'frameshifts': 0, 'cpg_hits':  0,
             'deaminations': 0}
    _rnd = _r.random; _choice = _r.choice; _randint = _r.randint
    ts_prob = ts_tv_ratio / (ts_tv_ratio + 1.0)  # loop-invariant
    # Substitutions
    for i in range(len(g)):
        # Detect CpG context: Cp followed by G OR previous is C and current is G
        is_cpg = (i + 1 < len(g) and g[i] == 'C' and g[i+1] == 'G') or \
                 (i > 0 and g[i-1] == 'C' and g[i] == 'G')
        # CpG hypermutability is driven by 5mC deamination — UNMETHYLATED
        # CpG sites mutate at the normal rate.  The methyl mark lives on
        # the cytosine, but CpG is a symmetric dinucleotide: when the C of
        # a methylated CG deaminates on the opposite strand, this strand
        # shows the reciprocal G->A (CpG -> CpA signature).
        is_methylated = methylated_cpg is not None and (
            i in methylated_cpg
            or (g[i] == 'G' and (i - 1) in methylated_cpg))
        local_rate = point_rate * (cpg_multiplier if is_methylated else 1.0)
        if _rnd() < local_rate:
            if is_cpg:
                stats['cpg_hits'] += 1
            # 5-methylcytosine deaminates specifically to thymine — the
            # dominant CpG->TpG mutation in mammalian genomes.  Its
            # reciprocal event on the paired strand is G->A (CpG -> CpA).
            if is_methylated and g[i] == 'C':
                g[i] = 'T'
                stats['deaminations'] += 1
                stats['transitions'] += 1
                continue
            if is_methylated and g[i] == 'G':
                g[i] = 'A'
                stats['deaminations'] += 1
                stats['transitions'] += 1
                continue
            # Choose transition vs transversion.  Ambiguous/foreign
            # residues (N, R, Y...) have no IUPAC pairing here — resolve
            # them to a different alphabet base outright.
            if g[i] not in TRANSITION_PAIRS:
                g[i] = _choice([b for b in bases if b != g[i]] or list(bases))
                stats['transversions'] += 1
            elif _rnd() < ts_prob:
                g[i] = TRANSITION_PAIRS[g[i]]
                stats['transitions'] += 1
            else:
                g[i] = _choice(TRANSVERSION_OPTIONS[g[i]])
                stats['transversions'] += 1
    # Indels (insertion or deletion)
    indel_count = sum(1 for _ in range(len(g)) if _rnd() < indel_rate)
    for _ in range(indel_count):
        if _rnd() < 0.5 and len(g) > 10:
            # Deletion
            del_len = _choice([1, 1, 1, 2, 3])  # mostly single
            pos = _randint(0, len(g) - del_len)
            del g[pos:pos+del_len]
            stats['deletions'] += 1
            if del_len % 3 != 0:
                stats['frameshifts'] += 1
        else:
            # Insertion
            ins_len = _choice([1, 1, 1, 2, 3])
            pos = _randint(0, len(g))
            ins = [_choice(bases) for _ in range(ins_len)]
            g[pos:pos] = ins
            stats['insertions'] += 1
            if ins_len % 3 != 0:
                stats['frameshifts'] += 1
    return ''.join(g), stats


# ---------------------------------------------------------------------------
# 5. DNA REPLICATION FORK — real polymerase mechanics
# ---------------------------------------------------------------------------
# Real polymerase rates (literature values):
#   E. coli DNA Pol III:        ~1000 bp/s
#   Eukaryotic Pol delta/eps:    ~50 bp/s
#   Okazaki fragment, prokaryote: ~1000-2000 bp
#   Okazaki fragment, eukaryote:  ~100-200 bp
REPLICATION_PARAMS = {
    'prokaryote': {
        'polymerase_rate_bps': 1000.0,
        'okazaki_length':      1500,
        'origins':             1,         # single circular origin (oriC)
        'has_proofreading':    True,
    },
    'eukaryote': {
        'polymerase_rate_bps': 50.0,
        'okazaki_length':      150,
        'origins':             30000,     # ~30k origins per genome
        'has_proofreading':    True,
    },
    'virus': {
        'polymerase_rate_bps': 200.0,
        'okazaki_length':      500,
        'origins':             1,
        'has_proofreading':    False,    # most viral pols lack proofreading
    },
}


def simulate_replication_fork(genome_len: int, organism_type: str = 'prokaryote',
                                fork_count: int = 1) -> Dict[str, Any]:
    """Compute real replication time and Okazaki fragment count.

    organism_type: 'prokaryote' (bacteria), 'eukaryote' (cells with nucleus),
                   'virus' (no proofreading, fast & error-prone).
    fork_count:    number of active replication forks. Bacteria: 2 (bidirectional
                   from oriC). Eukaryotes: many (one per active origin).
    """
    p = REPLICATION_PARAMS.get(organism_type, REPLICATION_PARAMS['prokaryote'])
    rate = p['polymerase_rate_bps']
    # Each fork copies half the genome bidirectionally
    bp_per_fork = genome_len / max(1, fork_count)
    time_s = bp_per_fork / rate
    # Lagging strand: number of Okazaki fragments per fork
    okazaki_per_fork = max(1, int(bp_per_fork / p['okazaki_length']))
    return {
        'organism_type':       organism_type,
        'genome_len_bp':       genome_len,
        'fork_count':          fork_count,
        'polymerase_rate_bps': rate,
        'replication_time_s':  round(time_s, 3),
        'replication_time_min':round(time_s / 60.0, 2),
        'okazaki_per_fork':    okazaki_per_fork,
        'okazaki_total':       okazaki_per_fork * fork_count,
        'has_proofreading':    p['has_proofreading'],
        'origins_typical':     p['origins'],
    }


# ---------------------------------------------------------------------------
# 6. POPULATION GENETICS — selection, drift, fixation
# ---------------------------------------------------------------------------

def selection_coefficient(w_mutant: float, w_wildtype: float) -> float:
    """Wright's selection coefficient: s = (W_a - W_b) / W_b.
    Positive s = beneficial mutation, negative = deleterious.
    """
    if w_wildtype <= 0:
        return 0.0
    return (w_mutant - w_wildtype) / w_wildtype


def kimura_fixation_probability(s: float, Ne: int = 1000) -> float:
    """Kimura (1962) probability that a new mutation fixes in a population.

    For a single new mutation (initial freq p = 1/(2Ne) in diploid, 1/Ne in haploid):
        u = (1 - exp(-2s)) / (1 - exp(-4*Ne*s))    (diploid)
    Limits: s -> 0 gives u = 1/(2Ne) (neutral drift fixation rate)
            s >> 0 gives u ≈ 2s for haploid, ≈ s for diploid heterozygote.
    """
    import math
    if Ne <= 0:
        return 0.0
    if abs(s) < 1e-9:
        # Neutral case: drift only
        return 1.0 / (2 * Ne)
    try:
        num = 1.0 - math.exp(-2 * s)
        den = 1.0 - math.exp(-4 * Ne * s)
        if abs(den) < 1e-12:
            return 0.0
        return max(0.0, min(1.0, num / den))
    except (OverflowError, ValueError):
        # For very large |s*Ne|
        return 1.0 if s > 0 else 0.0


def hardy_weinberg_eq(p: float) -> Dict[str, float]:
    """Hardy-Weinberg genotype frequencies for allele frequency p.
    q = 1 - p; AA = p^2; Aa = 2pq; aa = q^2."""
    p = max(0.0, min(1.0, p))
    q = 1.0 - p
    return {'p': p, 'q': q, 'AA': p*p, 'Aa': 2*p*q, 'aa': q*q}


# ---------------------------------------------------------------------------
# 7. CELL CYCLE — G1, S, G2, M phases with checkpoints
# ---------------------------------------------------------------------------
# Reference durations (actively dividing mammalian cell, ~24h cycle):
#   G1: ~11h, S: ~8h, G2: ~4h, M: ~1h
# Bacteria are simpler (binary fission ~20-60 min total).
CELL_CYCLE_PHASES = ['G1', 'S', 'G2', 'M']
CELL_CYCLE_DURATIONS_MIN = {
    'prokaryote': {'G1': 5,  'S': 10, 'G2': 5,  'M': 5},   # 25 min total
    'eukaryote':  {'G1': 660, 'S': 480, 'G2': 240, 'M': 60}, # 1440 min = 24h
    'virus':      {'G1': 0,  'S': 5,  'G2': 0,  'M': 5},   # parasitic, no real cycle
}
CELL_CYCLE_CHECKPOINTS = {
    'G1': 'restriction_point  — commits to division if growth signals + nutrients OK',
    'S':  'replication_check  — DNA damage halts replication',
    'G2': 'G2/M_checkpoint    — verifies DNA fully replicated and undamaged',
    'M':  'spindle_checkpoint — all chromosomes attached to spindle before anaphase',
}


def cell_cycle_progress(time_min: float, organism_type: str = 'eukaryote') -> Dict[str, Any]:
    """Return current cell-cycle phase given elapsed time (min)."""
    durs  = CELL_CYCLE_DURATIONS_MIN.get(organism_type, CELL_CYCLE_DURATIONS_MIN['eukaryote'])
    total = sum(durs.values())
    t     = time_min % total if total > 0 else 0
    cum   = 0
    for phase in CELL_CYCLE_PHASES:
        cum += durs[phase]
        if t < cum:
            phase_start = cum - durs[phase]
            phase_progress = (t - phase_start) / max(1, durs[phase])
            return {
                'phase':           phase,
                'phase_progress':  round(phase_progress, 3),
                'cycle_progress':  round(t / max(1, total), 3),
                'time_in_phase':   round(t - phase_start, 1),
                'phase_duration':  durs[phase],
                'cycle_duration':  total,
                'checkpoint':      CELL_CYCLE_CHECKPOINTS.get(phase, ''),
            }
    return {'phase': 'M', 'phase_progress': 1.0, 'cycle_progress': 1.0,
            'time_in_phase': 0, 'phase_duration': 0, 'cycle_duration': total,
            'checkpoint': ''}


# ---------------------------------------------------------------------------
# 3b-fba. FLUX BALANCE ANALYSIS — real steady-state metabolic flux solving
# ---------------------------------------------------------------------------
# FBA is the standard constraint-based method of systems biology (Orth,
# Thiele & Palsson, Nat. Biotechnol. 2010).  At steady state every internal
# metabolite pool is constant:
#
#       S · v = 0          (stoichiometric mass balance)
#       0 ≤ v ≤ ub         (irreversible reactions + nutrient bounds)
#       maximize  c · v    (objective — here: ATP production rate)
#
# The feasible flux set is a convex polytope and the optimum is a vertex,
# so an exact LP solve — not a heuristic — returns the cell's best
# achievable ATP yield.  The network below is the real core-carbon spine:
# glycolysis → pyruvate dehydrogenase → TCA → oxidative phosphorylation,
# with lactate fermentation as the NAD+ overflow valve.  Stoichiometry is
# textbook (Lehninger 7e): glycolysis nets 2 ATP + 2 NADH + 2 pyruvate,
# PDH +1 NADH per pyruvate, TCA +3 NADH +1 FADH2 +1 GTP +2 CO2 per
# acetyl-CoA, and modern P/O ratios 2.5 (NADH) / 1.5 (FADH2).

FBA_SPECIES = ['glc', 'pyr', 'accoa', 'nadh', 'nad', 'fadh2', 'fad',
               'atp', 'adp', 'lac', 'o2', 'co2']

# Reaction stoichiometry: negative = consumed, positive = produced.
# All reactions modelled as irreversible (v >= 0) — the physiologically
# dominant direction for this core set.
FBA_REACTIONS: Dict[str, Dict[str, float]] = {
    'glc_import':   {'glc': +1},
    'glycolysis':   {'glc': -1, 'adp': -2, 'nad': -2,
                     'pyr': +2, 'atp': +2, 'nadh': +2},
    'pdh':          {'pyr': -1, 'nad': -1,
                     'accoa': +1, 'nadh': +1, 'co2': +1},
    'tca':          {'accoa': -1, 'nad': -3, 'fad': -1, 'adp': -1,
                     'nadh': +3, 'fadh2': +1, 'atp': +1, 'co2': +2},
    'oxphos_nadh':  {'nadh': -1, 'o2': -0.5, 'adp': -2.5,
                     'nad': +1, 'atp': +2.5},
    'oxphos_fadh2': {'fadh2': -1, 'o2': -0.5, 'adp': -1.5,
                     'fad': +1, 'atp': +1.5},
    'ldh':          {'pyr': -1, 'nadh': -1, 'lac': +1, 'nad': +1},
    'lac_export':   {'lac': -1},
    'atp_demand':   {'atp': -1, 'adp': +1},
    'o2_import':    {'o2': +1},
    'co2_export':   {'co2': -1},
}
FBA_RXN_ORDER = list(FBA_REACTIONS)


def _fba_matrix() -> np.ndarray:
    """Stoichiometric matrix S (species x reactions) for the core network."""
    S = np.zeros((len(FBA_SPECIES), len(FBA_RXN_ORDER)))
    for j, rxn in enumerate(FBA_RXN_ORDER):
        for sp, coeff in FBA_REACTIONS[rxn].items():
            S[FBA_SPECIES.index(sp), j] = coeff
    return S


def _simplex_lp(c: np.ndarray, A: np.ndarray, b: np.ndarray,
                ub: np.ndarray):
    """max c·x  s.t.  A·x = b,  0 <= x_i <= ub_i  (ub_i may be inf).

    Two-phase tableau simplex with Bland's rule (smallest-index entering
    and leaving) — cannot cycle.  Upper bounds are added as explicit
    rows x_i + s_k = u_i so every variable stays non-negative, the
    standard textbook reduction.  Phase 1 maximises -(sum of artificial
    variables) to find a feasible basis; phase 2 optimises the real
    objective with artificial columns barred from re-entering.
    Returns (x, objective, duals) where duals maps each upper-bound row
    to its shadow price (dObjective per unit relaxation); (None, None,
    None) if the LP is infeasible or unbounded."""
    c = np.asarray(c, float)
    A = np.asarray(A, float)
    b = np.asarray(b, float)
    ub = np.asarray(ub, float)
    m, n = A.shape
    ub_rows = [i for i in range(n) if np.isfinite(ub[i])]
    nub = len(ub_rows)
    N = n + nub + m                      # x | bound-slacks | artificials
    rows = m + nub
    T = np.zeros((rows, N))
    rhs = np.zeros(rows)
    T[:m, :n] = A
    rhs[:m] = b
    for k, i in enumerate(ub_rows):
        T[m + k, i] = 1.0
        T[m + k, n + k] = 1.0
        rhs[m + k] = ub[i]
    for i in range(m):
        T[i, n + nub + i] = 1.0
    neg = rhs < 0                        # keep the initial BFS non-negative
    T[neg] *= -1.0
    rhs[neg] *= -1.0
    basis = (list(range(n + nub, N)) +   # artificials on equality rows
             list(range(n, n + nub)))    # slacks on bound rows
    EPS = 1e-9

    def _pivot(r: int, j: int) -> None:
        piv = T[r, j]
        T[r] /= piv
        rhs[r] /= piv
        for i in range(rows):
            if i != r and T[i, j] != 0.0:
                f = T[i, j]
                T[i] -= f * T[r]
                rhs[i] -= f * rhs[r]
        basis[r] = j

    def _solve(cost: np.ndarray, allow_artificial: bool) -> str:
        limit = N if allow_artificial else n + nub
        while True:
            cB = cost[basis]
            w = cB @ T - cost            # reduced costs (max: enter if < 0)
            j = -1
            for jj in range(limit):      # Bland: smallest index
                if w[jj] < -EPS:
                    j = jj
                    break
            if j < 0:
                return 'optimal'
            col = T[:, j]
            cand = [i for i in range(rows) if col[i] > EPS]
            if not cand:
                return 'unbounded'
            ratios = [rhs[i] / col[i] for i in cand]
            rmin = min(ratios)
            tied = [cand[k] for k in range(len(cand))
                    if ratios[k] <= rmin + EPS]
            r = min(tied, key=lambda i: basis[i])   # Bland tie-break
            _pivot(r, j)

    # Phase 1 — drive artificial variables to zero
    cost1 = np.zeros(N)
    cost1[n + nub:] = -1.0
    if _solve(cost1, True) != 'optimal':
        return None, None, None
    if float(cost1[basis] @ rhs) < -1e-6:   # artificials remain -> infeasible
        return None, None, None
    # Evict artificials still basic at level zero (rank-deficient A rows
    # like NAD+/NADH conservation leave a harmless all-zero structural row)
    for i in range(rows):
        if basis[i] >= n + nub:
            for jj in range(n + nub):
                if abs(T[i, jj]) > EPS:
                    _pivot(i, jj)
                    break
    # Phase 2 — real objective, artificial columns excluded
    cost2 = np.zeros(N)
    cost2[:n] = c
    if _solve(cost2, False) != 'optimal':
        return None, None, None
    x = np.zeros(n)
    for i in range(rows):
        if basis[i] < n:
            x[basis[i]] = rhs[i]
    # Shadow prices for bound rows: y_k = cB^T B^{-1} e_{m+k} equals the
    # reduced-cost coefficient under the k-th bound slack column.
    cB2 = cost2[basis]
    duals = {}
    for k, i in enumerate(ub_rows):
        duals[i] = float(cB2 @ T[:, n + k])
    return x, float(c @ x), duals


def fba_core_carbon(glucose_uptake: float = 1.0,
                    o2_uptake: float = 6.0,
                    species: Optional[List[str]] = None,
                    reactions: Optional[Dict[str, Dict[str, float]]] = None
                    ) -> Dict[str, Any]:
    """Solve the real FBA: maximum steady-state ATP flux per unit time.

    glucose_uptake / o2_uptake bound the two import reactions (flux units
    per unit time; set o2_uptake=0 for anaerobic).  Returns the optimal
    flux vector, ATP yield per glucose, and shadow prices — the marginal
    ATP value of relaxing each nutrient bound, the classic FBA dual.
    `species`/`reactions` default to the built-in core-carbon network but
    accept any imported network (e.g. from import_sbml) using the same
    reaction ids for uptake/objective bookkeeping."""
    species = species or FBA_SPECIES
    reactions = reactions or FBA_REACTIONS
    rxn_order = list(reactions)
    S = np.zeros((len(species), len(rxn_order)))
    for j, rxn in enumerate(rxn_order):
        for sp, coeff in reactions[rxn].items():
            if sp in species:
                S[species.index(sp), j] = coeff
    i_of = {r: i for i, r in enumerate(rxn_order)}
    c = np.zeros(len(rxn_order))
    if 'atp_demand' in i_of:
        c[i_of['atp_demand']] = 1.0
    BIG = 1e6
    ub = np.full(len(rxn_order), BIG)
    if 'glc_import' in i_of:
        ub[i_of['glc_import']] = max(0.0, glucose_uptake)
    if 'o2_import' in i_of:
        ub[i_of['o2_import']] = max(0.0, o2_uptake)
    x, obj, duals = _simplex_lp(c, S, np.zeros(len(species)), ub)
    if x is None:
        return {'feasible': False}
    flux = {rxn_order[j]: round(float(x[j]), 4) for j in range(len(x))}
    g_in = flux.get('glc_import', 0.0)
    return {
        'feasible':       True,
        'atp_flux':       round(obj, 4),
        'atp_per_glucose': round(obj / g_in, 3) if g_in > 1e-9 else 0.0,
        'flux':           flux,
        'o2_used':        flux.get('o2_import', 0.0),
        'lactate_out':    flux.get('lac_export', 0.0),
        'co2_out':        flux.get('co2_export', 0.0),
        'respiration_fraction': (flux.get('pdh', 0.0) /
                                 max(1e-9, flux.get('glycolysis', 0.0) * 2.0)),
        'shadow_price_glucose': round(duals.get(i_of.get('glc_import', -1), 0.0), 3),
        'shadow_price_o2':      round(duals.get(i_of.get('o2_import', -1), 0.0), 3),
        'note': ('steady-state S·v=0 vertex solution — NAD+/FAD pools are '
                 'internally conserved so only ratios are constrained'),
    }


# --- Analytic cross-check -------------------------------------------------
# The core network is a linear chain: glucose uptake g forces glycolysis
# flux g; pyruvate splits p (to PDH/TCA/OXPHOS) vs 2g-p (to lactate).
# NADH reaching OXPHOS = 5p (2 glycolytic are reoxidised through LDH),
# O2 demand = 3p, ATP = 2g + 15p.  Hence the exact optimum:
#   ATP* = 2g + 15·min(2g, o2/3)   -> 32g aerobic, 2g anaerobic, 17g at o2=3.
def fba_analytic_atp(glucose_uptake: float = 1.0,
                     o2_uptake: float = 6.0) -> float:
    """Closed-form optimum of the same network — used to validate the LP."""
    g = max(0.0, glucose_uptake)
    p = min(2.0 * g, max(0.0, o2_uptake) / 3.0)
    return 2.0 * g + 15.0 * p


# --- Morris elementary-effects sensitivity ---------------------------------
# Morris (1991) screening: perturb each input one-at-a-time around an
# operating point; the elementary effect's magnitude (mu*) ranks which
# bound controls the objective.  On this linear network the effect of the
# binding nutrient equals its LP shadow price — a falsifiable cross-check.

def morris_sensitivity(glc: float = 1.0, o2: float = 9.0,
                       delta_glc: float = 0.2,
                       delta_o2: float = 1.5) -> Dict[str, Any]:
    """Elementary effects of glucose vs O2 uptake on the FBA ATP optimum."""
    if delta_glc == 0 or delta_o2 == 0:
        raise ValueError('morris_sensitivity: deltas must be non-zero')
    f0 = fba_core_carbon(glc, o2)['atp_flux']
    e_glc = (fba_core_carbon(glc + delta_glc, o2)['atp_flux'] - f0) / delta_glc
    e_o2  = (fba_core_carbon(glc, o2 + delta_o2)['atp_flux'] - f0) / delta_o2
    effects = {'glucose_uptake': e_glc, 'o2_uptake': e_o2}
    binding = max(effects, key=lambda k: abs(effects[k]))
    return {
        'operating_point': {'glc': glc, 'o2': o2},
        'elementary_effects': {k: round(v, 3) for k, v in effects.items()},
        'mu_star': {k: round(abs(v), 3) for k, v in effects.items()},
        'binding_nutrient': binding,
        'note': ('at a glucose-limited vertex the glucose effect ~32 = its '
                 'LP shadow price and the O2 effect ~0 — Morris screening '
                 'reproduces the LP duals'),
    }


# --- SBML export ------------------------------------------------------------
# SBML Level 3 Version 1 (Hucka et al., Bioinformatics 2003) is the standard
# exchange format for systems-biology models.  This closes the critique gap
# "no SBML/standard-format support" for the reaction network.

def export_sbml(path: Optional[str] = None,
                model_id: str = 'core_carbon') -> str:
    """Serialize the FBA core-carbon network to SBML L3V1 XML.
    All species and reactions come straight from FBA_SPECIES/FBA_REACTIONS,
    so the exported model is by construction the same network the LP
    solves.  Returns the XML string (also written to `path` if given)."""
    sp_xml = ''.join(
        f'      <species id="{s}" compartment="cell" '
        f'hasOnlySubstanceUnits="true" boundaryCondition="false" '
        f'constant="false"/>\n' for s in FBA_SPECIES)
    rxn_chunks = []
    for rxn_name, stoich in FBA_REACTIONS.items():
        reacts = ''.join(
            f'        <speciesReference species="{s}" '
            f'stoichiometry="{-c}" constant="true"/>\n'
            for s, c in stoich.items() if c < 0)
        prods = ''.join(
            f'        <speciesReference species="{s}" '
            f'stoichiometry="{c}" constant="true"/>\n'
            for s, c in stoich.items() if c > 0)
        lr = ('      <listOfReactants>\n' + reacts +
              '      </listOfReactants>\n') if reacts else ''
        lp = ('      <listOfProducts>\n' + prods +
              '      </listOfProducts>\n') if prods else ''
        rxn_chunks.append(
            f'    <reaction id="{rxn_name}" reversible="false" fast="false">\n'
            f'{lr}{lp}    </reaction>\n')
    xml = ('<?xml version="1.0" encoding="UTF-8"?>\n'
           '<sbml xmlns="http://www.sbml.org/sbml/level3/version1/core" '
           'level="3" version="1">\n'
           f'  <model id="{model_id}" name="Periodic Machine core-carbon '
           'metabolism">\n'
           '    <listOfCompartments>\n'
           '      <compartment id="cell" spatialDimensions="3" size="1" '
           'constant="true"/>\n'
           '    </listOfCompartments>\n'
           '    <listOfSpecies>\n' + sp_xml +
           '    </listOfSpecies>\n'
           '    <listOfReactions>\n' + ''.join(rxn_chunks) +
           '    </listOfReactions>\n'
           '  </model>\n'
           '</sbml>\n')
    if path:
        with open(path, 'w', encoding='utf-8') as f:
            f.write(xml)
    return xml


def import_sbml(path_or_xml: str) -> Dict[str, Any]:
    """Parse an SBML Level-3 core document back into the engine's
    network representation — the inverse of export_sbml().

    Accepts a filesystem path or a raw XML string.  Reactant
    stoichiometries become negative coefficients, products positive —
    the same convention as FBA_REACTIONS, so the parsed network feeds
    straight back into fba_core_carbon(species=..., reactions=...).
    Only the SBML core is needed here (no layout/fbc packages); the
    parser is namespace-tolerant so Level-2 files also parse."""
    import os
    import xml.etree.ElementTree as ET
    if isinstance(path_or_xml, str) and os.path.exists(path_or_xml):
        with open(path_or_xml, 'r', encoding='utf-8') as f:
            text = f.read()
    elif isinstance(path_or_xml, str) and \
            not path_or_xml.lstrip().startswith('<'):
        raise FileNotFoundError(
            f'import_sbml: no such file: {path_or_xml!r}')
    else:
        text = path_or_xml
    root = ET.fromstring(text)
    ns = root.tag.split('}')[0] + '}' if root.tag.startswith('{') else ''
    model = root.find(f'{ns}model')
    if model is None:
        raise ValueError('import_sbml: no <model> element found')
    species = [s.get('id') for s in
               model.findall(f'{ns}listOfSpecies/{ns}species')]
    reactions: Dict[str, Dict[str, float]] = {}
    for rxn in model.findall(f'{ns}listOfReactions/{ns}reaction'):
        stoich: Dict[str, float] = {}
        for ref in rxn.findall(
                f'{ns}listOfReactants/{ns}speciesReference'):
            stoich[ref.get('species')] = \
                -float(ref.get('stoichiometry', '1'))
        for ref in rxn.findall(
                f'{ns}listOfProducts/{ns}speciesReference'):
            stoich[ref.get('species')] = \
                float(ref.get('stoichiometry', '1'))
        reactions[rxn.get('id')] = stoich
    return {'model_id': model.get('id'), 'species': species,
            'reactions': reactions,
            'n_species': len(species), 'n_reactions': len(reactions)}


# ---------------------------------------------------------------------------
# 3b-rna. RNA STRUCTURE + WOBBLE + THE LAC OPERON — the language's grammar
# ---------------------------------------------------------------------------
# RNA folds on itself through the same Watson-Crick pairs (A-U, G-C) plus
# the G-U wobble pair.  The Nussinov algorithm (Nussinov & Jacobson 1980)
# finds the maximum number of nested base pairs by dynamic programming —
# the real first-order model of RNA secondary structure (tRNA cloverleafs,
# ribozyme stems, riboswitch aptamers all start here).

NUSSINOV_MIN_LOOP = 3          # real hairpins need >= 3 unpaired nt to turn
RNA_PAIR_TYPES = {
    ('A', 'U'): -1.5, ('U', 'A'): -1.5,   # mean stacked AU ~ -1 to -2 kcal/mol
    ('G', 'C'): -2.3, ('C', 'G'): -2.3,   # mean stacked GC ~ -2 to -3
    ('G', 'U'): -0.9, ('U', 'G'): -0.9,   # wobble pair ~ -1
}


def nussinov_fold(rna: str, min_loop: int = NUSSINOV_MIN_LOOP
                  ) -> Optional[Dict[str, Any]]:
    """Max-base-pair RNA secondary structure via Nussinov DP.

    Returns the dot-bracket structure, pair count, and an approximate
    stacking free energy (per-pair mean estimates — honest coarse model,
    not full Turner nearest-neighbor parameters).  Only defined for real
    RNA letters A/U/C/G."""
    s = rna.upper().replace('T', 'U')
    if not s or any(b not in 'AUCG' for b in s):
        return None
    n = len(s)
    N = [[0] * n for _ in range(n)]
    take = [[False] * n for _ in range(n)]

    def pair_ok(i: int, j: int) -> bool:
        return (s[i], s[j]) in RNA_PAIR_TYPES and j - i > min_loop

    for span in range(1, n):
        for i in range(n - span):
            j = i + span
            best = N[i + 1][j]
            if N[i][j - 1] > best:
                best = N[i][j - 1]
            if pair_ok(i, j) and N[i + 1][j - 1] + 1 > best:
                best = N[i + 1][j - 1] + 1
                take[i][j] = True
            for k in range(i + 1, j):
                if N[i][k] + N[k + 1][j] > best:
                    best = N[i][k] + N[k + 1][j]
                    take[i][j] = False
            N[i][j] = best
    # Traceback -> pairs + dot-bracket
    pairs: List[Tuple[int, int]] = []
    stack = [(0, n - 1)]
    while stack:
        i, j = stack.pop()
        if i >= j:
            continue
        if N[i][j] == N[i + 1][j]:
            stack.append((i + 1, j))
        elif N[i][j] == N[i][j - 1]:
            stack.append((i, j - 1))
        elif take[i][j] and N[i][j] == N[i + 1][j - 1] + 1:
            pairs.append((i, j))
            stack.append((i + 1, j - 1))
        else:
            for k in range(i + 1, j):
                if N[i][j] == N[i][k] + N[k + 1][j]:
                    stack.append((i, k))
                    stack.append((k + 1, j))
                    break
    dot = ['.'] * n
    dg = 0.0
    for i, j in pairs:
        dot[i], dot[j] = '(', ')'
        dg += RNA_PAIR_TYPES[(s[i], s[j])]
    return {
        'structure':   ''.join(dot),
        'pairs':       len(pairs),
        'paired_frac': round(2 * len(pairs) / n, 3),
        'approx_dG_kcal': round(dg, 1),
        'n_nt':        n,
        'note':        'Nussinov max-pairs; dG is per-pair mean estimate',
    }


# --- Crick wobble: why ~32 tRNAs read 61 codons ---------------------------
# The ribosome only strictly checks codon positions 1-2; the third base
# pairs with tRNA anticodon position 34 under relaxed 'wobble' geometry
# (Crick 1966).  Permitted pairings, anticodon 5' base -> codon 3' bases:
#     U -> A or G      G -> U or C      C -> G      A -> U
#     I (inosine, deaminated A in the wobble position) -> U, C, or A
WOBBLE_RULES: Dict[str, str] = {
    'U': 'AG', 'G': 'UC', 'C': 'G', 'A': 'U', 'I': 'UCA',
}


def trnas_required(with_inosine: bool = False) -> Dict[str, Any]:
    """Minimum tRNA species to read all 61 sense codons under Crick wobble.

    Anticodon positions 35-36 must Watson-Crick-match codon positions 1-2,
    and a tRNA carries ONE amino acid — so coverage groups are codons
    sharing first-two bases AND amino acid.  Within a group only the 3'
    codon base varies; find the smallest set of wobble anticodon bases
    covering every ending actually used."""
    allowed = {k: set(v) for k, v in WOBBLE_RULES.items()}
    if not with_inosine:
        allowed.pop('I')
    groups: Dict[Tuple[str, str], set] = {}
    for codon, aa in GENETIC_CODE.items():
        if aa == '*':
            continue
        end3 = 'U' if codon[2] == 'T' else codon[2]   # codon table is DNA
        groups.setdefault((aa, codon[:2]), set()).add(end3)
    total = 0
    detail = []
    for (aa, first2), endings in sorted(groups.items()):
        best = len(endings)
        for x1, cover1 in allowed.items():
            if endings <= cover1:
                best = 1
                break
        else:
            if any(endings <= (allowed[x1] | allowed[x2])
                   for x1 in allowed for x2 in allowed):
                best = 2
        total += best
        detail.append((aa, first2, ''.join(sorted(endings)), best))
    return {
        'min_trnas':   total,
        'inosine':     with_inosine,
        'n_groups':    len(groups),
        'note':        'Crick wobble set-cover; real cells carry more '
                       '(E. coli ~46 species) for abundance tuning',
    }


# --- The lac operon: real transcriptional logic ----------------------------
# Jacob & Monod 1961 (Nobel 1965).  LacI tetramer binds the operator and
# blocks RNA Pol; allolactose (made from lactose) binds LacI and releases
# it.  Glucose starves adenylyl cyclase -> cAMP falls -> CAP cannot bind
# -> weak initiation even when derepressed (catabolite repression).
# Induction is famously ~1000x between OFF and fully ON states.
LAC = {
    'ki_inducer_mM':   0.5,    # allolactose/IPTG effective Kd ~0.1-1 mM
    'kg_glucose_mM':   0.5,    # glucose level halving CAP-cAMP activity
    'basal_leak':      0.001,  # ~1 transcript / 1000 cells even when OFF
    'cap_gain':        0.97,   # CAP contributes ~50x over weak basal Pol
}


def lac_operon_state(glucose_mM: float, lactose_mM: float) -> Dict[str, Any]:
    """Lac-operon expression state for (glucose, lactose) — real gene logic.

    repressor_off = fraction of time LacI is inducer-bound (inactive);
    cap_on = CAP-cAMP activation level; expression = leak + derepressed x
    (weak basal + CAP gain).  Fold induction is relative to the OFF state."""
    rep_off = lactose_mM / (LAC['ki_inducer_mM'] + lactose_mM) \
        if lactose_mM > 0 else 0.0
    cap_on = 1.0 / (1.0 + glucose_mM / LAC['kg_glucose_mM']) \
        if glucose_mM >= 0 else 0.0
    weak = 1.0 - LAC['cap_gain']
    expr = LAC['basal_leak'] + rep_off * (weak + LAC['cap_gain'] * cap_on)
    fold = expr / LAC['basal_leak']
    state = ('OFF — LacI bound' if rep_off < 0.1 else
             'INDUCED' if rep_off > 0.4 else 'intermediate')
    if rep_off >= 0.4:
        state += (' + CAP active (full ~1000x)' if cap_on > 0.5 else
                  ' but catabolite-repressed (glucose present)')
    return {
        'expression':      round(expr, 4),
        'fold_induction':  round(fold, 1),
        'repressor_off':   round(rep_off, 3),
        'cap_active':      round(cap_on, 3),
        'state':           state,
    }


# ---------------------------------------------------------------------------
# 3b-allo. ALLOSTERY + INHIBITION + SIGNAL CASCADE — regulation physics
# ---------------------------------------------------------------------------
# Monod-Wyman-Changeux (1965) is the mechanistic model behind the empirical
# Hill curve used above: a protein exists in R (relaxed, high-affinity) and
# T (tense, low-affinity) conformations, and ligand binding shifts the
# equilibrium.  For n subunits with alpha = [S]/K_R:
#   Y = [a(1+a)^(n-1) + L·ca(1+ca)^(n-1)] / [(1+a)^n + L(1+ca)^n]
# Hemoglobin parameters: n=4, L ~ 9000 (T strongly favoured empty),
# c = K_R/K_T ~ 0.014 — reproduces the measured sigmoid (Hill ~2.8).
MWC = {
    'n_subunits': 4,
    'L0':         9054.0,    # T/R equilibrium, unliganded (IUPHAR fit)
    'c':          0.014,     # affinity ratio K_R/K_T
    'KR_mmHg':    2.65,      # R-state O2 dissociation — fit to p50 ~ 26
}


def mwc_saturation(po2_mmHg: float) -> float:
    """MWC fractional saturation for hemoglobin — the mechanistic sigmoid."""
    a = po2_mmHg / MWC['KR_mmHg']
    n, L, c = MWC['n_subunits'], MWC['L0'], MWC['c']
    num = a * (1 + a) ** (n - 1) + L * c * a * (1 + c * a) ** (n - 1)
    den = (1 + a) ** n + L * (1 + c * a) ** n
    return num / den if den > 0 else 0.0


def mwc_r_fraction(po2_mmHg: float) -> float:
    """Fraction of molecules in the high-affinity R state at this pO2."""
    a = po2_mmHg / MWC['KR_mmHg']
    n, L, c = MWC['n_subunits'], MWC['L0'], MWC['c']
    r = (1 + a) ** n
    return r / (r + L * (1 + c * a) ** n)


def mwc_hill_coefficient() -> Dict[str, float]:
    """Effective Hill coefficient + p50 implied by the MWC parameters —
    derived by bisection on the saturation curve, not asserted."""
    lo, hi = 1e-3, 500.0
    for _ in range(80):
        mid = math.sqrt(lo * hi)
        if mwc_saturation(mid) < 0.5:
            lo = mid
        else:
            hi = mid
    p50 = math.sqrt(lo * hi)
    y = 0.5
    eps = 1e-4 * p50
    dY = (mwc_saturation(p50 + eps) - mwc_saturation(p50 - eps)) / (2 * eps)
    n_eff = 4.0 * p50 * dY / (4.0 * y * (1.0 - y))   # Hill slope at 50%
    return {'p50_mmHg': p50, 'hill_n_effective': n_eff}


def enzyme_inhibition(substrate_mM: float, vmax: float, km: float,
                      inhibitor_mM: float = 0.0, ki_mM: float = 1.0,
                      mode: str = 'competitive') -> Dict[str, float]:
    """Michaelis-Menten rate under reversible inhibition (real pharmacology).

    competitive:    alpha scales Km   (inhibitor fights for the active site)
    noncompetitive: alpha scales Vmax (inhibitor binds elsewhere, E+I dead)
    uncompetitive:  binds ES only -> both Km and Vmax scaled down by alpha
    mixed:          independent alpha (Km) / alpha' (Vmax)"""
    a = 1.0 + (inhibitor_mM / ki_mM if ki_mM > 0 else 0.0)
    if mode == 'competitive':
        km_app, vmax_app = km * a, vmax
    elif mode == 'noncompetitive':
        km_app, vmax_app = km, vmax / a
    elif mode == 'uncompetitive':
        km_app, vmax_app = km / a, vmax / a
    else:  # mixed
        km_app, vmax_app = km * a, vmax / a
    v = michaelis_menten(substrate_mM, vmax_app, km_app)
    return {'v': v, 'km_apparent': km_app, 'vmax_apparent': vmax_app,
            'mode': mode, 'alpha': a}


# --- Signal amplification cascades ----------------------------------------
# One receptor molecule can move thousands of second messengers — this is
# why cells detect single molecules.  Visual phototransduction (Stryer):
# 1 photoactivated rhodopsin activates ~150 transducins over its ~40 ms
# lifetime (mammalian rod); each active PDE hydrolyses ~2000 cGMP/s.
# beta-adrenergic GPCR: ~10-100 Gs-alpha per receptor, adenylyl cyclase
# ~1000 cAMP/s, and PKA then phosphorylates many targets each.
SIGNAL_CASCADE = {
    'visual': {'name': 'phototransduction',
               'second_step_gain': 150,      # transducins / rhodopsin lifetime
               'third_step_rate_s': 2000,    # cGMP hydrolysed / active PDE / s
               'response_s': 0.3},           # open time ~300 ms
    'gpcr':   {'name': 'beta-adrenergic GPCR',
               'second_step_gain': 100,      # Gs-alpha per occupied receptor
               'third_step_rate_s': 1000,    # cAMP / adenylyl cyclase / s
               'response_s': 1.0},
}


def signal_amplification(cascade: str = 'visual') -> Dict[str, float]:
    """Total molecular amplification of one receptor activation event."""
    if cascade not in SIGNAL_CASCADE:
        raise ValueError(f'signal_amplification: cascade must be one of '
                         f'{sorted(SIGNAL_CASCADE)}, got {cascade!r}')
    c = SIGNAL_CASCADE[cascade]
    third = c['second_step_gain'] * c['third_step_rate_s'] * c['response_s']
    return {
        'cascade':        c['name'],
        'second_messenger_gain': c['second_step_gain'],
        'amplification':  third,
        'note': 'one receptor -> ~10^4-10^5 downstream molecules '
                '(single-photon vision rests on this)',
    }


# --- Krogh tissue oxygenation ----------------------------------------------
# The Krogh-Erlang model (1919, Nobel): each capillary supplies a tissue
# cylinder; pO2 falls quadratically-outward under consumption q.
#   p(r) = p_c - (q/2K)·[r_t^2·ln(r/r_c) - (r^2-r_c^2)/2]
# K = D_O2 · solubility ~ (1.5e-5 cm2/s)·(3.2e-5 mL/mL/mmHg) for muscle.
# The critical radius where p -> 0 is the hard diffusion limit on tissue —
# the reason capillary spacing in muscle is ~20-50 um.
KROGH = {
    'capillary_r_um':    3.0,       # single-endothelium capillary
    'tissue_r_um':       30.0,      # typical half-spacing in muscle
    'p_cap_mmHg':        40.0,      # mean capillary pO2 at the venous end
    'o2_conductivity':   4.8e-10,   # mL O2 /(cm·s·mmHg) = D·alpha
    'q_rest_mL_cm3_s':   2.5e-5,    # resting skeletal muscle
    'q_exercise_mL_cm3_s': 5.0e-4,  # heavy exercise ~20x
}


def krogh_drop_mmHg(r_tissue_um: float, q_mL_cm3_s: float,
                    r_cap_um: float = None) -> float:
    """pO2 fall from capillary wall to the cylinder edge (mmHg)."""
    rc = (r_cap_um or KROGH['capillary_r_um']) * 1e-4   # um -> cm
    rt = r_tissue_um * 1e-4
    if rt <= rc:
        return 0.0
    K = KROGH['o2_conductivity']
    return (q_mL_cm3_s / (2 * K)) * \
        (rt * rt * math.log(rt / rc) - (rt * rt - rc * rc) / 2.0)


def krogh_critical_radius_um(q_mL_cm3_s: float,
                             p_cap_mmHg: float = None) -> Optional[float]:
    """Tissue-cylinder radius at which rim pO2 reaches zero (um)."""
    pc = p_cap_mmHg if p_cap_mmHg is not None else KROGH['p_cap_mmHg']
    f = lambda rt_um: krogh_drop_mmHg(rt_um, q_mL_cm3_s) - pc
    lo, hi = KROGH['capillary_r_um'] * 1.001, 2000.0
    if f(hi) < 0:
        return None                       # O2 never exhausted within 2 mm
    for _ in range(100):
        mid = (lo + hi) / 2
        if f(mid) < 0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


# --- Passive cable properties of neurons -----------------------------------
# Electrotonus: a steady voltage decays exp(-x/lambda) along a dendrite;
# lambda = sqrt(d·R_m / 4·R_i) for a cylindrical neurite.  tau = R_m·C_m
# sets the integration window.  Real values: lambda ~0.1-1 mm, tau ~1-50 ms
# — the physical reason dendrites are short and brains need myelin.
CABLE = {
    'R_m_ohm_cm2': 10_000.0,    # specific membrane resistance
    'R_i_ohm_cm':     150.0,    # axoplasm resistivity
    'C_m_uF_cm2':       1.0,    # membrane capacitance
}


def cable_properties(diameter_um: float) -> Dict[str, float]:
    """Space (lambda) and time (tau) constants for a cylindrical neurite."""
    d_cm = max(0.0, diameter_um) * 1e-4
    lam_cm = math.sqrt(d_cm * CABLE['R_m_ohm_cm2'] / (4.0 * CABLE['R_i_ohm_cm']))
    tau_s = CABLE['R_m_ohm_cm2'] * CABLE['C_m_uF_cm2'] * 1e-6
    return {
        'lambda_mm': lam_cm * 10.0,
        'tau_ms':    tau_s * 1000.0,
        'diameter_um': diameter_um,
        'v_decay_1mm': math.exp(-1.0 / max(1e-9, lam_cm * 10.0)),
    }


# --- Biosynthesis cost of building a cell ----------------------------------
# Making a cell is expensive: ~4 high-energy bonds per peptide bond,
# ~2 per polymerised nucleotide, ~4 per deoxynucleotide (incorporation +
# ribose reduction), ~2 acetyl-CoA (~4 ATP-equiv) per lipid tail carbon
# pair.  Stouthamer's Y_ATP ~10 g dry biomass per mol ATP ties this to
# growth-yield measurements.
Y_ATP_G_PER_MOL = 10.0        # g dry biomass / mol ATP (Stouthamer 1973)


def biosynthesis_cost(dry_mass_pg: float = 0.28) -> Dict[str, float]:
    """ATP equivalents needed to build one cell of given dry mass (pg).

    Default 0.28 pg = E. coli.  Composition comes from the same Neidhardt
    dry-mass fractions used by cell_composition() so the books balance."""
    comp = CELL_COMPOSITION
    g = dry_mass_pg * 1e-12
    NA = 6.022e23
    aa_mol = g * comp['protein'] / 110.0      # mean residue 110 Da
    nt_mol = g * comp['rna'] / 330.0          # mean NMP 330 Da
    bp_mol = g * comp['dna'] / 660.0          # mean dNMP pair 660 Da
    lipid_mol = g * comp['lipid'] / 750.0     # mean phospholipid ~750 Da
    atp = (aa_mol * 4.0 + nt_mol * 2.0 + bp_mol * 4.0
           + lipid_mol * 40.0) * NA
    return {
        'atp_per_cell':    atp,
        'atp_billions':    atp / 1e9,
        'dry_mass_pg':     dry_mass_pg,
        'glucose_equiv_pg': atp / 32.0 * 180.156 / NA * 1e12,
        'Y_atp_check_g':   Y_ATP_G_PER_MOL,
        'dominant_cost':   'protein synthesis (~4 ATP-equiv/peptide bond)',
    }


# --- Germline + somatic mutation rates --------------------------------------
# Real rates per generation (Drake et al. 1998; Jonsson et al. 2017):
#   human de novo SNV  ~1.2e-8 /bp/generation -> ~60-70 new mutations/child
#   strong paternal bias (~4:1) + ~1.5 extra mutations per paternal year
#   E. coli ~1e-3 /genome/replication (4.6 Mbp x ~2e-10 /bp)
#   somatic cells accrue ~1-5e-9 /bp/year — cancer needs ~7 driver hits.
MUTATION_RATES = {
    'human_snv_per_bp_gen': 1.2e-8,
    'human_genome_haploid_bp': 3.0e9,
    'paternal_age_per_year':  1.5,     # extra de novo SNVs / father-year
    'paternal_fraction':      0.8,     # ~80% of de novo SNVs are paternal
    'ecoli_per_genome_rep':   1e-3,
    'somatic_per_bp_year':    3e-9,
}


def germline_mutations(mother_age: float = 30.0,
                       father_age: float = 30.0) -> Dict[str, float]:
    """Expected de novo SNVs per child — real human germline numbers.

    Jonsson et al. 2017 (Iceland, 14k trios): ~60-70 de novo SNVs per
    child at typical parental age, ~80% paternal; the count grows ~1.5
    per father-year and ~0.4 per mother-year (oocyte divisions are fixed,
    spermatogonia divide ~23x/yr).  Anchored at ~40 SNVs for 20-yr-old
    parents so the 30/30 case lands on the measured ~60."""
    expected = (40.0
                + max(0.0, father_age - 20.0)
                  * MUTATION_RATES['paternal_age_per_year']
                + max(0.0, mother_age - 20.0) * 0.4)
    return {
        'expected_de_novo_snvs': expected,
        'per_bp_per_gen':        MUTATION_RATES['human_snv_per_bp_gen'],
        'per_bp_implied':        expected /
            (2.0 * MUTATION_RATES['human_genome_haploid_bp']),
        'paternal_share':        MUTATION_RATES['paternal_fraction'],
        'note': 'age effect concentrated in fathers (spermatogonial '
                'divisions ~23/yr vs fixed oocyte pool)',
    }


# --- Morphogen gradients: real positional information -----------------------
# Wolpert's French flag: a source-secreted morphogen that diffuses and
# decays sets up C(x) = C0·exp(-x/lambda) with lambda = sqrt(D/k).
# Cells read their LOCAL concentration against thresholds -> stripes of
# gene expression.  Bicoid in the Drosophila embryo is the textbook case
# (L ~ 500 um, lambda ~ 100 um ~ L/5, D ~ 0.2-1 um2/s in embryo
# cytoplasm, half-life ~30-50 min).
MORPHOGEN = {
    'diffusion_um2_s':  2.0,     # Bicoid D: measured 0.11-7 um2/s (FRAP
                               # studies disagree — mid-range default)
    'halflife_s':       2700.0,  # ~45 min measured for Bicoid
    'embryo_len_um':    500.0,   # Drosophila syncytium
    'c0_nM':            55.0,    # anterior Bicoid peak
}


def morphogen_lambda(diffusion_um2_s: float = None,
                     halflife_s: float = None) -> float:
    """Characteristic decay length lambda = sqrt(D/k), k = ln2/t_half."""
    D = diffusion_um2_s if diffusion_um2_s is not None \
        else MORPHOGEN['diffusion_um2_s']
    hl = halflife_s if halflife_s is not None else MORPHOGEN['halflife_s']
    k = math.log(2.0) / max(1e-9, hl)
    return math.sqrt(D / k)


def french_flag_positions(threshold_nM: List[float],
                          c0_nM: float = None,
                          diffusion_um2_s: float = None,
                          halflife_s: float = None) -> Dict[str, Any]:
    """Boundary positions where C(x)=threshold — real French-flag pattern.

    x_i = lambda·ln(C0/T_i); thresholds must be < C0.  Returns each
    boundary plus whether the embryo is patterned across its length."""
    c0 = c0_nM if c0_nM is not None else MORPHOGEN['c0_nM']
    lam = morphogen_lambda(diffusion_um2_s, halflife_s)
    L = MORPHOGEN['embryo_len_um']
    bounds = []
    for t in sorted(threshold_nM, reverse=True):
        if 0 < t < c0:
            bounds.append({'threshold_nM': t, 'x_um': lam * math.log(c0 / t)})
    return {
        'lambda_um':      lam,
        'lambda_over_L':  lam / L,
        'boundaries':     bounds,
        'c0_nM':          c0,
        'note': 'steady-state exp(-x/lambda) source-decay gradient; '
                'measured Bicoid lambda ~ 100 um ~ L/5',
    }


# --- Eigen error threshold: why genomes can't be arbitrarily sloppy --------
# Eigen's quasispecies theory (1971): a replicator of length L with per-base
# error rate q keeps its master sequence only while  q·L < ln(sigma),
# where sigma is the superiority (fitness ratio) of the master over the
# mutant cloud.  Past the error threshold the information melts — this is
# the real bound on genome size vs polymerase fidelity:
#   RNA virus  q ~ 1e-4  ->  Lmax ~ 10^4 nt   (influenza ~14 kb — at edge)
#   bacteria   q ~ 1e-9  ->  Lmax ~ 10^9 bp   (4.6 Mbp — huge headroom)
# The engine's per-alphabet error_rates are therefore *predictive*: the
# 8-base alphabet at q=0.11 cannot stably maintain a long genome at all.
EIGEN = {
    'sigma_typical': 2.0,     # master twice as fit as mutant average
    'rna_virus_q':   1e-4,    # RNA Pol II error — no proofreading
    'ecoli_q':       1e-9,    # pol + proofreading + MMR cascade
}


def error_threshold_genome_len(per_base_err: float,
                               sigma: float = None) -> Dict[str, float]:
    """Maximum stable genome length Lmax = ln(sigma)/q (Eigen 1971).

    At lengths beyond Lmax the error catastrophe wins: offspring carry
    ~1+ mutations each and the master sequence is lost to the mutant
    cloud.  Returns the threshold plus mutations-per-replication at a
    given L for interpreting the engine's own alphabet error_rates."""
    sig = sigma if sigma is not None else EIGEN['sigma_typical']
    q = max(1e-12, per_base_err)
    lmax = math.log(max(1.0001, sig)) / q
    return {
        'per_base_err': q,
        'sigma':        sig,
        'lmax_bp':      lmax,
        'mutations_per_rep_at_lmax': q * lmax,   # ~ln(sigma) by definition
    }


def alphabet_error_budget(n_bases: int,
                          sigma: float = None) -> Dict[str, Any]:
    """Eigen threshold applied to each BASE_SYSTEMS error rate — the real
    reason the high-alphabet genomes are unstable."""
    if n_bases not in BASE_SYSTEMS:
        raise ValueError(f'alphabet_error_budget: n_bases must be one of '
                         f'{sorted(BASE_SYSTEMS)}, got {n_bases!r}')
    q = BASE_SYSTEMS[n_bases]['error_rate']
    t = error_threshold_genome_len(q, sigma)
    t['n_bases'] = n_bases
    t['verdict'] = ('stable for long genomes' if t['lmax_bp'] > 1e4 else
                    'short-genome regime only' if t['lmax_bp'] > 50 else
                    'error catastrophe — cannot hold a genome')
    return t


# ---------------------------------------------------------------------------
# 3d. XENOBIOLOGY — the engine's expanded alphabets map onto REAL published
#     synthetic base pairs, not invented chemistry
# ---------------------------------------------------------------------------
# Natural DNA is not the only possible alphabet.  Real xenobiology has
# built, replicated, and TRANSCRIBED expanded genetic systems:
#   * Benner lab AEGIS — dZ:dP pair replicated by DNA polymerases and
#     transcribed by RNA polymerases in vitro (Yang et al. 2011, NAR 39:6305);
#     earlier isoG:isoC pairs (Switzer/Moroney/Benner 1989-1993).
#   * Hachimoji DNA/RNA — a complete 8-letter system A-T, C-G, Z-P, S-B
#     (Hoshika et al. 2019, Science 363:884) that forms orthogonally-pairing
#     duplexes, is transcribed into hachimoji RNA, and stores 2× the
#     information density of DNA.
#   * Expanded codons encode extra amino acids — a 21st nonstandard amino
#     acid was incorporated using an expanded-alphabet codon (Bain et al.
#     1992; reviewed in Hoshika & Benner 2020).
# So the 'hexary' (X·Y) and 'octary' (X·Y, W·Z) alphabets below are mapped
# to the closest real synthetic pairs — the letters are abstract but the
# chemistry they stand in for is published.
XENO_BIOLOGY: Dict[int, Dict[str, Any]] = {
    4: {'pairs': {'A:T': 'adenine-thymine (2 H-bonds)',
                  'C:G': 'cytosine-guanine (3 H-bonds)'},
        'real_system': 'natural DNA', 'transcribed': True,
        'ref': 'Watson & Crick 1953'},
    6: {'pairs': {'A:T': 'adenine-thymine', 'C:G': 'cytosine-guanine',
                  'X:Y': 'stands in for dZ:dP — Benner AEGIS pair '
                         '(pyridone-imidazotriazinone, 3 H-bonds, '
                         'orthogonally replicating)'},
        'real_system': 'AEGIS 6-letter (dZ:dP added)',
        'transcribed': True,
        'ref': 'Yang et al. 2011 NAR 39:6305'},
    8: {'pairs': {'A:T': 'adenine-thymine', 'C:G': 'cytosine-guanine',
                  'X:Y': 'stands in for dZ:dP (hachimoji Z:P)',
                  'W:Z': 'stands in for dS:dB — isoGuanine:isoCytosine '
                         '(hachimoji S:B, 3 H-bonds)'},
        'real_system': 'hachimoji 8-letter DNA/RNA',
        'transcribed': True,
        'ref': 'Hoshika et al. 2019 Science 363:884'},
}

# Documented purine/pyrimidine-consistent projection used to show an XNA
# genome through the (natural) standard genetic code: the two extra pairs
# are mapped to the natural pair of the same geometry, so codon identity
# is preserved modulo pair swap, NOT scrambled randomly.  X,W occupy the
# "new purine" slots (X→G, W→A); Y,Z the "new pyrimidine" slots (Y→C, Z→T).
XNA_TO_DNA: Dict[str, str] = {'X': 'G', 'Y': 'C', 'W': 'A', 'Z': 'T'}


def project_xna_to_dna(seq: str, n_bases: int) -> str:
    """Project an expanded-alphabet sequence onto DNA for translation,
    preserving purine/pyrimidine geometry and pair identity.  Used by the
    genetic-code panel — documented as a lossy (4-letter shadow) map, the
    same trick real hachimoji papers use when discussing codon tables."""
    seq = seq.upper()
    if n_bases <= 4:
        return seq
    bases = BASE_SYSTEMS[n_bases]['bases']
    proj = {b: XNA_TO_DNA.get(b, 'ATCG'[i % 4]) for i, b in enumerate(bases)}
    return ''.join(proj.get(c, 'A') for c in seq)


def expanded_alphabet_facts(n_bases: int) -> Dict[str, Any]:
    """Real xenobiology anchoring for the selected alphabet size."""
    if n_bases not in XENO_BIOLOGY:
        raise ValueError(f'expanded_alphabet_facts: n_bases must be one of '
                         f'{sorted(XENO_BIOLOGY)}, got {n_bases!r}')
    x = XENO_BIOLOGY[n_bases]
    codon_space = n_bases ** 3
    return {**x, 'n_bases': n_bases,
            'triplet_codons': codon_space,
            'vs_natural_64': f"{codon_space}/64 = {codon_space/64:.1f}x "
                             "codon space",
            'extra_aa_note': ('natural code uses 61 sense codons for 20 aa'
                              if n_bases == 4 else
                              'real work: expanded-alphabet codons have '
                              'encoded nonstandard amino acids (Bain 1992; '
                              'hachimoji review 2020)')}


def selenocysteine_recoding() -> Dict[str, Any]:
    """The code is not frozen at 20 amino acids even in REAL biology:
    selenocysteine (21st aa, all domains of life) recodes UGA + SECIS
    stem-loop; pyrrolysine (22nd aa, some methanogens) recodes UAG via
    PylRS.  Proof that 'codon expansion' is biology, not fiction."""
    return {'sec': {'codon': 'UGA', 'signal': 'SECIS element (stem-loop)',
                    'machinery': 'SelB elongation factor + tRNA^Sec',
                    'proteins': 'glutathione peroxidase, formate '
                                'dehydrogenase, thioredoxin reductase'},
            'pyl': {'codon': 'UAG', 'signal': 'PYLIS (some species)',
                    'machinery': 'pyrrolysyl-tRNA synthetase (PylRS)',
                    'proteins': 'methylamine methyltransferases '
                                '(methanogens)'},
            'n_canonical': 20, 'n_with_recoding': 22}


def genetic_code_optimality(n_random: int = 300,
                            seed: int = 42) -> Dict[str, float]:
    """Is the standard genetic code an accident?  Measure its error-
    buffering: the mean |Δhydropathy| over all single-point mutations
    (each sense codon's 9 one-base neighbours; nonsense mutations cost a
    fixed penalty).  Compare against random codes with the same structure.
    Real result (Freeland & Hurst 2000): the natural code buffers errors
    better than ~99% of alternatives — it is a *selected* language."""
    if n_random <= 0:
        raise ValueError('genetic_code_optimality: n_random must be > 0')
    hydro = {a: p['hydropathy'] for a, p in AMINO_ACIDS.items()}
    STOP_PENALTY = max(hydro.values()) - min(hydro.values())   # ~9.0

    def code_cost(code: Dict[str, str]) -> float:
        tot, n = 0.0, 0
        for c, aa in code.items():
            if aa == '*':
                continue
            for pos in range(3):
                for b in 'TCAG':
                    if b == c[pos]:
                        continue
                    nb = c[:pos] + b + c[pos+1:]
                    other = code.get(nb, '*')
                    if other == '*':
                        tot += STOP_PENALTY
                    else:
                        tot += abs(hydro[aa] - hydro[other])
                    n += 1
        return tot / n

    real_cost = code_cost(GENETIC_CODE)
    codons = [c for c, a in GENETIC_CODE.items() if a != '*']
    stops  = {c: '*' for c, a in GENETIC_CODE.items() if a == '*'}
    aas = list(hydro.keys())
    rng = random.Random(seed)
    better = 0
    for _ in range(n_random):
        rcode = dict(stops)
        for c in codons:
            rcode[c] = aas[rng.randrange(len(aas))]
        if code_cost(rcode) <= real_cost:
            better += 1
    return {'real_cost': real_cost,
            'n_random': n_random,
            'random_beating_real': better,
            'percentile': 100.0 * (n_random - better) / n_random,
            'metric': 'mean |ΔKyte-Doolittle| over all point mutations '
                      '(stop hits penalized)'}


# ---------------------------------------------------------------------------
# 3e. MULTICELLULAR SPACE — Turing reaction-diffusion tissue patterning
# ---------------------------------------------------------------------------
# Infornmational.md's largest structural gap: "no spatial grid, diffusion,
# cell–cell signaling network".  This is a REAL developmental simulation:
# Gierer–Meinhardt activator–inhibitor kinetics on a 2-D grid produce
# stripes/spots from near-uniform initial conditions — the same mechanism
# proposed for zebrafish stripes, digit spacing and mammalian coat
# patterning (Kondo & Miura 2010).
#
#   ∂a/∂t = ρa + σ a²/h − μa·a + Da∇²a    (short-range self-activator)
#   ∂h/∂t = ρh + σ a²   − μh·h + Dh∇²h    (long-range inhibitor)
#
# The REAL Turing falsifiable prediction: patterns form ONLY when the
# inhibitor diffuses much faster than the activator (Dh >> Da).  We test
# both regimes.  The Laplacian is computed spectrally (FFT) — periodic
# boundaries, which is what most published demos assume.
def _spectral_laplacian(field: 'np.ndarray', dx: float) -> 'np.ndarray':
    rows, cols = field.shape
    fy = np.fft.fftfreq(rows)[:, None] * 2 * math.pi
    fx = np.fft.fftfreq(cols)[None, :] * 2 * math.pi
    k2 = (fx * fx + fy * fy) / (dx * dx)
    return np.fft.ifft2(np.fft.fft2(field) * (-k2)).real


def turing_pattern(rows: int = 48, cols: int = 48,
                   dx: float = 1.0, dt: float = 0.4,
                   Da: float = 0.005, Dh: float = 0.2,
                   rho_a: float = 0.003, rho_h: float = 0.0,
                   mu_a: float = 0.02, mu_h: float = 0.04,
                   sigma: float = 0.03,
                   steps: int = 3000,
                   seed: int = 42) -> Dict[str, Any]:
    """Gierer–Meinhardt activator-inhibitor on a periodic grid.
    Koch & Meinhardt 1994 parameter regime.  Returns pattern metrics:
    activator std (0 = homogeneous), dominant pattern wavelength, and the
    field itself (downsampled for display)."""
    if rows < 1 or cols < 1:
        raise ValueError(f'turing_pattern: grid must be >=1x1 '
                         f'(got {rows}x{cols})')
    if dx <= 0 or dt <= 0:
        raise ValueError('turing_pattern: dx and dt must be positive')
    if mu_a <= 0 or mu_h <= 0:
        raise ValueError('turing_pattern: mu_a and mu_h must be positive '
                         '(they divide the steady-state field)')
    if min(Da, Dh, sigma, rho_a, rho_h) < 0:
        raise ValueError('turing_pattern: rates and diffusivities must '
                         'be >= 0 (negative diffusion is ill-posed)')
    if steps < 0:
        raise ValueError('turing_pattern: steps must be >= 0')
    rng = np.random.RandomState(seed)
    a = rho_a / mu_a + 0.05 * rng.rand(rows, cols)
    h = (sigma * (rho_a / mu_a) ** 2 + rho_h) / mu_h + \
        0.05 * rng.rand(rows, cols)
    with np.errstate(over='ignore', invalid='ignore'):
        for _ in range(steps):
            a2 = a * a
            lap_a = _spectral_laplacian(a, dx)
            lap_h = _spectral_laplacian(h, dx)
            da = rho_a + sigma * a2 / np.maximum(h, 1e-9) - mu_a * a + Da * lap_a
            dh = rho_h + sigma * a2 - mu_h * h + Dh * lap_h
            a = np.clip(a + dt * da, 0.0, 1e6)
            h = np.clip(h + dt * dh, 0.0, 1e6)
    a = np.nan_to_num(a, nan=0.0, posinf=1e6)
    a = np.maximum(a, 0.0)
    # Dominant wavelength from the 2-D power spectrum peak (exclude DC).
    P = np.abs(np.fft.fft2(a - a.mean())) ** 2
    fy = np.fft.fftfreq(rows)[:, None]
    fx = np.fft.fftfreq(cols)[None, :]
    f = np.sqrt(fx * fx + fy * fy)
    f[0, 0] = 1.0
    kmax = np.unravel_index(np.argmax(P), P.shape)
    freq = f[kmax]
    # A flat field has no dominant mode (argmax lands on the excluded DC
    # bin or numerical noise) — report infinite wavelength, not dx.
    wavelength_um = ((1.0 / freq) * dx
                     if freq > 0 and P[kmax] > 1e-12 else float('inf'))
    return {'activator_std': float(a.std()),
            'activator_mean': float(a.mean()),
            'wavelength_um': float(wavelength_um),
            'rows': rows, 'cols': cols,
            'patterned': bool(a.std() > 0.15 * max(a.mean(), 1e-9)),
            'field_min': float(a.min()), 'field_max': float(a.max())}


def turing_condition(Da: float, Dh: float, dt: float = None,
                     **rxn) -> Dict[str, Any]:
    """REAL linear-stability test for diffusion-driven (Turing)
    instability at the nonzero homogeneous fixed point:
      homogeneous stable:  tr(J) < 0  and  det(J) > 0
      unstable w/ diffusion: Dh·Jaa + Da·Jhh > 0
    Requires Dh/Da above a critical ratio — the theorem that makes
    'morphogen patterns' testable rather than vibes."""
    p = dict(rho_a=0.003, rho_h=0.0, mu_a=0.02, mu_h=0.04, sigma=0.03)
    p.update(rxn)
    a_eq = (p['rho_a'] + p['sigma'] * 0 + p['mu_a'] * 0)  # solve numerically
    # Nonzero fixed point: from dh=0 -> h = (sigma a² + rho_h)/mu_h; plug
    # into da=0: rho_a + sigma a²/h - mu_a a = 0.  Solve by bisection.
    def fa(x):
        h = (p['sigma'] * x * x + p['rho_h']) / p['mu_h']
        return p['rho_a'] + p['sigma'] * x * x / max(h, 1e-12) - p['mu_a'] * x
    lo, hi = 1e-6, 1e4
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if fa(lo) * fa(mid) <= 0:
            hi = mid
        else:
            lo = mid
    a_eq = 0.5 * (lo + hi)
    h_eq = (p['sigma'] * a_eq * a_eq + p['rho_h']) / p['mu_h']
    # Jacobian by central differences.
    eps = 1e-6
    def rates(av, hv):
        aa2 = av * av
        return (p['rho_a'] + p['sigma'] * aa2 / max(hv, 1e-12) - p['mu_a'] * av,
                p['rho_h'] + p['sigma'] * aa2 - p['mu_h'] * hv)
    Jaa = (rates(a_eq + eps, h_eq)[0] - rates(a_eq - eps, h_eq)[0]) / (2 * eps)
    Jah = (rates(a_eq, h_eq + eps)[0] - rates(a_eq, h_eq - eps)[0]) / (2 * eps)
    Jha = (rates(a_eq + eps, h_eq)[1] - rates(a_eq - eps, h_eq)[1]) / (2 * eps)
    Jhh = (rates(a_eq, h_eq + eps)[1] - rates(a_eq, h_eq - eps)[1]) / (2 * eps)
    tr = Jaa + Jhh
    det = Jaa * Jhh - Jah * Jha
    hom_stable = tr < 0 and det > 0
    diff_drives = Dh * Jaa + Da * Jhh > 0
    return {'a_eq': a_eq, 'h_eq': h_eq, 'J': (Jaa, Jah, Jha, Jhh),
            'trJ': tr, 'detJ': det,
            'homogeneous_stable': bool(hom_stable),
            'turing_possible': bool(hom_stable and diff_drives),
            'Dh_over_Da': Dh / max(Da, 1e-12)}


# ---------------------------------------------------------------------------
# 3f. DOUBLE-STRAND BREAK REPAIR — the mechanistic layer under 'consensus
#     voting'.  Real pathway choice is driven by cell-cycle phase and the
#     availability of a sister chromatid template.
# ---------------------------------------------------------------------------
# Real biology (Ceccaldi, Rondinelli & D'Andrea 2016; Scully et al. 2019):
#   * NHEJ (Ku70/80, DNA-PKcs, Lig4) — active all cycle, DOMINANT in G1
#     (no sister chromatid).  Fast (~30 min), usually precise for clean
#     ends but mutagenic (small indels) when ends need processing.
#   * Homologous recombination (BRCA1/2, RAD51) — only in S/G2 when a
#     sister chromatid exists; essentially error-free (copies sister).
#   * alt-EJ / MMEJ — microhomology-mediated backup; always deletes the
#     sequence between repeats.  The cancer-prone fallback.
DSB_PATHWAYS: Dict[str, Dict[str, Any]] = {
    'NHEJ': {'phases': 'G1/S/G2/M (dominant G1)',
             'mechanism': 'Ku70/80 end binding -> DNA-PKcs -> Lig4 ligation',
             'fidelity': 'usually precise; indels if ends processed',
             # Junction outcome distribution for a clean single break
             # (van Gent & van der Burg 2007; CRISPR-NHEJ repair studies):
             'outcomes': {'precise_religation': 0.60,
                          'small_indel_1_20bp': 0.30,
                          'large_del_or_rearrangement': 0.10},
             'time_min': 30},
    'HR':   {'phases': 'S/G2 only (sister chromatid required)',
             'mechanism': 'BRCA1/53BP1 antagonism -> MRN resection -> '
                          'RAD51 filament -> sister-templated synthesis',
             'fidelity': '~error-free (template copying)',
             'outcomes': {'precise': 0.95, 'LOH_or_conversion': 0.05},
             'time_min': 420},
    'MMEJ': {'phases': 'S/G2 backup when NHEJ+HR fail',
             'mechanism': 'PolQ microhomology annealing — always deletes',
             'fidelity': 'always mutagenic (deletion between repeats)',
             'outcomes': {'deletion_between_repeats': 1.0},
             'time_min': 180},
}


def dsb_pathway_choice(cell_phase: str,
                       sister_chromatid: bool = None) -> Dict[str, Any]:
    """Real DSB-repair pathway selection.  53BP1/RIF1 block resection in
    G1 -> NHEJ; in S/G2 BRCA1 promotes resection -> HR wins when a sister
    template exists.  Mutational signature follows the pathway."""
    phase = cell_phase.upper()
    if sister_chromatid is None:
        sister_chromatid = phase in ('S', 'G2')
    if phase in ('S', 'G2') and sister_chromatid:
        return {'pathway': 'HR', 'phase': phase,
                'reason': 'sister chromatid present; 53BP1 inhibited by '
                          'CDK activity -> MRN resection -> RAD51',
                'expected_indel_per_break': 0.05,
                'mutagenic': False,
                'outcomes': DSB_PATHWAYS['HR']['outcomes'],
                'time_min': DSB_PATHWAYS['HR']['time_min']}
    return {'pathway': 'NHEJ', 'phase': phase,
            'reason': ('G1 — no sister chromatid; Ku binds ends directly'
                       if phase == 'G1' else
                       'no sister chromatid available -> fast end joining'),
            'expected_indel_per_break':
                1 - DSB_PATHWAYS['NHEJ']['outcomes']['precise_religation'],
            'mutagenic': True,
            'outcomes': DSB_PATHWAYS['NHEJ']['outcomes'],
            'time_min': DSB_PATHWAYS['NHEJ']['time_min']}


def p53_dna_damage_decision(n_dsb: int, repair_failed: bool = False,
                            hrs: float = 6.0) -> Dict[str, Any]:
    """p53 the 'guardian of the genome' integrates DSB load over time:
    few breaks -> p21 arrest + repair; sustained/severe damage -> PUMA/
    BAX apoptosis.  The real threshold is ~10-20 persistent breaks for
    apoptosis commitment (Loewer et al. 2013 pulsing model)."""
    if repair_failed or n_dsb >= 20 or (n_dsb >= 10 and hrs >= 8):
        return {'decision': 'APOPTOSIS', 'effector': 'PUMA/BAX -> '
                'caspase-9 -> caspase-3',
                'reason': f'{n_dsb} persistent breaks over {hrs:.0f}h — '
                          'p53 pulses sustained -> pro-death genes win'}
    if n_dsb > 0:
        return {'decision': 'ARREST+REPAIR', 'effector': 'p21 -> CDK2 '
                'inhibition -> G1/S block; GADD45 repair',
                'reason': f'{n_dsb} breaks — transient p53 pulses arrest '
                          'cycle while repair proceeds'}
    return {'decision': 'NORMAL CYCLE', 'effector': 'p53 basally low',
            'reason': 'no damage signal'}


