def _revcomp_dna(s: str) -> str:
    return s.translate(str.maketrans('ATCG', 'TAGC'))[::-1]


CRISPR = {
    'system': 'S. pyogenes Cas9 (SpCas9)',
    'pam': 'NGG',
    'protospacer_len': 20,
    'cut_offset_bp': 3,            # ~3 bp upstream of the PAM (blunt)
    'seed_len': 10,                # PAM-proximal seed — near-perfect match req.
    'offtarget_mismatch_max': 3,   # published off-target tolerance
    'ref': 'Jinek et al. 2012; Hsu et al. 2013 (off-target landscape)',
}


def _count_mismatches(a: str, b: str) -> int:
    return sum(1 for x, y in zip(a, b) if x != y)


def crispr_scan(seq: str, guide: str = '', pam: str = 'NGG',
                phase: str = 'G1') -> Dict[str, Any]:
    """Scan a sequence for SpCas9 target sites: a 20-nt protospacer
    immediately 5' of an NGG PAM, on either strand.  For each site the
    guide match is scored as seed-region (PAM-proximal ~10 nt, must be
    near-perfect) + distal mismatches; sites within the published
    off-target tolerance are flagged.  Repair outcome is then routed
    through the engine's REAL DSB machinery — G1 -> NHEJ -> indels
    (knockout), S/G2 -> homology-directed repair."""
    s = seq.upper()
    g = guide.upper()
    L = CRISPR['protospacer_len']
    sites = []
    # + strand: protospacer = s[i-L:i], PAM = s[i:i+3] matching .GG
    for i in range(L, len(s) - 2):
        if s[i + 1:i + 3] == 'GG':
            proto = s[i - L:i]
            sites.append({'strand': '+', 'pam_idx': i,
                          'protospacer': proto, 'pam': s[i:i + 3],
                          'cut_idx': i - CRISPR['cut_offset_bp']})
    # - strand: PAM reads CCN on the + strand at s[i:i+3] == 'CC?'
    for i in range(0, len(s) - 2 - L):
        if s[i:i + 2] == 'CC':
            proto = _revcomp_dna(s[i + 3:i + 3 + L])
            sites.append({'strand': '-', 'pam_idx': i,
                          'protospacer': proto,
                          'pam': _revcomp_dna(s[i:i + 3]),
                          'cut_idx': i + 3 + CRISPR['cut_offset_bp']})
    on_target, off_targets = None, []
    if g:
        for st in sites:
            proto = st['protospacer']
            window = proto[len(proto) - len(g):] if len(g) <= len(proto) \
                else proto
            mm = _count_mismatches(window, g) + max(0, len(g) - len(proto))
            tail = min(CRISPR['seed_len'], len(g))
            seed_mm = _count_mismatches(window[len(window) - tail:],
                                        g[len(g) - tail:])
            st['mismatches'] = mm
            st['seed_mismatches'] = seed_mm
            if mm == 0:
                on_target = st
            elif mm <= CRISPR['offtarget_mismatch_max'] and seed_mm <= 1:
                off_targets.append(st)
    repair = dsb_pathway_choice(phase) if on_target else None
    return {'n_pam_sites': len(sites), 'sites': sites,
            'on_target': on_target, 'off_targets': off_targets,
            'repair_prediction': repair,
            'note': ('on-target guide -> 1 DSB -> '
                     + (repair['pathway'] + ' outcome' if repair else
                        'none (no guide/PAM match)'))}


def fatty_acid_synthesis(carbons: int = 16) -> Dict[str, Any]:
    """De novo lipogenesis on the FAS megasynthase (palmitate C16:0):
    acetyl-CoA primer + (C/2 − 1) malonyl-CoA; each malonyl-CoA costs
    1 ATP at acetyl-CoA carboxylase — the real rate-limiting step
    (citrate-activated, insulin-stimulated, the ACC drug target); each
    reduction cycle burns 2 NADPH (which is WHY the PPP exists at scale).
    Synthesis and beta-oxidation are different chemistries — the
    round-trip wastes ~30% as heat, which is why fat is stored, not
    cycled."""
    cycles = max(0, carbons // 2 - 1)
    ox = beta_oxidation(carbons)
    return {'cycles': cycles, 'malonyl_coa': cycles,
            'atp_acc': cycles, 'nadph': 2 * cycles,
            'nadph_source': 'PPP + malic enzyme',
            'oxidation_yield_atp': ox['atp_net'],
            'note': (f'C{carbons}: build costs {cycles} ATP + '
                     f'{2 * cycles} NADPH; burn yields ~{ox["atp_net"]:.0f} '
                     'ATP — not the reverse pathway (different enzymes, '
                     'different compartments)')}


def signal_peptide_analysis(protein: str) -> Dict[str, Any]:
    """von Heijne signal-peptide rules for Sec/SRP secretion:
      n-region: 1-5 residues, net positive charge (Lys/Arg);
      h-region: >= 7 uncharged hydrophobic residues — the helical core
                the signal recognition particle binds;
      c-region: small uncharged residues at -3 and -1 relative to the
                signal-peptidase cut site (the '(-3,-1) rule').
    Heuristic only — real prediction uses SignalP's neural nets — but
    the n/h/c grammar is the actual biological motif."""
    seq = protein.upper()
    if len(seq) < 12:
        return {'is_signal': False, 'reason': 'too short (<12 aa)'}
    n_pos = sum(1 for a in seq[:5] if a in 'KR')
    best_len, best_i = 0, 0
    i = 1
    while i < min(len(seq) - 7, 22):
        j = i
        while j < len(seq) and AMINO_ACIDS.get(seq[j], {}).get(
                'hydropathy', 0.0) >= 1.0:
            j += 1
        if j - i > best_len:
            best_len, best_i = j - i, i
        i += 1
    h_mean = (float(np.mean([AMINO_ACIDS.get(seq[k], {}).get('hydropathy', 0.0)
                             for k in range(best_i, best_i + best_len)]))
              if best_len else 0.0)
    cut = best_i + best_len
    c_ok = (best_len >= 7 and cut + 2 < len(seq)
            and seq[cut] in 'AGST' and seq[cut + 2] in 'AGST')
    is_sig = n_pos >= 1 and best_len >= 7 and h_mean >= 1.5
    return {'is_signal': is_sig, 'n_pos_charges': n_pos,
            'h_region_start': best_i, 'h_region_len': best_len,
            'h_region_hydropathy': round(h_mean, 2),
            'c_region_cut_motif': c_ok,
            'verdict': ('secreted / membrane-targeted via SRP-Sec'
                        if is_sig else 'cytosolic (no signal anchor)')}


PCR = {
    'taq_error_per_bp': 1e-4,        # Taq: no proofreading
    'pfu_q5_error_per_bp': 1e-6,     # engineered high-fidelity polymerases
    'efficiency_typical': 0.85,      # real per-cycle yield is NOT 2.0
}


def pcr_amplification(cycles: int = 30, efficiency: float = None,
                      amplicon_bp: int = 1000,
                      pol_error_per_bp: float = None) -> Dict[str, Any]:
    """Polymerase chain reaction — in-vitro exponential replication:
    yield = (1+ε)^n vs the ideal 2^n.  Fidelity: every position is copied
    n times, so errors accumulate ~n·q per base and the error-free
    fraction decays exp(−n·q·L).  This is the real reason high-fidelity
    polymerases exist: 30 cycles of Taq on a 1 kb amplicon leaves only
    ~5% of molecules error-free."""
    e = PCR['efficiency_typical'] if efficiency is None else efficiency
    q = PCR['taq_error_per_bp'] if pol_error_per_bp is None else pol_error_per_bp
    e = min(max(e, 0.0), 1.0)
    cycles = max(0, int(cycles))
    yld = (1.0 + e) ** cycles
    err_per_bp = cycles * q
    clean = math.exp(-err_per_bp * amplicon_bp)
    return {'cycles': cycles, 'efficiency': e,
            'yield_fold': yld, 'ideal_fold': 2.0 ** cycles,
            'errors_per_bp': err_per_bp,
            'error_free_fraction': clean,
            'note': (f'Taq (q={q:g}): {clean * 100:.1f}% of {amplicon_bp} bp '
                     f'amplicons error-free after {cycles} cycles — use a '
                     'proofreading polymerase for cloning')}


HEAT_SHOCK = {
    'rpoH_operon': 'sigma-32 (rpoH) regulon — E. coli',
    'rna_thermometer': ('the rpoH 5\' UTR base-pairs its own Shine-'
                        'Dalgarno box shut at 30 C and melts open above '
                        '~37 C — the mRNA IS the temperature sensor'),
    'transient_fold': 15.0, 'sustained_fold': 4.0,
    'hsp_fold': 10.0, 'lethal_c': 46.0,
    'ref': 'Morita et al. 1999; Yura & Nakahigashi 1999',
}


def heat_shock_response(temp_c: float = 42.0) -> Dict[str, Any]:
    """E. coli heat-shock: an rpoH mRNA thermometer controls sigma-32,
    which transcribes GroEL/DnaK chaperones.  Measured: sigma-32 spikes
    ~10-15x within ~5 min of a 30->42 C upshift, then relaxes to a ~4x
    sustained level; HSPs rise ~3-10x.  Above ~46 C denaturation outruns
    chaperones — lethal."""
    if temp_c < 37.0:
        s32 = hsp = 1.0
    elif temp_c <= 44.0:
        frac = (temp_c - 37.0) / 7.0
        s32 = 1.0 + (HEAT_SHOCK['transient_fold'] - 1.0) * frac
        hsp = 1.0 + (HEAT_SHOCK['hsp_fold'] - 1.0) * frac
    else:
        s32, hsp = HEAT_SHOCK['transient_fold'], HEAT_SHOCK['hsp_fold']
    return {'temp_c': temp_c, 'sigma32_fold_peak': round(s32, 1),
            'sigma32_fold_sustained': round(1 + (s32 - 1) * 0.3, 1),
            'hsp_fold': round(hsp, 1), 'lethal': temp_c >= HEAT_SHOCK['lethal_c'],
            'sensor': 'rpoH 5\' UTR RNA thermometer'}


