@dataclass
class Colony:
    """Simple colony model for quorum-sensing organisms.
    Tracks population count and shared signals."""
    cells: List[Dict] = field(default_factory=list)
    shared_signals: int = 0

    def add_cell(self, org_dict: Dict):
        self.cells.append(slim_organism_dict(org_dict))
        self.shared_signals += org_dict.get('quorum_signals', 0)

    @property
    def density(self) -> int:
        return len(self.cells)

    @property
    def quorum_active(self) -> bool:
        return self.shared_signals >= QUORUM_THRESHOLD

    def avg_fitness(self) -> float:
        if not self.cells:
            return 0.0
        return sum(c['fitness'] for c in self.cells) / len(self.cells)

    def spatial_quorum(self, cell_pitch_um: float = 1.0, **kw) -> Dict[str, Any]:
        """Spatially realistic quorum check: lay cells out at
        `cell_pitch_um` spacing and run AHL diffusion.  Cells whose
        *local* signal crosses the quorum threshold are active —
        a lone low-density cell never sees quorum in open medium."""
        n = len(self.cells)
        if n == 0:
            return {'n_active': 0, 'active': [], 'peak_signal': 0.0}
        # pack cells on a square lattice inside the field
        side = max(1, math.ceil(math.sqrt(n)))
        nx = max(24, side + 8)
        positions = [(4 + (i % side), 4 + (i // side)) for i in range(n)]
        res = simulate_quorum_field(positions, n_x=nx, n_y=nx, **kw)
        res['flat_quorum'] = self.quorum_active   # old counter, for comparison
        return res

    def summary(self) -> Dict:
        return {
            'density': self.density,
            'quorum_active': self.quorum_active,
            'shared_signals': self.shared_signals,
            'avg_fitness': round(self.avg_fitness(), 4),
            'motile_fraction': sum(1 for c in self.cells if c.get('motility')) / max(1, self.density),
        }


