def _validate_reference_library():
    """Verify every reference genome translates to the expected organism."""
    errors = []
    for ref in REFERENCE_LIBRARY:
        strand = Strand(ref['genome'], ref['n_bases'])
        bp = execute_genome_deterministic(strand, 'earth')

        viable = bp.systems_score() == 1.0
        if ref['expected_viable'] is not None and viable != ref['expected_viable']:
            errors.append(
                f"{ref['name']}: expected viable={ref['expected_viable']}, got {viable}")

        if ref['expected_parts']:
            if bp.parts_used != ref['expected_parts']:
                errors.append(
                    f"{ref['name']}: expected parts {ref['expected_parts']}, "
                    f"got {bp.parts_used}")

    return errors


# ---------------------------------------------------------------------------
# Genome Library — save/load full organism files to disk
# ---------------------------------------------------------------------------
# Each organism is stored as a .json file in a library folder.
# Large organisms (intelligent life, real microbe templates) are saved here
# because their genome strings are too large for the in-memory REFERENCE_LIBRARY.
#
# File schema:
#   {
#     "name": str,
#     "category": str,          # "microbe" | "viral" | "intelligent" | "evolved" | ...
#     "source": str,            # "real_template" | "generated" | "evolved"
#     "n_bases": int,
#     "env_name": str,
#     "genome": str,            # full genome string
#     "description": str,       # human-readable
#     "science_notes": str,     # real-world biology reference
#     "subsystems": [str],      # list of subsystem names encoded
#     "expected_grade": str,    # e.g. "S", "A"
#     "fitness": float,         # last evaluated fitness
#     "grade": str,
#     "parts_used": [str],
#     "complexes_formed": [str],
#     "behaviors": [str],
#     "intelligence_tier": int,
#     "saved_at": str,          # ISO timestamp
#     "version": str,           # language version
#   }

import os as _os
import json as _json
import datetime as _datetime

LIBRARY_FOLDER_NAME = "organism_library"
LIBRARY_DEFAULT_PATH = _os.path.join(
    _os.path.expanduser("~"), "CascadeProjects", LIBRARY_FOLDER_NAME
)


def get_library_path() -> str:
    """Return the current library folder path, creating it if needed.
    Falls back to a user-home folder when the default location is not
    writable (e.g. running from a protected install directory)."""
    candidates = [LIBRARY_DEFAULT_PATH,
                  _os.path.join(_os.path.expanduser('~'),
                                'periodic_machine_library')]
    for path in candidates:
        try:
            _os.makedirs(path, exist_ok=True)
            probe = _os.path.join(path, '.write_probe')
            with open(probe, 'w') as f:
                f.write('x')
            _os.remove(probe)
            return path
        except OSError:
            continue
    return _os.path.expanduser('~')


def organism_to_library_dict(org, name: str, category: str = 'generated',
                              source: str = 'generated',
                              description: str = '',
                              science_notes: str = '') -> dict:
    """Serialise an Organism + metadata to the library JSON schema."""
    bp = org.blueprint
    grade, grade_desc = org.structural_grade()
    tier_idx, tier_name, _ = bp.intelligence_level()
    return {
        'name':             name,
        'category':         category,
        'source':           source,
        'n_bases':          org.strand.n_bases,
        'env_name':         org.env_name if hasattr(org, 'env_name') else 'earth',
        'genome':           org.strand.seq,
        'description':      description,
        'science_notes':    science_notes,
        'subsystems':       list(bp.complexes_formed),
        'expected_grade':   grade,
        'fitness':          round(org.fitness, 6),
        'grade':            grade,
        'grade_desc':       grade_desc,
        'parts_used':       list(bp.parts_used),
        'unique_parts':     sorted(set(bp.parts_used)),
        'complexes_formed': list(bp.complexes_formed),
        'behaviors':        list(bp.behaviors),
        'intelligence_tier':tier_idx,
        'intelligence_name':tier_name,
        'intelligence_score': round(bp.intelligence_score, 6),
        'neural_score':     round(bp.neural_score(), 6),
        'homeostasis_score':round(bp.homeostasis_score(), 6),
        'energy_budget':    bp.energy_budget,
        'energy_cost':      bp.energy_cost,
        'motility':         bp.motility_capable(),
        'chemotaxis':       bp.chemotaxis_capable(),
        'flagella_count':   bp.flagella_count,
        'torque':           round(bp.torque, 2),
        'rpm':              round(bp.rpm, 1),
        'membrane_potential': round(bp.membrane_potential, 1),
        'viable':           bool(org.viable),
        'replication_prob': round(bp.replication_prob, 6),
        'base_error_rate':  org.strand.system['error_rate'],
        'saved_at':         _datetime.datetime.now().isoformat(timespec='seconds'),
        'version':          __version__,
        'engine':           'periodic_machine',
    }


def save_organism_to_library(org, name: str, category: str = 'generated',
                              source: str = 'generated',
                              description: str = '',
                              science_notes: str = '',
                              folder: str = None) -> str:
    """Save organism to library folder. Returns the saved file path."""
    folder = folder or get_library_path()
    _os.makedirs(folder, exist_ok=True)
    data = organism_to_library_dict(org, name, category, source,
                                    description, science_notes)
    safe_name = ''.join(c if c.isalnum() or c in '-_ ' else '_' for c in name)
    safe_name = safe_name.replace(' ', '_').strip('_') or 'organism'
    timestamp = _datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
    # Never overwrite an existing library file — append a counter if a
    # same-second save already produced this filename.
    filepath = _os.path.join(folder, f"{safe_name}_{timestamp}.json")
    n = 1
    while _os.path.exists(filepath):
        filepath = _os.path.join(
            folder, f"{safe_name}_{timestamp}_{n}.json")
        n += 1
    with open(filepath, 'w', encoding='utf-8') as fh:
        _json.dump(data, fh, indent=2, ensure_ascii=False)
    return filepath


def load_organism_from_file(filepath: str) -> dict:
    """Load an organism dict from a library JSON file."""
    with open(filepath, 'r', encoding='utf-8') as fh:
        return _json.load(fh)


def list_library_organisms(folder: str = None) -> list:
    """Return list of (filepath, summary_dict) for all .json files in folder."""
    folder = folder or get_library_path()
    if not _os.path.isdir(folder):
        return []
    results = []
    for fname in sorted(_os.listdir(folder)):
        if not fname.endswith('.json'):
            continue
        fpath = _os.path.join(folder, fname)
        try:
            with open(fpath, 'r', encoding='utf-8') as fh:
                data = _json.load(fh)
            summary = {
                'filepath':    fpath,
                'filename':    fname,
                'name':        data.get('name', fname),
                'category':    data.get('category', ''),
                'source':      data.get('source', ''),
                'grade':       data.get('grade', '?'),
                'fitness':     data.get('fitness', 0.0),
                'viable':      data.get('viable', False),
                'n_bases':     data.get('n_bases', 4),
                'genome_len':  len(data.get('genome', '')),
                'n_parts':     len(data.get('parts_used', [])),
                'behaviors':   data.get('behaviors', []),
                'intelligence_tier': data.get('intelligence_tier', 0),
                'intelligence_name': data.get('intelligence_name', ''),
                'description': data.get('description', ''),
                'saved_at':    data.get('saved_at', ''),
            }
            results.append(summary)
        except Exception:
            pass
    return results


def organism_from_library_dict(data: dict):
    """Reconstruct an Organism from a library dict. Returns (Organism, data)."""
    if not isinstance(data, dict):
        raise ValueError(
            f'organism_from_library_dict: expected dict, got '
            f'{type(data).__name__}')
    n_bases  = data.get('n_bases', 4)
    env_name = data.get('env_name', 'earth')
    genome   = data.get('genome', '')
    if not isinstance(genome, str):
        raise ValueError(
            f'organism_from_library_dict: genome must be a string, got '
            f'{type(genome).__name__}')
    if not isinstance(n_bases, int):
        raise ValueError(
            f'organism_from_library_dict: n_bases must be an int, got '
            f'{type(n_bases).__name__}')
    parts_saved = data.get('parts_used', [])
    if not isinstance(parts_saved, (list, tuple)):
        raise ValueError(
            'organism_from_library_dict: parts_used must be a list, got '
            f'{type(parts_saved).__name__}')
    strand   = Strand(genome, n_bases)
    supply   = _env_supply(env_name)
    org      = Organism(strand=strand, env_name=env_name)
    org.express(supply, deterministic=True)
    # Re-inject parts that were directly injected at build time (neural /
    # homeostasis / organelle parts are not genome-encodable, so express()
    # alone drops them and the reloaded organism loses real subsystems).
    bp = org.blueprint
    if bp is None:
        org.evaluate()
        return org, data
    expressed = set(bp.parts_used)
    missing = [p for p in parts_saved if p not in expressed]
    if missing:
        for pname in missing:
            _inject_blueprint_part(bp, pname)
        _rescore_after_injection(org, bp, supply)
    else:
        org.evaluate()
    return org, data


# ---------------------------------------------------------------------------
# Real Micro-organism Templates
# ---------------------------------------------------------------------------
# These genomes are inspired by real organisms' functional organisation.
# They are NOT literal DNA sequences — they are structured genomes in the
# Periodic Machine language that encode the same functional subsystems.
#
# References:
#  - M. genitalium (smallest self-replicating bacterium, 473 genes)
#    Fraser et al., Science 1995; Hutchison et al., Science 2016
#  - E. coli K-12 (model bacterium, ~4300 genes)
#    Blattner et al., Science 1997
#  - Phi-X174 (smallest dsDNA bacteriophage, 11 genes, 5386 bp)
#    Sanger et al., Nature 1977

def _make_microbe_genome(parts_sequence: list, n_bases: int = 8) -> str:
    """Build a genome string from an ordered list of part names + opcodes.

    Uses the exact W/Z second-base dispatch from LanguageSpec._decode_opcode_legacy
    so every codon round-trips correctly through codon_to_instruction.

    Dispatch (8-base, bases = A T C G X Y W Z):
      First base A/G → BUILD,  T/C → CONNECT,  X → REPEAT,  Y → REGULATE
      W prefix: second = A/T→MOTOR, C/G→LOCALIZE, X→POLYMERIZE, Y→PHASE,
                                    W→CHEMOTAXIS, Z→MEMBRANE_INS
      Z prefix: second = A/T→SECRETE, C/G→QUORUM, X→DIVIDE, Y→METABOLIZE,
                                       W→GRADIENT, Z→PROMOTER
      Operand = sum(ord(c) for c in codon[1:])  — use 'AAAA' tail for operand 0
    """
    if n_bases not in BASE_SYSTEMS:
        n_bases = 8
    bases = BASE_SYSTEMS[n_bases]['bases']
    nb    = len(bases)

    # The interpreter computes: operand = sum(ord(c) for c in codon[1:])
    # then part = TABLE[operand % len(TABLE)].
    # We need to engineer the 4 trailing chars (codon[1:]) so that
    #   sum(ord(trailing)) % table_len == desired_index.
    # Complete search over bases^4 — the previous 1/2-char solver with fixed
    # leading 'A's could not reach every residue (e.g. 'filament' idx 2 in
    # 4-base fell back to 'AAA' and silently built 'glucose' instead).

    def _solve_tail(first_chars: Optional[str], desired_idx: int,
                    table_len: int) -> Optional[str]:
        """Return a 4-char tail (codon[1:]) using only valid bases such that
        sum(ord(tail)) % table_len == desired_idx.  `first_chars` optionally
        restricts tail[0] (motor codons need A/T to keep the W+modifier = MOTOR).
        Returns None when the residue is unreachable in this alphabet — e.g.
        in 4-base ATCG the ord-residues {3,14,16} can only reach 12/17 BUILD
        indices, so wall/atp/coenzyme_a/formaldehyde/phosphate are unencodable."""
        c0s = first_chars if first_chars else ''.join(bases)
        for c0 in c0s:
            for c1 in bases:
                for c2 in bases:
                    for c3 in bases:
                        if (ord(c0) + ord(c1) + ord(c2) + ord(c3)) % table_len == desired_idx:
                            return c0 + c1 + c2 + c3
        return None

    def _noop_codon() -> str:
        """A codon that decodes to an inert no-op in this alphabet.
        'TG' pair -> NOOP in 4+ bases (v2.2 carve-out); in binary there is
        no NOOP — CONNECT is the only instruction that adds no parts."""
        if nb >= 4:
            return bases[1] + bases[3] + bases[0] * (CODON_LEN - 2)   # 'TG...' → NOOP
        return bases[1] + bases[0] * (CODON_LEN - 1)                  # CONNECT

    def _build_codon(operand: int) -> str:
        # A-prefix: codon = A + (4 chars), codon[1:] = 4 chars
        # operand % len(BUILD_PART_NAMES) must == operand arg
        tail = _solve_tail(None, operand % len(BUILD_PART_NAMES),
                           len(BUILD_PART_NAMES))
        # Unreachable residue -> honest NOOP.  The old 'AAAA' fallback decoded
        # to BUILD:glucose — silently fabricating a part never requested.
        return bases[0] + tail if tail else _noop_codon()

    def _connect_codon() -> str:
        return bases[1] + bases[0] * (CODON_LEN - 1)      # T-prefix → CONNECT

    def _motor_codon(operand: int) -> str:
        if nb < 8:
            # No W/Z bases exist below 8 — a BUILD fallback would fabricate
            # an unrelated part; emit a no-op (part injected downstream).
            return _noop_codon()
        # codon[1:] must start with A or T so W+modifier keeps MOTOR
        tail = _solve_tail('AT', operand % len(MOTOR_PART_NAMES),
                           len(MOTOR_PART_NAMES))
        return 'W' + tail if tail else _noop_codon()

    def _w_codon(second: str) -> str:
        """W + modifier opcodes (LOCALIZE/POLYMERIZE/PHASE/MEMBRANE_INS) —
        operand is unused by these opcodes, so the tail is inert."""
        if nb < 8:
            return _noop_codon()
        return 'W' + second + bases[0] * (CODON_LEN - 2)

    def _z_codon(second: str) -> str:
        """Z + modifier opcodes (SECRETE/QUORUM/DIVIDE/METABOLIZE/GRADIENT/
        PROMOTER) — operand unused.  Fallback must be a REAL no-op:
        'AAAAA' decodes to BUILD:glucose (260 % 17 = 5), not NOOP."""
        if nb < 8:
            return _noop_codon()
        return 'Z' + second + bases[0] * (CODON_LEN - 2)

    codons = []
    for item in parts_sequence:
        if item == 'PROMOTER':
            # 'CC' prefix -> PROMOTER in every alphabet >= 4 (v2.2 carve-out)
            if nb >= 4:
                codons.append(bases[2] + bases[2] + bases[0] * (CODON_LEN - 2))
            else:
                codons.append(_noop_codon())
        elif item == 'TERMINATOR':
            # 'TT' prefix -> TERMINATOR in every alphabet >= 4
            if nb >= 4:
                codons.append(bases[1] + bases[1] + bases[0] * (CODON_LEN - 2))
            else:
                codons.append(_noop_codon())
        elif item == 'CONNECT':
            codons.append(_connect_codon())
        elif item == 'NOOP':
            codons.append(_noop_codon())
        elif item == 'REPEAT':
            codons.append('X' + bases[0] * (CODON_LEN - 1) if nb >= 6 else _noop_codon())
        elif item == 'REGULATE':
            codons.append('Y' + bases[0] * (CODON_LEN - 1) if nb >= 6 else _noop_codon())
        elif item == 'METABOLIZE':
            codons.append(_z_codon('Y'))           # Z+Y → METABOLIZE
        elif item == 'SECRETE':
            codons.append(_z_codon('A'))           # Z+A → SECRETE
        elif item == 'QUORUM':
            codons.append(_z_codon('C'))           # Z+C → QUORUM
        elif item == 'DIVIDE':
            codons.append(_z_codon('X'))           # Z+X → DIVIDE
        elif item == 'GRADIENT':
            codons.append(_z_codon('W'))           # Z+W → GRADIENT
        elif item == 'CHEMOTAXIS':
            codons.append(_w_codon('W'))           # W+W → CHEMOTAXIS
        elif item == 'LOCALIZE':
            codons.append(_w_codon('C'))           # W+C → LOCALIZE
        elif item == 'POLYMERIZE':
            codons.append(_w_codon('X'))           # W+X → POLYMERIZE
        elif item == 'PHASE':
            codons.append(_w_codon('Y'))           # W+Y → PHASE
        elif item == 'MEMBRANE_INS':
            codons.append(_w_codon('Z'))           # W+Z → MEMBRANE_INS
        elif item in BUILD_PART_NAMES:
            codons.append(_build_codon(BUILD_PART_NAMES.index(item)))
        elif item in MOTOR_PART_NAMES:
            codons.append(_motor_codon(MOTOR_PART_NAMES.index(item)))
        else:
            # Spec item with no codon representation (e.g. 'actin'/'tubulin'
            # in PARTS_KB but outside BUILD/MOTOR tables) — keep a no-op slot
            # so codons stay 1:1 with the requested program; real parts are
            # injected in build_microbe_organism().
            codons.append(_noop_codon())
    return ''.join(codons)


