            m.insert('end', f"  Fasting switch:       glycogen →GNG ~{GLUCOSE['liver_glycogen_g']/(GLUCOSE['brain_g_day']/24):.0f} h "
                            "→ketosis ~day 3\n", 'dim')
            m.insert('end', "\nGROWTH PHYSIOLOGY (Monod/Pirt)\n", 'h2')
            g_sat = monod_growth(5.0); g_lim = monod_growth(GROWTH['Ks_glucose_mM'])
            m.insert('end', f"  Monod (E. coli/glucose):  μmax={GROWTH['mu_max_per_h']:.1f}/h, "
                            f"Ks={GROWTH['Ks_glucose_mM']:.2f} mM\n", 'val')
            m.insert('end', f"    at Ks:      μ={g_lim['mu_per_h']:.2f}/h "
                            f"(td={g_lim['doubling_min']:.0f} min — half-max by definition)\n", 'dim')
            m.insert('end', f"    saturating: μ={g_sat['mu_per_h']:.2f}/h "
                            f"(td={g_sat['doubling_min']:.0f} min)\n", 'val')
            y_a = GROWTH['yield_g_per_g_aerobic']
            m.insert('end', f"  Yield coefficient:  {y_a:.2f} g cells/g glucose aerobic "
                            f"(~{GROWTH['yield_g_per_g_anaerobic']:.2f} anaerobic)\n", 'val')
            me_slow = maintenance_energy_fraction(0.05)
            me_fast = maintenance_energy_fraction(GROWTH['mu_max_per_h'])
            m.insert('end', f"  Maintenance (Pirt): {me_fast*100:.0f}% of substrate at μmax "
                            f"vs {me_slow*100:.0f}% at slow growth\n", 'dim')
            phys = ENV_PHYSICS.get(org.env_name, ENV_PHYSICS['earth'])
            temp_c = phys['temp_K'] - 273.15
            m.insert('end', f"  Env {org.env_name}: {phys['temp_K']:.0f} K "
                            f"({temp_c:.0f} °C)  η={phys['viscosity_Pa_s']*1000:.1f} mPa·s\n", 'val')
            m.insert('end', f"  Q10(2) rate vs 37 °C:  ×{q10_factor(2.0, temp_c):.3f}\n", 'val')
            m.insert('end', f"  Arrhenius(Ea=50 kJ):   ×{arrhenius_factor(50, phys['temp_K']):.3f}\n", 'val')
            d_prot = diffusion_coefficient(3.0, phys['temp_K'], phys['viscosity_Pa_s'])
